#!/bin/bash
# =============================================================================
# DCS Orchestrator — REST API Server
# Lightweight HTTP/JSON API for remote management, served by socat or ncat.
# Each connection is handled by a fresh `--handle-request` instance of this
# script: handlers are plain bash functions that read the request on stdin and
# write the HTTP response to stdout.
#
# Usage:
#   ./api-server.sh [--port PORT] [--bind ADDR] [--daemon] [--stop] [--help]
#
# Endpoint reference: docs/API.md — generated from the router at the bottom of
# this file by .scripts/api-docs.sh (run it after adding or changing a route).
#
# Security model (details in SECURITY.md):
#   - Authentication is mandatory unless the listener is bound to loopback.
#   - Bearer tokens over PBKDF2-hashed passwords, optional TOTP, invite-only
#     registration, per-client rate limits and login lockouts.
#   - Two roles: "user" (read-only viewer) and "admin" (everything else).
#   - Compose content is scanned for container-escape vectors before it is
#     written or deployed; .env is read as data, never sourced.
# =============================================================================

set -euo pipefail

# =============================================================================
# PATH AUTO-DETECTION
# =============================================================================

if [[ -z "${BASE_DIR:-}" ]]; then
    _API_SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    BASE_DIR="$(cd "$_API_SCRIPT_DIR/.." && pwd)"
    unset _API_SCRIPT_DIR
fi

# Keys that must never be set from .env: they change how bash or the dynamic
# loader behave for every command this server runs.
_API_ENV_RESERVED_KEYS='PATH|IFS|PS4|ENV|BASH_ENV|BASH_XTRACEFD|SHELLOPTS|BASHOPTS|CDPATH|GLOBIGNORE|PROMPT_COMMAND|LD_PRELOAD|LD_LIBRARY_PATH|LD_AUDIT|BASE_DIR|HANDLE_REQUEST|DAEMON_MODE|STOP_SERVER'

# Load a .env file as DATA, never as code. Only `KEY=value` lines are accepted,
# values are taken literally (matching surrounding quotes are stripped) and
# reserved keys are ignored. Sourcing the file would turn write access to .env
# (which the API grants to admins) into command execution on the host.
_api_load_env_file() {
    local file="$1" line key val
    [[ -f "$file" ]] || return 0
    while IFS= read -r line || [[ -n "$line" ]]; do
        line="${line%%$'\r'}"
        [[ -z "${line//[[:space:]]/}" || "$line" =~ ^[[:space:]]*# ]] && continue
        [[ "$line" =~ ^[[:space:]]*(export[[:space:]]+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]] || continue
        key="${BASH_REMATCH[2]}"
        val="${BASH_REMATCH[3]}"
        [[ "$key" =~ ^(${_API_ENV_RESERVED_KEYS})$ || "$key" == BASH_FUNC_* ]] && continue
        if [[ ${#val} -ge 2 && "$val" == \"*\" ]]; then
            val="${val:1:${#val}-2}"
            # inside double quotes bash reads \\ \" \$ \` as the bare character
            [[ "$val" == *\\* ]] && val=$(printf '%s' "$val" | sed 's/\\\([\\"$`]\)/\1/g')
        elif [[ ${#val} -ge 2 && "$val" == \'*\' ]]; then
            val="${val:1:${#val}-2}"
        else
            val="${val%%[[:space:]]#*}"
            val="${val%"${val##*[![:space:]]}"}"
        fi
        export "$key=$val"
    done < "$file"
}

# Validate .env content before it is written by the API (raw editor, config
# update, setup wizard). Prints the first problem and returns 1 on rejection.
_api_validate_env_content() {
    local content="$1" line n=0 key val
    while IFS= read -r line || [[ -n "$line" ]]; do
        n=$(( n + 1 ))
        line="${line%%$'\r'}"
        [[ -z "${line//[[:space:]]/}" || "$line" =~ ^[[:space:]]*# ]] && continue
        if [[ ! "$line" =~ ^[[:space:]]*(export[[:space:]]+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]]; then
            echo "line $n is not KEY=value"
            return 1
        fi
        key="${BASH_REMATCH[2]}"
        val="${BASH_REMATCH[3]}"
        if [[ "$key" =~ ^(${_API_ENV_RESERVED_KEYS})$ || "$key" == BASH_FUNC_* ]]; then
            echo "line $n sets reserved variable $key"
            return 1
        fi
        if [[ "$val" == *'$('* || "$val" == *'`'* || "$val" =~ [[:cntrl:]] ]]; then
            echo "line $n: values may not contain command substitution or control characters"
            return 1
        fi
    done <<< "$content"
    return 0
}

# Validate a single KEY=value pair destined for .env
_api_validate_env_kv() {
    local key="$1" val="$2"
    [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || { echo "invalid key '$key'"; return 1; }
    [[ "$key" =~ ^(${_API_ENV_RESERVED_KEYS})$ || "$key" == BASH_FUNC_* ]] && { echo "reserved variable $key"; return 1; }
    [[ "$val" == *'$('* || "$val" == *'`'* || "$val" =~ [[:cntrl:]] ]] && { echo "value of $key contains command substitution or control characters"; return 1; }
    return 0
}

_api_load_env_file "$BASE_DIR/.env"

COMPOSE_DIR="${COMPOSE_DIR:-$BASE_DIR/Stacks}"
APP_DATA_DIR="${APP_DATA_DIR:-$BASE_DIR/App-Data}"

# =============================================================================
# CONFIGURATION
# =============================================================================

# The server process exports the values it actually listens with; per-request
# handlers (spawned by socat) take those over anything in .env so that every
# process agrees on the bind address, port and authentication policy.
API_PORT="${DCS_API_EFFECTIVE_PORT:-${API_PORT:-9876}}"
API_BIND="${DCS_API_EFFECTIVE_BIND:-${API_BIND:-127.0.0.1}}"
API_VERSION="1.17.0"
DCS_VERSION="$(cat "${BASE_DIR}/VERSION" 2>/dev/null || echo "unknown")"

# Plugin system
PLUGINS_DIR="${BASE_DIR}/.plugins"
PLUGINS_HOOKS_ENABLED="${PLUGINS_HOOKS_ENABLED:-true}"
API_PID_FILE="${BASE_DIR}/.data/api-server.pid"
API_CAPS_FILE="${BASE_DIR}/.data/api-server.caps"
POWER_STATE_FILE="${BASE_DIR}/.data/power.json"
POWER_PID_FILE="${BASE_DIR}/.data/power.pid"
SELF_UPDATE_LOCK="${BASE_DIR}/.data/self-update.lock"
SELF_UPDATE_LOG="${BASE_DIR}/logs/self-update.log"
IMAGE_UPDATE_LOCK="${BASE_DIR}/.data/image-update.lock"
IMAGE_UPDATE_LOG="${BASE_DIR}/logs/image-update.log"
API_LOG_FILE="${BASE_DIR}/logs/api-server.log"

# Authentication configuration
API_AUTH_DIR="${BASE_DIR}/.api-auth"
API_TOKEN_EXPIRY="${API_TOKEN_EXPIRY:-86400}"       # 24 hours in seconds
API_INVITE_EXPIRY="${API_INVITE_EXPIRY:-604800}"     # 7 days in seconds
API_MAX_LOGIN_ATTEMPTS="${API_MAX_LOGIN_ATTEMPTS:-5}"
API_LOCKOUT_DURATION="${API_LOCKOUT_DURATION:-900}"  # 15 minutes in seconds

# Authentication policy — resolved by _api_resolve_auth_policy once the command
# line has been parsed (so --bind counts) and exported to the request handlers.
#
#   Loopback bind (127.x / localhost / ::1): auth optional, off unless enabled.
#   Any other bind address: auth is mandatory. API_AUTH_ENABLED=false is ignored
#   there unless API_INSECURE_NO_AUTH=true is ALSO set, because an open API on a
#   reachable interface hands out full control of the Docker host.
API_AUTH_ENABLED="${DCS_API_EFFECTIVE_AUTH:-${API_AUTH_ENABLED:-}}"
API_INSECURE_NO_AUTH="${API_INSECURE_NO_AUTH:-false}"
API_AUTH_FORCED="false"
SETUP_MODE="${DCS_API_SETUP_MODE:-false}"

# The role of this installation (DCS_ROLE in .env, written by setup.sh). "hub" is the default and the full DCS: the
# API, the dashboard, accounts and the setup wizard; a standalone server is a hub without members. "node" is the API
# alone, managed from its hub's dashboard: no dashboard, no accounts of its own, no wizard and no first-admin gate.
# Joining a node to a hub creates only the account the hub uses on it (FLEET_HUB_ACCOUNT), and nothing else ever
# signs in there.
DCS_ROLE="${DCS_ROLE:-hub}"
[[ "$DCS_ROLE" == "node" ]] || DCS_ROLE="hub"
_api_is_node() { [[ "$DCS_ROLE" == "node" ]]; }

# Peers listed here (comma-separated IPs/CIDRs) are trusted to set
# X-Forwarded-For. The DCS-UI container proxies browser traffic to this API,
# so without it every UI user would share one rate-limit bucket and one
# login-lockout counter, and audit logs would only ever show the container IP.
API_TRUSTED_PROXIES="${API_TRUSTED_PROXIES:-}"

_api_bind_is_loopback() {
    case "$1" in
        127.*|localhost|::1|'') return 0 ;;
        *) return 1 ;;
    esac
}

_api_resolve_auth_policy() {
    if _api_bind_is_loopback "$API_BIND"; then
        [[ -z "$API_AUTH_ENABLED" ]] && API_AUTH_ENABLED="false"
    elif [[ "$API_AUTH_ENABLED" != "true" ]]; then
        if [[ "$API_INSECURE_NO_AUTH" == "true" ]]; then
            API_AUTH_ENABLED="false"
        else
            API_AUTH_ENABLED="true"
            API_AUTH_FORCED="true"
        fi
    fi
    [[ "$API_AUTH_ENABLED" == "true" ]] || API_AUTH_ENABLED="false"
    export DCS_API_EFFECTIVE_AUTH="$API_AUTH_ENABLED"
    export DCS_API_EFFECTIVE_BIND="$API_BIND"
    export DCS_API_EFFECTIVE_PORT="$API_PORT"
    export DCS_API_SETUP_MODE="$SETUP_MODE"
}

# IP Whitelist — comma-separated list of allowed IPs/CIDRs (empty = allow all)
# Example: API_IP_WHITELIST="192.168.1.0/24,10.0.0.5"
API_IP_WHITELIST="${API_IP_WHITELIST:-}"

# PBKDF2 password hashing iterations
API_PBKDF2_ITERATIONS="${API_PBKDF2_ITERATIONS:-100000}"

# CORS allowed origins (comma-separated, empty = localhost only)
API_CORS_ORIGINS="${API_CORS_ORIGINS:-}"
_API_CORS_PUBLIC=""  # set per request for the discovery answers (_api_cors_lines), never from the environment

# Whether the API runs behind a TLS-terminating proxy (enables HSTS header)
API_BEHIND_TLS_PROXY="${API_BEHIND_TLS_PROXY:-false}"

# TLS/HTTPS support — direct TLS termination via socat OPENSSL-LISTEN
API_TLS_ENABLED="${API_TLS_ENABLED:-false}"
API_TLS_CERT="${API_TLS_CERT:-$BASE_DIR/.api-auth/server.crt}"
API_TLS_KEY="${API_TLS_KEY:-$BASE_DIR/.api-auth/server.key}"

# Single-session enforcement (revoke old tokens on new login)
API_SINGLE_SESSION="${API_SINGLE_SESSION:-true}"

# Request body size limit (bytes) — 1 MB default
API_MAX_BODY_SIZE="${API_MAX_BODY_SIZE:-1048576}"
# The largest backup archive or recovery bundle sent as the request body itself (POST /backups/upload, its VM variant through
# a hub, POST /recovery/upload): streamed to disk as it arrives, never held in memory. 20 GiB by default; every other route
# keeps its small limit (API_MAX_BODY_SIZE; API_MAX_UPLOAD_SIZE, 128 MB, for a bundle sent as JSON: the setup wizard's)
API_MAX_BACKUP_UPLOAD_SIZE="${API_MAX_BACKUP_UPLOAD_SIZE:-21474836480}"
[[ "$API_MAX_BACKUP_UPLOAD_SIZE" =~ ^[0-9]{1,15}$ ]] || API_MAX_BACKUP_UPLOAD_SIZE=21474836480

# Global rate limiting — max requests per minute per IP (0 = disabled)
API_RATE_LIMIT="${API_RATE_LIMIT:-600}"
API_RATE_WINDOW="${API_RATE_WINDOW:-60}"  # window in seconds

# Max simultaneous connections the listener accepts (socat max-children, ncat -m).
# Beyond it new connections queue in the kernel backlog instead of each fork
# re-parsing this script — a ceiling on fork-bomb and slow-drip damage.
API_MAX_CHILDREN="${API_MAX_CHILDREN:-64}"

# Rate limit tracking directory
API_RATE_DIR="${API_RATE_DIR:-$BASE_DIR/.data/rates}"
[[ -d "$API_RATE_DIR" ]] || mkdir -p "$API_RATE_DIR" 2>/dev/null

# API server start time (epoch) — used by /health for uptime & request counters
API_START_EPOCH="$(date +%s)"
API_STATS_FILE="${API_STATS_FILE:-$BASE_DIR/.data/api-stats}"
# Initialize stats file (request count, error count) — shared across forked handlers
[[ -f "$API_STATS_FILE" ]] || printf '0\n0\n' > "$API_STATS_FILE"

# =============================================================================
# DOCKER COMPOSE DETECTION
# =============================================================================

# Detected once by the listener and exported, so the handler that socat forks
# for every request inherits it instead of asking the daemon again (~25 ms).
if [[ -z "${DOCKER_COMPOSE_CMD:-}" ]]; then
    if docker compose version >/dev/null 2>&1; then
        DOCKER_COMPOSE_CMD="docker compose"
    elif command -v docker-compose >/dev/null 2>&1; then
        DOCKER_COMPOSE_CMD="docker-compose"
    else
        echo "Error: No Docker Compose found" >&2
        exit 1
    fi
fi
export DOCKER_COMPOSE_CMD
# Exported so the per-request processes skip the detection (one docker CLI
# round-trip per request otherwise).
export DOCKER_COMPOSE_CMD

# =============================================================================
# ARGUMENT PARSING
# =============================================================================

DAEMON_MODE=false
STOP_SERVER=false
HANDLE_REQUEST=false
WORKER_MODE=false; WORKER_SOCK=""
FLEET_CLI=""

# Only when executed: a script that sources this file for its functions
# (tests, tooling) must not have its own arguments parsed as server options.
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    _API_ARGV=("$@")
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --handle-request) HANDLE_REQUEST=true; shift ;;
            --worker) WORKER_MODE=true; WORKER_SOCK="$2"; shift 2 ;;      # one of the server's own worker processes (started by start_server, never by hand)
            --port)    API_PORT="$2"; shift 2 ;;
            --bind)    API_BIND="$2"; shift 2 ;;
            --daemon)  DAEMON_MODE=true; shift ;;
            --stop)    STOP_SERVER=true; shift ;;
            --setup-mode) SETUP_MODE=true; shift ;;
            --self-update) SELF_UPDATE_JOB=true; shift ;;
            --images)  SELF_UPDATE_IMAGES=true; shift ;;
            --image-update) IMAGE_UPDATE_JOB=true; shift ;;
            --pull-only) IMAGE_UPDATE_PULL_ONLY=true; shift ;;
            --os-updates-check) OS_UPDATES_JOB=true; shift ;;
            --join-hub)
                FLEET_CLI="join"; FLEET_CLI_HUB="${2:-}"; FLEET_CLI_TOKEN="${3:-}"
                shift 3 2>/dev/null || shift $#
                if [[ $# -gt 0 && "${1:-}" != --* ]]; then FLEET_CLI_NAME="$1"; shift; fi ;;
            --join-token) FLEET_CLI="token"; shift; if [[ $# -gt 0 && "${1:-}" =~ ^[0-9]+$ ]]; then FLEET_CLI_TTL="$1"; shift; fi ;;
            --join-token-quiet) FLEET_CLI="token"; FLEET_CLI_QUIET=true; shift ;;
            --fleet-status) FLEET_CLI="status"; shift ;;
            --fleet-jobs-runner) FLEET_CLI="runner"; shift ;;
            --help|-h)
                cat <<EOF
DCS Orchestrator — REST API Server v${API_VERSION}

Usage: $0 [OPTIONS]

Options:
  --port PORT     Port to listen on (default: ${API_PORT})
  --bind ADDR     Bind address (default: ${API_BIND})
  --daemon        Run in background (daemonize)
  --stop          Stop a running daemon
  --join-hub URL CODE [NAME]
                  Make this server a member of the DCS hub at URL (CODE is a
                  join code from the hub's Proxmox page or --join-token)
  --join-token [HOURS]
                  Mint a join code on this hub (valid 24 h by default)
  --fleet-status  Print the hub, members and join codes this server knows
  --os-updates-check
                  Look at the waiting OS updates now (unprivileged) and print it
  --help, -h      Show this help message

The API provides JSON endpoints for managing Docker Compose stacks,
containers, images, and system resources. Designed as the backend
for the Electron desktop application.

Requires: socat or ncat (netcat with -e support)
EOF
                exit 0
                ;;
            *) echo "Unknown option: $1" >&2; exit 1 ;;
        esac
    done
fi

_api_resolve_auth_policy

# =============================================================================
# DAEMON MANAGEMENT
# =============================================================================

# PIDs of processes listening on a TCP port (ss preferred, lsof fallback)
_api_port_listeners() {
    local port="$1" pids=""
    if command -v ss >/dev/null 2>&1; then
        pids=$(ss -Hltnp "sport = :${port}" 2>/dev/null | grep -oE 'pid=[0-9]+' | cut -d= -f2 | sort -u | tr '\n' ' ')
    fi
    if [[ -z "${pids// /}" ]] && command -v lsof >/dev/null 2>&1; then
        pids=$(lsof -ti "tcp:${port}" -sTCP:LISTEN 2>/dev/null | tr '\n' ' ')
    fi
    printf '%s' "${pids% }"
}

# Every request handler is a child of the listener and inherits its descriptors; ncat keeps its listening socket
# open in each of them. A helper that a request leaves running (the DDNS loop that a settings change or the wizard
# starts, a stream, an update job) would then hold the port after the listener is gone, and the API could not start
# again ("port 9876 is already in use by PID ...: sleep 300"). A handler needs the connection (0, 1, 2) and bash's
# own copy of the script (255), nothing else.
_api_close_inherited_fds() {
    local p fd
    for p in /proc/self/fd/*; do
        fd="${p##*/}"
        [[ "$fd" =~ ^[0-9]+$ ]] || continue
        (( fd > 2 && fd < 255 )) || continue
        eval "exec ${fd}>&-" 2>/dev/null || true
    done
}

# The port is still held when this listener starts. This process replaced an older listener (an update or
# POST /system/restart re-executes the API in place, same PID), and what holds the port is what that one left
# behind: it has not finished closing (wait a moment), or a helper that one of its request handlers started still
# runs with the listening socket it inherited (before 3.9.9 every helper kept it: the DDNS loop's 300 s sleep was
# enough to keep the API from coming back after an update). Such a helper is a shell utility in this service's own
# cgroup and is ended; another program on the port, or another installation's listener, is left alone.
# Returns 0 when the port is free afterwards.
_api_reclaim_port() {
    local port="$1" i h comm mycg hcg
    local -a ended=()
    for i in $(seq 1 15); do
        [[ -z "$(_api_port_listeners "$port")" ]] && return 0
        sleep 0.2
    done
    mycg=$(cat "/proc/${BASHPID:-$$}/cgroup" 2>/dev/null || true)
    for h in $(_api_port_listeners "$port"); do
        [[ "$h" == "$$" || "$h" == "${BASHPID:-$$}" ]] && continue
        hcg=$(cat "/proc/$h/cgroup" 2>/dev/null || true)
        [[ -n "$mycg" && "$hcg" == "$mycg" ]] || continue
        comm=$(cat "/proc/$h/comm" 2>/dev/null || true)
        case "$comm" in
            sleep|api-server.sh|bash|sh|dash|docker|curl|jq|awk|gawk|sed|cat|tail|timeout|ssh|openssl|git|wget) ;;
            *) continue ;;
        esac
        kill -TERM "$h" 2>/dev/null && ended+=("$h:$comm")
    done
    [[ ${#ended[@]} -gt 0 ]] || return 1
    for i in $(seq 1 15); do
        [[ -z "$(_api_port_listeners "$port")" ]] && break
        sleep 0.2
    done
    if [[ -n "$(_api_port_listeners "$port")" ]]; then
        for h in "${ended[@]}"; do kill -KILL "${h%%:*}" 2>/dev/null || true; done
        sleep 0.5
    fi
    printf '  Freed port %s: ended %d helper(s) left over from the previous listener (%s)\n' "$port" "${#ended[@]}" "${ended[*]}"
    [[ -z "$(_api_port_listeners "$port")" ]]
}

# _api_pid_is_ours PID — 0 when that process runs this installation's API script, however it was started: with the absolute path or
# with a relative one (.scripts/api-server.sh --bind …, as CLAUDE.md shows), which its command line only holds relative to its directory
_api_pid_is_ours() {
    local pid="$1" tok cwd
    [[ "$pid" =~ ^[0-9]+$ && -r "/proc/$pid/cmdline" ]] || return 1
    cwd=$(readlink "/proc/$pid/cwd" 2>/dev/null)
    while IFS= read -r tok; do
        [[ "$tok" == *api-server.sh ]] || continue
        [[ "$tok" == /* ]] || tok="$cwd/$tok"
        [[ "$(realpath -m "$tok" 2>/dev/null)" == "$_self_path" ]] && return 0
    done < <(tr '\0' '\n' < "/proc/$pid/cmdline" 2>/dev/null)
    return 1
}
if [[ "$STOP_SERVER" == "true" ]]; then
    stopped=false
    _self_path="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
    if [[ -f "$API_PID_FILE" ]]; then
        pid=$(cat "$API_PID_FILE" 2>/dev/null)
        # the pid file is trusted only when that process really is this installation's server:
        # a copied .data/ (or a reused pid) must never point --stop at someone else's process
        _pidcmd=""; [[ "$pid" =~ ^[0-9]+$ ]] && _pidcmd=$(tr '\0' ' ' < "/proc/${pid}/cmdline" 2>/dev/null || true)
        if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null && [[ "$_pidcmd" != *"$_self_path"* && "$_pidcmd" != *"$BASE_DIR/.scripts/api-server.sh"* ]] && ! _api_pid_is_ours "$pid"; then
            echo "PID file points at PID $pid (${_pidcmd:0:70}), which is not this installation's API server — ignored"
            pid=""
        fi
        if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
            # SIGTERM lets the server's trap stop the listener and its helpers
            kill -TERM "$pid" 2>/dev/null
            for _ in $(seq 1 50); do
                kill -0 "$pid" 2>/dev/null || break
                sleep 0.1
            done
            if kill -0 "$pid" 2>/dev/null; then
                pkill -KILL -P "$pid" 2>/dev/null || true
                kill -KILL "$pid" 2>/dev/null || true
            fi
            echo "API server stopped (PID $pid)"
            stopped=true
        fi
        rm -f "$API_PID_FILE"
    fi

    # Fallback: an orphaned DCS listener still bound to the port (older
    # version, or a server started without a PID file). Anything else that
    # owns the port — another program, or another DCS installation — is
    # reported, never killed.
    _leftover=$(_api_port_listeners "$API_PORT")
    for _p in $_leftover; do
        _cmd=$(tr '\0' ' ' < "/proc/${_p}/cmdline" 2>/dev/null || true)
        # the listener is a socat whose parent is this script: match either the
        # process or its parent against this installation's script path
        _pcmd=$(tr '\0' ' ' < "/proc/$(awk '{print $4}' "/proc/${_p}/stat" 2>/dev/null)/cmdline" 2>/dev/null || true)
        if [[ "$_cmd" == *"$_self_path"* || "$_pcmd" == *"$_self_path"* || "$_cmd" == *"$BASE_DIR/.scripts/api-server.sh"* || "$_pcmd" == *"$BASE_DIR/.scripts/api-server.sh"* ]] || _api_pid_is_ours "$_p" || _api_pid_is_ours "$(awk '{print $4}' "/proc/${_p}/stat" 2>/dev/null)"; then
            kill -TERM "$_p" 2>/dev/null || true
            sleep 0.5
            kill -KILL "$_p" 2>/dev/null || true
            echo "Stopped orphaned listener on port ${API_PORT} (PID ${_p})"
            stopped=true
        else
            echo "Port ${API_PORT} is held by PID ${_p} (${_cmd:0:70}) — not this installation's API server, left running"
        fi
    done
    # Long-lived request handlers (SSE and log streams) outlive the listener.
    # They belong to this installation (matched by this script's absolute
    # path), so end them as well.
    _self="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
    _self_re=$(printf '%s' "$_self" | sed 's/[][\.*^$+?(){}|]/\\&/g')
    if pkill -TERM -f -- "${_self_re} --handle-request$" 2>/dev/null; then
        echo "Stopped lingering request handlers"
        stopped=true
    fi
    [[ "$stopped" == "false" ]] && echo "API server is not running"
    exit 0
fi

# =============================================================================
# DEPENDENCY CHECK
# =============================================================================

LISTENER_CMD=""
if command -v socat >/dev/null 2>&1; then
    LISTENER_CMD="socat"
elif command -v ncat >/dev/null 2>&1; then
    LISTENER_CMD="ncat"
else
    echo "Error: Neither 'socat' nor 'ncat' found. Install one:" >&2
    echo "  sudo apt install socat       # Debian/Ubuntu" >&2
    echo "  sudo dnf install socat       # Fedora/RHEL" >&2
    echo "  sudo pacman -S socat         # Arch" >&2
    exit 1
fi

if ! command -v jq >/dev/null 2>&1; then
    echo "ERROR: jq is required for API authentication security." >&2
    echo "Install: sudo apt install jq  |  sudo dnf install jq  |  sudo pacman -S jq" >&2
    exit 1
fi

# =============================================================================
# JSON HELPERS
# =============================================================================

# Escape a string for safe JSON embedding (handles all control characters)
_api_json_escape() {
    local str="$1"
    # First strip ANSI escape sequences before doing JSON escaping
    # Use perl if available (most reliable), otherwise sed
    if command -v perl >/dev/null 2>&1; then
        str=$(printf '%s' "$str" | perl -pe 's/\e\[[0-9;]*[a-zA-Z]//g; s/\e\][^\a]*\a//g; s/[\x00-\x08\x0B\x0C\x0E-\x1F]//g' 2>/dev/null) || true
    fi
    str="${str//\\/\\\\}"      # backslash
    str="${str//\"/\\\"}"      # double quote
    str="${str//$'\n'/\\n}"    # newline
    str="${str//$'\r'/\\r}"    # carriage return
    str="${str//$'\t'/\\t}"    # tab
    printf '%s' "$str"
}

# Escape a value for use as sed replacement text (handles / \ &)
_sed_escape_val() {
    local v="$1"
    v="${v//\\/\\\\}"   # escape backslashes first
    v="${v//\//\\/}"     # escape forward slashes
    v="${v//&/\\&}"      # escape ampersands
    printf '%s' "$v"
}

# The machine's name and first address without the hostname command: Arch's minimal image has none (and its inetutils has no -I)
_hostname() {
    local h; h=$(cat /proc/sys/kernel/hostname 2>/dev/null) || h=""
    [[ -n "$h" ]] || h=$(uname -n 2>/dev/null) || h=""
    printf '%s' "${h:-${1:-}}"
}
_primary_ip() { ip -4 -o addr show scope global 2>/dev/null | awk '{sub(/\/.*/, "", $4); print $4; exit}'; }

# The CORS response headers for this request's Origin (nothing for a request without one or from an origin that is not allowed).
# The response writer and the response cache both use it: a cached answer must carry the CORS headers of the request it is
# served to, not those of the request that filled the cache.
# The two discovery answers (GET /ping and the catalogue GET /, both public, _API_CORS_PUBLIC) may be read from any origin
# ("*", no credentials involved): a web dashboard on another domain can always tell that a DCS server lives at an address,
# and then whether this server lets it in (every other answer keeps API_CORS_ORIGINS).
_api_cors_lines() {
    if [[ -n "${_API_CORS_PUBLIC:-}" ]]; then
        printf "Access-Control-Allow-Origin: *\r\n"
        printf "Access-Control-Allow-Methods: GET, OPTIONS\r\n"
        printf "Access-Control-Allow-Headers: Content-Type, Authorization\r\n"
        printf "Access-Control-Allow-Private-Network: true\r\n"
        [[ "${method:-}" == "OPTIONS" ]] && printf "Access-Control-Max-Age: 600\r\n"
        return 0
    fi
    local cors_origin
    cors_origin=$(_api_cors_origin)
    # the answer depends on the Origin: a cache between a browser and this server keeps one copy per origin
    [[ -z "$cors_origin" && -n "${REQUEST_ORIGIN_HEADER:-}" ]] && printf "Vary: Origin\r\n"
    if [[ -n "$cors_origin" ]]; then
        printf "Access-Control-Allow-Origin: %s\r\n" "$cors_origin"
        printf "Access-Control-Allow-Methods: GET, POST, PUT, PATCH, DELETE, OPTIONS\r\n"
        printf "Access-Control-Allow-Headers: Content-Type, Authorization\r\n"
        printf "Access-Control-Allow-Private-Network: true\r\n"
        # a preflight is remembered for ten minutes (browsers ask again every 5 s without it:
        # nearly one OPTIONS for every call a dashboard on another origin makes)
        [[ "${method:-}" == "OPTIONS" ]] && printf "Access-Control-Max-Age: 600\r\n"
        printf "Vary: Origin\r\n"
    fi
    return 0
}

# Validate a request Origin against the CORS whitelist
# Returns the origin if allowed, empty if not
_api_cors_origin() {
    local origin="${REQUEST_ORIGIN_HEADER:-}"
    [[ -z "$origin" ]] && return 0  # No Origin header = same-origin, no CORS needed

    # In setup mode before initialization, allow ALL origins so the Electron
    # app can connect from any IP without pre-configuring CORS
    if [[ "$SETUP_MODE" == "true" ]] && ! _api_is_initialized; then
        echo "$origin"
        return 0
    fi

    # Always allow any localhost / 127.0.0.1 origin (any port)
    # This covers Vite dev (5173/5174+), Electron, and any local tooling
    case "$origin" in
        http://localhost|http://localhost:*|https://localhost|https://localhost:*|\
        http://127.0.0.1|http://127.0.0.1:*|https://127.0.0.1|https://127.0.0.1:*|\
        capacitor://localhost)
            echo "$origin"
            return 0
            ;;
    esac

    # Check user-configured origins
    if [[ -n "$API_CORS_ORIGINS" ]]; then
        local IFS=','
        local entry
        for entry in $API_CORS_ORIGINS; do
            entry="${entry## }"  # trim leading space
            entry="${entry%% }"  # trim trailing space
            [[ -n "$entry" && "$origin" == "$entry" ]] && { echo "$origin"; return 0; }
        done
    fi

    return 0  # Return empty (no echo) — origin not allowed
}

# Build a standard JSON response envelope
_api_response() {
    local status_code="$1"
    local body="$2"
    local status_text="OK"

    case "$status_code" in
        200) status_text="OK" ;;
        201) status_text="Created" ;;
        204) status_text="No Content" ;;
        202) status_text="Accepted" ;;
        400) status_text="Bad Request" ;;
        401) status_text="Unauthorized" ;;
        403) status_text="Forbidden" ;;
        404) status_text="Not Found" ;;
        405) status_text="Method Not Allowed" ;;
        409) status_text="Conflict" ;;
        413) status_text="Payload Too Large" ;;
        429) status_text="Too Many Requests" ;;
        500) status_text="Internal Server Error" ;;
        502) status_text="Bad Gateway" ;;
        507) status_text="Insufficient Storage" ;;
    esac
    # a body a route left unread (an upload) is read and dropped first: the client gets this answer, not a broken connection
    [[ -n "${REQUEST_BODY_DEFERRED:-}" ]] && _api_body_drain

    # A handler that interpolated empty jq output (a truncated state file) must
    # not reach the client as broken JSON: answer a real 500 and log it
    if [[ "$status_code" == 2* ]]; then
        local lead="${body#"${body%%[![:space:]]*}"}"
        if [[ "$lead" == \{* || "$lead" == \[* ]] && ! printf '%s' "$body" | jq -e . >/dev/null 2>&1; then
            echo "$(date '+%Y-%m-%d %H:%M:%S') invalid JSON built for ${REQUEST_METHOD:-?} ${REQUEST_PATH:-?} — a state file is probably empty or corrupt" >&2
            status_code=500; status_text="Internal Server Error"
            body='{"error": true, "code": 500, "message": "The server built an invalid response for this request; a state file is probably empty or corrupt (see logs/api-server.log)"}'
        fi
    fi

    # Use byte count (not char count) for Content-Length — critical for UTF-8
    local content_length
    content_length=$(printf '%s' "$body" | wc -c)

    {
    printf "HTTP/1.1 %s %s\r\n" "$status_code" "$status_text"
    # a 204 (a CORS preflight) has neither a body nor a length
    if [[ "$status_code" != 204 ]]; then
        printf "Content-Type: application/json; charset=utf-8\r\n"
        printf "Content-Length: %d\r\n" "$content_length"
    fi

    # Dynamic CORS — only emit for whitelisted origins
    _api_cors_lines

    # Security headers
    printf "X-Content-Type-Options: nosniff\r\n"
    printf "X-Frame-Options: DENY\r\n"
    printf "X-XSS-Protection: 1; mode=block\r\n"
    printf "Cache-Control: no-store, no-cache, must-revalidate\r\n"
    printf "Pragma: no-cache\r\n"
    printf "Content-Security-Policy: default-src 'none'; frame-ancestors 'none'\r\n"
    printf "Referrer-Policy: strict-origin-when-cross-origin\r\n"
    printf "Permissions-Policy: camera=(), microphone=(), geolocation=(), interest-cohort=()\r\n"
    if [[ "$API_TLS_ENABLED" == "true" ]] || [[ "$API_BEHIND_TLS_PROXY" == "true" ]]; then
        printf "Strict-Transport-Security: max-age=31536000; includeSubDomains; preload\r\n"
    fi

    printf "X-API-Version: %s\r\n" "$API_VERSION"
    printf "Connection: close\r\n"
    printf "\r\n"
    printf "%s" "$body"
    } 2>/dev/null
}

_api_error() {
    local code="$1"
    local message="$2"
    local escaped
    escaped="$(_api_json_escape "$message")"
    # Increment error counter
    if [[ -f "${API_STATS_FILE}" ]]; then
        local _rc _ec
        _rc=$(sed -n '1p' "$API_STATS_FILE" 2>/dev/null || echo 0)
        _ec=$(sed -n '2p' "$API_STATS_FILE" 2>/dev/null || echo 0)
        printf '%d\n%d\n' "$_rc" "$(( _ec + 1 ))" > "$API_STATS_FILE" 2>/dev/null
    fi
    _api_response "$code" "{\"error\": true, \"code\": $code, \"message\": \"$escaped\"}"
}

_api_success() {
    local body="$1"
    # a handler that captured nothing (a helper that failed under errexit, an empty state file) answers a real error, never a blank 200
    # (a regex search for one non-blank character: stripping the blanks out of the whole body took five seconds on a 120 KB list)
    if [[ ! "$body" =~ [^[:space:]] ]]; then
        echo "$(date '+%Y-%m-%d %H:%M:%S') empty answer built for ${REQUEST_METHOD:-?} ${REQUEST_PATH:-?}" >&2
        _api_error 500 "empty answer"; return
    fi
    _api_response 200 "$body"
}

# =============================================================================
# FAST PATH: the dashboard's heartbeat (GET /ping)
# =============================================================================
# Bash reads a script as it runs it, and this one is ~26,000 lines of functions that every request parses again
# (about 85 of the 105 ms a heartbeat used to take, so a busy server queued its own heartbeat behind the page's other
# calls). The heartbeat is answered here, before the rest is parsed, in a few milliseconds — with the same
# response function, so the headers (CORS, security, HSTS) are the ones every answer carries.
# It is answered here only when nothing else could change the answer: an IP allow-list, the setup mode's open CORS
# and the rate limiter all live below, so a server that uses one of them, and every other request, takes the
# normal path with the request line already read (_API_PREREAD_LINE). A heartbeat is neither written to the access
# log nor counted. DCS_NO_FAST_PING=1 turns it off (the smoke test compares both answers).
if [[ "$HANDLE_REQUEST" == "true" && -z "${DCS_NO_FAST_PING:-}" && -z "$API_IP_WHITELIST" && "$SETUP_MODE" != "true" ]]; then
    set +e
    if read -r -t 10 _API_PREREAD_LINE; then
        _API_PREREAD_SET=1
        _fp_line="${_API_PREREAD_LINE%%$'\r'}"
        if [[ "$_fp_line" == "GET /ping HTTP/1."[01] || "$_fp_line" == "GET /ping/ HTTP/1."[01] ]]; then
            REQUEST_ORIGIN_HEADER=""; _fp_n=0
            while IFS= read -r -t 10 _fp_h; do
                (( ++_fp_n > 100 )) && break
                _fp_h="${_fp_h%%$'\r'}"
                [[ -z "$_fp_h" ]] && break
                if [[ "${_fp_h,,}" == origin:* ]]; then
                    REQUEST_ORIGIN_HEADER="${_fp_h#*: }"; REQUEST_ORIGIN_HEADER="${REQUEST_ORIGIN_HEADER## }"
                    REQUEST_ORIGIN_HEADER="${REQUEST_ORIGIN_HEADER//$'\r'/}"; REQUEST_ORIGIN_HEADER="${REQUEST_ORIGIN_HEADER//$'\n'/}"
                fi
            done
            REQUEST_METHOD=GET; REQUEST_PATH=/ping; _API_CORS_PUBLIC=1
            _api_success "{\"ok\": true, \"version\": \"$(_api_json_escape "$DCS_VERSION")\", \"api_version\": \"$API_VERSION\", \"time\": $(printf '%(%s)T' -1)}"
            exit 0
        fi
    fi
fi

# Response cache for the read endpoints every open dashboard polls. The Docker
# daemon answers once per TTL however many clients ask, and a poll never waits
# for it: an answer past its TTL is served at once and refreshed in the
# background (stale-while-revalidate). Any write request, and any audited
# event, clears it, so an action shows on the next poll.
#   hit    age < TTL                   served from the file
#   stale  TTL ≤ age < MAX_STALE       served from the file, refreshed in the background
#   miss   no file, or age ≥ MAX_STALE the handler runs inline and its answer is kept
# Every cached answer carries "X-DCS-Cache: hit|stale|miss" and "Age".
# Usage: _api_cached NAME TTL_SECONDS HANDLER [ARGS…]
API_CACHE_DIR="${API_CACHE_DIR:-$BASE_DIR/.data/cache}"
API_CACHE_MAX_STALE="${API_CACHE_MAX_STALE:-120}"
_api_cached() {
    local name="$1" ttl="$2"; shift 2
    local k f now mtime age
    for k in "${!QUERY_PARAMS[@]}"; do name+="_${k}-${QUERY_PARAMS[$k]}"; done
    name=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_')
    f="$API_CACHE_DIR/$name.http"
    if [[ "${API_RESPONSE_CACHE:-true}" != "false" && -s "$f" ]]; then
        now=$(date +%s); mtime=$(stat -c %Y "$f" 2>/dev/null || echo 0)
        age=$(( now - mtime ))
        if (( age < ttl )); then
            _api_cache_emit "$f" hit "$age"; return 0
        fi
        if (( age < API_CACHE_MAX_STALE )); then
            _api_cache_refresh "$f" "$@"
            _api_cache_emit "$f" stale "$age"; return 0
        fi
    fi
    [[ -d "$API_CACHE_DIR" ]] || mkdir -p "$API_CACHE_DIR" 2>/dev/null
    # the answer is written to a dotfile first: a cache clear that runs while the handler works (a state change it
    # noticed, an action it forwarded) removes *.http and *.tmp.*, and must not take the answer in flight with it
    local tmp="$API_CACHE_DIR/.inflight-$name.$$"
    "$@" > "$tmp"
    _api_cache_emit "$tmp" miss 0
    # only a 200 with a body is kept (a blank answer would otherwise be served for a whole TTL)
    local cl; cl=$(head -c 2048 "$tmp" 2>/dev/null | grep -m1 -i '^Content-Length:' | tr -dc '0-9' || true)
    if head -c 12 "$tmp" 2>/dev/null | grep -q '^HTTP/1.1 200' && [[ "${cl:-0}" -gt 0 ]]; then mv -f "$tmp" "$f" 2>/dev/null; else rm -f "$tmp"; fi
    return 0
}
# Print a stored response with the cache headers added after the status line
# (byte-exact body, so Content-Length stays right).
_api_cache_emit() {
    local file="$1" state="$2" age="$3" first line
    {
        IFS= read -r first
        printf '%s\n' "$first"
        printf 'X-DCS-Cache: %s\r\nAge: %s\r\n' "$state" "$age"
        # the stored headers, except the CORS ones: those are the ones of the request that filled the cache (its Origin), and a
        # dashboard on another origin got them and a CORS error
        while IFS= read -r line; do
            if [[ -z "$line" || "$line" == $'\r' ]]; then _api_cors_lines; printf '%s\n' "$line"; break; fi
            case "$line" in Access-Control-*|Vary:*) continue ;; esac
            printf '%s\n' "$line"
        done
        cat
    } < "$file"
}
# Refresh a cache file in the background: one refresher per file (a mkdir
# lock; an abandoned lock older than the stale limit is taken over), fully
# detached from the connection so the client's answer is not held up.
_api_cache_refresh() {
    local f="$1"; shift
    local lock="$f.lock" lock_age
    if [[ -d "$lock" ]]; then
        lock_age=$(( $(date +%s) - $(stat -c %Y "$lock" 2>/dev/null || echo 0) ))
        (( lock_age < API_CACHE_MAX_STALE )) && return 0
        rmdir "$lock" 2>/dev/null || return 0
    fi
    mkdir "$lock" 2>/dev/null || return 0
    (
        trap 'rmdir "$lock" 2>/dev/null' EXIT
        local tmp="$f.tmp.$$"
        "$@" > "$tmp" 2>/dev/null
        # only a 200 with a body is kept (a blank answer would otherwise be served for a whole TTL)
        local cl; cl=$(head -c 2048 "$tmp" 2>/dev/null | grep -m1 -i '^Content-Length:' | tr -dc '0-9' || true)
        if head -c 12 "$tmp" 2>/dev/null | grep -q '^HTTP/1.1 200' && [[ "${cl:-0}" -gt 0 ]]; then mv -f "$tmp" "$f" 2>/dev/null; else rm -f "$tmp"; fi
    ) </dev/null >/dev/null 2>&1 &
    return 0
}
# The .inflight-* names are the answers handlers are still writing: clearing
# one mid-emit makes that request answer nothing, so only files old enough to
# be orphaned (a handler died) are swept — never a live writer's.
_api_cache_clear() { local d="${API_CACHE_DIR:-$BASE_DIR/.data/cache}"; rm -rf "$d"/*.http "$d"/*.lock "$d"/*.tmp.* 2>/dev/null; find "$d" -maxdepth 1 -name '.inflight-*' -mmin +10 -delete 2>/dev/null; return 0; }

# =============================================================================
# QUERY STRING PARSER
# =============================================================================

declare -gA QUERY_PARAMS=()

_api_parse_query() {
    QUERY_PARAMS=()
    local full_path="$1"
    if [[ "$full_path" == *"?"* ]]; then
        local query_string="${full_path#*\?}"
        local IFS='&'
        local -a pairs
        read -ra pairs <<< "$query_string"
        for pair in "${pairs[@]}"; do
            local key="${pair%%=*}"
            [[ -n "$key" ]] || continue      # "a=1&&b=2" or "=x": no name, no parameter (bash refuses "" as an array index and the request died without an answer)
            local value="${pair#*=}"
            value="${value//+/ }"
            # URL-decode percent-encoded characters
            value=$(printf '%b' "${value//%/\\x}")
            QUERY_PARAMS["$key"]="$value"
        done
    fi
}

# =============================================================================
# AUTHENTICATION HELPERS
# =============================================================================

# Auth audit log — append-only structured log for security events
# Sanitizes all fields to prevent log injection (strips pipes, newlines, control chars)
_api_audit_log() {
    local ip="$1" event="$2" username="${3:-}" detail="${4:-}"
    # Strip pipe characters, newlines, and control chars from user-supplied fields
    username="${username//|/}"
    username="${username//$'\n'/}"
    username="${username//$'\r'/}"
    detail="${detail//|/}"
    detail="${detail//$'\n'/ }"
    detail="${detail//$'\r'/}"
    # Truncate detail to prevent log flooding (max 256 chars)
    [[ ${#detail} -gt 256 ]] && detail="${detail:0:256}..."
    printf '%s | %-15s | %-14s | %-15s | %s\n' \
        "$(_api_now_iso)" "$ip" "$event" "$username" "$detail" \
        >> "${API_AUTH_DIR}/auth-audit.log" 2>/dev/null
    # Mirror into the JSON audit log that GET /audit, the UI and webhooks consume
    _audit_log "auth.${event,,}" "${username:-anonymous}@${ip}${detail:+ — $detail}"
}

# Initialize auth data directory and files
_api_init_auth_dir() {
    if [[ ! -d "$API_AUTH_DIR" ]]; then
        (umask 0077 && mkdir -p "$API_AUTH_DIR") 2>/dev/null || mkdir -p "$API_AUTH_DIR" 2>/dev/null
    fi
    # Create missing auth files with secure permissions
    # Use printf + chmod as fallback if install doesn't support /dev/stdin
    for _f in users.json tokens.json invites.json; do
        if [[ ! -f "$API_AUTH_DIR/$_f" ]]; then
            printf '[]' > "$API_AUTH_DIR/$_f" 2>/dev/null && chmod 600 "$API_AUTH_DIR/$_f" 2>/dev/null
        fi
    done
    if [[ ! -f "$API_AUTH_DIR/rate_limits.json" ]]; then
        printf '{}' > "$API_AUTH_DIR/rate_limits.json" 2>/dev/null && chmod 600 "$API_AUTH_DIR/rate_limits.json" 2>/dev/null
    fi
}

# Force-remove a directory, using Docker as fallback for root-owned files.
# Docker containers create files owned by root; the API server (running as the
# host user) can't delete those with plain rm. This tries rm first, then falls
# back to a throwaway Alpine container that mounts the directory and deletes it.
_force_remove_dir() {
    local dir="$1"
    [[ -d "$dir" ]] || return 0

    # Attempt 1: regular rm
    rm -rf "$dir" 2>/dev/null
    [[ -d "$dir" ]] || return 0

    # Attempt 2: Docker-based privileged removal
    if command -v docker >/dev/null 2>&1; then
        local abs_dir
        abs_dir=$(cd "$dir" 2>/dev/null && pwd || realpath "$dir" 2>/dev/null || echo "$dir")
        docker run --rm -v "$abs_dir:/___target" alpine rm -rf /___target 2>/dev/null
        # Docker removes the contents but the mount-point directory persists —
        # now the host user can remove the empty directory
        rm -rf "$dir" 2>/dev/null
    fi

    [[ -d "$dir" ]] && return 1 || return 0
}

# Hash a password with a given salt using SHA-256 (v1 — legacy, kept for verifying old hashes)
_api_hash_password() {
    local salt="$1"
    local password="$2"
    echo -n "${salt}${password}" | sha256sum | cut -d' ' -f1
}

# Hash a password with PBKDF2-SHA256 (v2 — secure, requires python3)
_api_hash_password_v2() {
    local salt="$1" password="$2" iters="${API_PBKDF2_ITERATIONS:-100000}"
    # The password travels in the environment, never on the command line
    # (argv is readable by every local user via /proc).
    DCS_PW="$password" DCS_SALT="$salt" DCS_ITERS="$iters" python3 -c '
import hashlib, os
print(hashlib.pbkdf2_hmac(
    "sha256",
    os.environ["DCS_PW"].encode(),
    bytes.fromhex(os.environ["DCS_SALT"]),
    int(os.environ["DCS_ITERS"])
).hex())'
}

# Verify a password against a stored hash, dispatching to v1 or v2 based on hash_version
_api_verify_password() {
    local password="$1" stored_hash="$2" stored_salt="$3" hash_version="${4:-1}"
    local computed_hash
    if [[ "$hash_version" == "2" ]]; then
        computed_hash=$(_api_hash_password_v2 "$stored_salt" "$password")
    else
        computed_hash=$(_api_hash_password "$stored_salt" "$password")
    fi
    # SECURITY: Constant-time comparison to prevent timing attacks.
    # Python's hmac.compare_digest is guaranteed constant-time.
    DCS_A="$computed_hash" DCS_B="$stored_hash" python3 -c '
import hmac, os
raise SystemExit(0 if hmac.compare_digest(os.environ["DCS_A"], os.environ["DCS_B"]) else 1)'
}

# Update a user's password hash in users.json (for transparent migration)
_api_update_user_hash() { _api_with_auth_lock users _api_update_user_hash_locked "$@"; }
_api_update_user_hash_locked() {
    local username="$1" new_hash="$2" new_salt="$3" new_version="$4"
    local users
    users=$(_api_read_auth_file "users.json")
    if command -v jq >/dev/null 2>&1; then
        local new_users
        new_users=$(echo "$users" | jq \
            --arg u "$username" \
            --arg h "$new_hash" \
            --arg s "$new_salt" \
            --argjson v "$new_version" \
            '[.[] | if .username == $u then . + {"password_hash": $h, "salt": $s, "hash_version": $v} else . end]' 2>/dev/null)
        _api_write_auth_file "users.json" "$new_users"
    fi
}

# =============================================================================
# TOTP (Time-Based One-Time Password) — RFC 6238
# =============================================================================

# Generate a TOTP secret (20 bytes random, returned as hex + base32)
_api_totp_generate_secret() {
    python3 -c "
import os, base64
raw = os.urandom(20)
print(raw.hex())
print(base64.b32encode(raw).decode().rstrip('='))
" 2>/dev/null
}

# Verify a TOTP code against a secret. Allows +/-1 time window (90 seconds).
# Args: $1=hex_secret $2=6-digit code
# Returns: 0 on success, 1 on failure
_api_totp_verify() {
    local hex_secret="$1" code="$2"
    python3 -c "
import hmac, hashlib, struct, sys, time
secret = bytes.fromhex(sys.argv[1])
code = sys.argv[2].strip()
if len(code) != 6 or not code.isdigit():
    sys.exit(1)
now = int(time.time())
# Check current period and +/-1 for clock skew (90 second window)
for offset in (-1, 0, 1):
    t = (now // 30) + offset
    msg = struct.pack('>Q', t)
    h = hmac.new(secret, msg, hashlib.sha1).digest()
    o = h[-1] & 0x0F
    token = (struct.unpack('>I', h[o:o+4])[0] & 0x7FFFFFFF) % 1000000
    if str(token).zfill(6) == code:
        sys.exit(0)
sys.exit(1)
" "$hex_secret" "$code" 2>/dev/null
}

# Build an otpauth:// URI for QR code generation
# Args: $1=base32_secret $2=username $3=issuer
_api_totp_uri() {
    local b32="$1" username="$2" issuer="${3:-DCS}"
    # Usernames are validated to [A-Za-z0-9_-] at signup and the issuer is a
    # fixed label, so no URL encoding is needed here.
    printf 'otpauth://totp/%s:%s?secret=%s&issuer=%s&algorithm=SHA1&digits=6&period=30' \
        "$issuer" "$username" "$b32" "$issuer"
}

# Update a user's TOTP fields in users.json
_api_totp_update_user() { _api_with_auth_lock users _api_totp_update_user_locked "$@"; }
_api_totp_update_user_locked() {
    local username="$1" totp_secret="$2" totp_enabled="$3"
    local users
    users=$(_api_read_auth_file "users.json")
    if command -v jq >/dev/null 2>&1; then
        local new_users
        new_users=$(echo "$users" | jq \
            --arg u "$username" \
            --arg s "$totp_secret" \
            --argjson e "$totp_enabled" \
            '[.[] | if .username == $u then . + {"totp_secret": $s, "totp_enabled": $e} else . end]' 2>/dev/null)
        _api_write_auth_file "users.json" "$new_users"
    fi
}

# Generate a random token
_api_generate_token() {
    # SECURITY: Always use cryptographic randomness — never bash $RANDOM
    local token=""
    token=$(head -c 32 /dev/urandom 2>/dev/null | xxd -p -c 64 2>/dev/null)
    if [[ -z "$token" ]]; then
        token=$(head -c 32 /dev/urandom 2>/dev/null | od -An -tx1 2>/dev/null | tr -d ' \n')
    fi
    if [[ -z "$token" ]]; then
        token=$(openssl rand -hex 32 2>/dev/null)
    fi
    if [[ -z "$token" || ${#token} -lt 32 ]]; then
        echo "FATAL: Cannot generate secure token — /dev/urandom unavailable" >&2
        return 1
    fi
    echo "$token"
}

# Generate a random salt
_api_generate_salt() {
    # SECURITY: Always use cryptographic randomness — never bash $RANDOM
    local salt=""
    salt=$(head -c 16 /dev/urandom 2>/dev/null | xxd -p -c 32 2>/dev/null)
    if [[ -z "$salt" ]]; then
        salt=$(head -c 16 /dev/urandom 2>/dev/null | od -An -tx1 2>/dev/null | tr -d ' \n')
    fi
    if [[ -z "$salt" ]]; then
        salt=$(openssl rand -hex 16 2>/dev/null)
    fi
    if [[ -z "$salt" || ${#salt} -lt 16 ]]; then
        echo "FATAL: Cannot generate secure salt — /dev/urandom unavailable" >&2
        return 1
    fi
    echo "$salt"
}

# SHA-256 digest of a session token. tokens.json and terminal-sessions.json
# keep only the digest, so a leaked state file cannot be replayed; records
# written before this change are still matched against the raw value until
# they expire or are revoked.
_api_token_digest() {
    printf '%s' "$1" | sha256sum | cut -d' ' -f1
}

# Read a JSON auth file (returns contents, with shared flock)
_api_read_auth_file() {
    local file="$API_AUTH_DIR/$1"
    [[ -f "$file" ]] || { echo '[]'; return; }
    if command -v flock >/dev/null 2>&1; then
        (flock -s -w 2 200; cat "$file" 2>/dev/null) 200>"$file.lock"
    else
        cat "$file" 2>/dev/null
    fi
}

# Write a JSON auth file (exclusive flock + restricted permissions): a temp file renamed over it, so a reader never sees
# it half written and a full disk never leaves it empty; when the lock does not come, nothing is written (1)
_api_write_auth_file() {
    local file="$API_AUTH_DIR/$1"
    local content="$2" tmp="$API_AUTH_DIR/$1.tmp.${BASHPID:-$$}"
    [[ -d "$API_AUTH_DIR" ]] || mkdir -p "$API_AUTH_DIR" 2>/dev/null
    if command -v flock >/dev/null 2>&1; then
        (
            flock -w 2 200 || { echo "$1 is locked: not written" >&2; exit 1; }
            { (umask 077; printf '%s' "$content" > "$tmp") && chmod 600 "$tmp" && mv -f "$tmp" "$file"; } 2>/dev/null || { rm -f "$tmp"; exit 1; }
        ) 200>"$file.lock"
    else
        { (umask 077; printf '%s' "$content" > "$tmp") && mv -f "$tmp" "$file"; } 2>/dev/null || { rm -f "$tmp"; return 1; }
    fi
}

# _version_ge A B — true when version A sorts at or after B (sort -V: 1.10 after 1.9, 6.8.0-45 after 6.8.0-9)
_version_ge() { [[ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | tail -n 1)" == "$1" ]]; }

# _api_now_iso — the time now, UTC, as 2026-10-08T21:30:00Z: every ISO timestamp the API writes (the time as epoch seconds is
# plain `date +%s`)
_api_now_iso() {
    date -u '+%Y-%m-%dT%H:%M:%SZ'
}

# Check if a user exists (returns 0 if exists, 1 if not)
_api_user_exists() {
    local username="$1"
    local users
    users=$(_api_read_auth_file "users.json")
    if command -v jq >/dev/null 2>&1; then
        local count
        count=$(echo "$users" | jq -r --arg u "$username" '[.[] | select(.username == $u)] | length' 2>/dev/null)
        [[ "$count" -gt 0 ]] && return 0
    else
        echo "$users" | grep -q "\"username\": *\"$username\"" && return 0
    fi
    return 1
}

# Setup wizard state
SETUP_COMPLETE_MARKER="$API_AUTH_DIR/.setup-complete"

# Check if server is fully initialized (users exist AND setup marker present)
_api_is_initialized() {
    # A node has nothing to set up: no admin to make, no wizard to finish (its accounts are the hub's, made by the join)
    _api_is_node && return 0
    # When auth is disabled, only check the marker file (no user accounts required)
    if [[ "$API_AUTH_ENABLED" != "true" ]]; then
        [[ -f "$SETUP_COMPLETE_MARKER" ]]
        return $?
    fi
    [[ "$(_api_user_count)" -gt 0 ]] && [[ -f "$SETUP_COMPLETE_MARKER" ]]
}

# The setup wizard's public routes while setup is unfinished. Before the first account exists they
# are open (a fresh install has nobody to sign in as). Once an admin exists but the wizard has not
# finished (it was closed, or is resumed), that admin owns the server: the caller must be them.
# 0 = go on; 1 = not allowed (the answer is not sent: the caller decides what an outsider gets).
_api_setup_caller_ok() {
    [[ "$API_AUTH_ENABLED" != "true" ]] && return 0
    [[ "$(_api_user_count)" -eq 0 ]] && return 0
    _api_check_auth && [[ "${AUTH_ROLE:-}" == "admin" ]]
}

# Gate for setup-only endpoints — returns 1 (and sends 403) if setup is already done
_api_require_setup_mode() {
    if _api_is_initialized; then
        _api_error 403 "Setup already complete"
        return 1
    fi
    return 0
}

# Get user count
_api_user_count() {
    local users
    users=$(_api_read_auth_file "users.json")
    if command -v jq >/dev/null 2>&1; then
        echo "$users" | jq 'length' 2>/dev/null
    else
        # Rough count by counting username fields
        echo "$users" | grep -c '"username"' 2>/dev/null || echo "0"
    fi
}

# Get user record as JSON (requires jq)
_api_get_user() {
    local username="$1"
    local users
    users=$(_api_read_auth_file "users.json")
    echo "$users" | jq -r --arg u "$username" '.[] | select(.username == $u)' 2>/dev/null
}

# The role of an account, "user" when unknown
# Service accounts (a hub's dcs-hub account on a member) are exempt from the single-session rule
_api_user_is_service() {
    _api_read_auth_file "users.json" | jq -r --arg u "$1" '[.[] | select(.username == $u)] | .[0].service // false' 2>/dev/null
}

_api_user_role() {
    _api_read_auth_file "users.json" | jq -r --arg u "$1" '[.[] | select(.username == $u) | .role // "user"] | first // "user"' 2>/dev/null
}

# Add a user record (always v2 hash), serialized under the users lock
_api_add_user() { _api_with_auth_lock users _api_add_user_locked "$@"; }
_api_add_user_locked() {
    local username="$1" password_hash="$2" salt="$3" role="$4"
    if ! command -v jq >/dev/null 2>&1; then
        echo "jq is required to add a user" >&2
        return 1
    fi
    local created_at
    created_at=$(_api_now_iso)
    local users new_users
    users=$(_api_read_auth_file "users.json")
    new_users=$(echo "$users" | jq \
        --arg u "$username" \
        --arg h "$password_hash" \
        --arg s "$salt" \
        --arg r "$role" \
        --arg c "$created_at" \
        '. + [{"username": $u, "password_hash": $h, "salt": $s, "role": $r, "created_at": $c, "hash_version": 2}]' 2>/dev/null)
    [[ -n "$new_users" ]] || { echo "Refusing to write an empty users.json" >&2; return 1; }
    _api_write_auth_file "users.json" "$new_users"
}

# First-admin insert under the users lock: the "no users yet" check and the
# insert are one critical section, so two racing /auth/setup requests cannot
# both create an admin.
_api_setup_first_admin() {
    [[ "$(_api_user_count)" -gt 0 ]] && return 1
    _api_add_user "$1" "$2" "$3" "admin"
}

# Delete a user record under the users lock
_api_delete_user() { _api_with_auth_lock users _api_delete_user_locked "$@"; }
_api_delete_user_locked() {
    local username="$1" users new_users
    command -v jq >/dev/null 2>&1 || return 1
    users=$(_api_read_auth_file "users.json")
    new_users=$(echo "$users" | jq --arg u "$username" '[.[] | select(.username != $u)]' 2>/dev/null)
    [[ -n "$new_users" ]] || return 1
    _api_write_auth_file "users.json" "$new_users"
}

# _api_with_auth_lock tokens|users CMD… — runs CMD while holding the lock every read-modify-write of tokens.json (or users.json)
# takes; a caller that holds it already (the sign-in below holds the tokens lock while it revokes) runs CMD directly. Without it two
# requests can each read the file, change it and write it back, and one of the changes (a fresh session, an account, a hash upgrade
# after a check-then-write like the first admin) is lost.
_api_with_auth_lock() {
    local _awl_which="$1"; shift
    local _awl_held="_API_${_awl_which^^}_LOCK_HELD"
    if [[ -n "${!_awl_held:-}" ]]; then "$@"; return; fi
    (
        flock -w 10 200 || { if [[ "$_awl_which" == tokens ]]; then echo "Token lock timeout"; else echo "User lock timeout"; fi >&2; exit 1; }
        export "$_awl_held=1"
        "$@"
    ) 200>"$API_AUTH_DIR/.$_awl_which.lock"
}

# Store a session token (enforces single-session when enabled)
# SECURITY: the tokens lock prevents the race where concurrent logins both pass the single-session check and create duplicate tokens.
_api_store_token() { _api_with_auth_lock tokens _api_store_token_locked "$@"; }
_api_store_token_locked() {
    local token="$1" username="$2" role="$3"

    # Single-session enforcement: revoke all existing tokens for this user
    # (bot accounts keep theirs: a bot may sign in from several places)
    if [[ "${API_SINGLE_SESSION:-true}" == "true" && "$(_api_user_role "$username")" != "bot" && "$(_api_user_is_service "$username")" != "true" ]]; then
        _api_revoke_user_tokens "$username"
    fi

    if ! command -v jq >/dev/null 2>&1; then
        echo "jq is required to store a session token" >&2
        return 1
    fi

    local now
    now=$(date +%s)
    local expires_at=$(( now + API_TOKEN_EXPIRY ))
    local created_at
    created_at=$(_api_now_iso)
    # Only the digest is stored: a copy of tokens.json then cannot be replayed
    local digest
    digest=$(_api_token_digest "$token")
    local tokens new_tokens
    tokens=$(_api_read_auth_file "tokens.json")
    new_tokens=$(echo "$tokens" | jq \
        --arg t "$digest" \
        --arg u "$username" \
        --arg r "$role" \
        --arg c "$created_at" \
        --argjson e "$expires_at" \
        --arg ip "${CLIENT_IP:-}" \
        '. + [{"token": $t, "username": $u, "role": $r, "created_at": $c, "expires_at": $e, "ip": $ip}]' 2>/dev/null)
    [[ -n "$new_tokens" ]] || { echo "Refusing to write an empty tokens.json" >&2; return 1; }
    _api_write_auth_file "tokens.json" "$new_tokens"
}

# Validate a token — sets AUTH_USERNAME and AUTH_ROLE on success; returns 1 on failure
_api_validate_token() {
    local token="$1"
    AUTH_USERNAME=""
    AUTH_ROLE=""

    if [[ -z "$token" ]]; then
        return 1
    fi

    local tokens
    tokens=$(_api_read_auth_file "tokens.json")
    local now
    now=$(date +%s)

    # Stored tokens are digests; the raw form is still accepted so sessions
    # issued before the change keep working until they expire. The temporary token of a
    # sign-in waiting for its 2FA code is never a session: only POST /auth/totp/validate takes it
    local digest
    digest=$(_api_token_digest "$token")
    local record
    record=$(echo "$tokens" | jq -r --arg t "$digest" --arg raw "$token" --argjson n "$now" \
        '.[] | select((.token == $t or .token == $raw) and .expires_at > $n and .totp_pending != true)' 2>/dev/null)
    if [[ -n "$record" ]]; then
        AUTH_USERNAME=$(echo "$record" | jq -r '.username' 2>/dev/null)
        AUTH_ROLE=$(echo "$record" | jq -r '.role' 2>/dev/null)
        return 0
    fi
    return 1
}

# =============================================================================
# API KEYS
#
# A session belongs to a person at a keyboard: it expires in hours and a second sign-in ends the first. A dashboard
# (Homarr), a script or Home Assistant can only send a fixed header, for months. An API key is that: made by an admin,
# shown once, kept here as a hash only, sent as "Authorization: Bearer dcs_…" or "X-API-Key: dcs_…".
#   read     what a viewer may read (every GET that is not admin-only), nothing else
#   operate  that, plus what a bot account may do: start, stop, restart and update stacks and containers, deploy a
#            template, run a backup or a schedule
# A key is never an admin and never an account: users, sessions, secrets, the terminal, files, settings and the keys
# themselves stay closed to it. The audit log names the key.
# =============================================================================
_api_key_hash() { printf '%s' "$1" | sha256sum | cut -d' ' -f1; }
# _api_validate_key KEY — sets AUTH_USERNAME ("key:<name>"), AUTH_ROLE (user | bot), AUTH_VIA_KEY, AUTH_KEY_ID
_api_validate_key() {
    local key="$1" h now rec f="$API_AUTH_DIR/api-keys.json"
    AUTH_USERNAME=""; AUTH_ROLE=""; AUTH_VIA_KEY=""; AUTH_KEY_ID=""
    [[ "$key" =~ ^dcs_[0-9a-f]{40}$ && -s "$f" ]] || return 1
    h=$(_api_key_hash "$key"); now=$(date +%s)
    rec=$(jq -c --arg h "$h" --argjson n "$now" '[.[] | select(.hash == $h and ((.expires_at // 0) == 0 or .expires_at > $n))] | .[0] // empty' "$f" 2>/dev/null) || rec=""
    [[ -n "$rec" ]] || return 1
    AUTH_KEY_ID=$(jq -r '.id' <<< "$rec"); AUTH_USERNAME="key:$(jq -r '.name' <<< "$rec")"; AUTH_VIA_KEY=true
    [[ "$(jq -r '.role' <<< "$rec")" == "operate" ]] && AUTH_ROLE="bot" || AUTH_ROLE="user"
    # when it was last used, to the minute (the list shows a key nobody uses any more)
    if (( now - $(jq -r '.last_used_at // 0' <<< "$rec") > 60 )); then
        _api_jq_update_file "$f" --arg id "$AUTH_KEY_ID" --argjson n "$now" 'map(if .id == $id then .last_used_at = $n else . end)' 2>/dev/null || true
    fi
    return 0
}
# GET /auth/keys — The API keys (name, role, when made, when last used, expiry); the key itself is never shown again (admin, not with a key)
handle_auth_keys_list() {
    if [[ "${AUTH_ROLE:-}" != "admin" || "${AUTH_VIA_KEY:-}" == "true" ]]; then _api_error 403 "Admin access required"; return; fi
    local f="$API_AUTH_DIR/api-keys.json" now; now=$(date +%s)
    _api_state_file "$f" '[]' array || true
    _api_success "$(jq -c --argjson n "$now" '{keys: [.[] | {id, name, role, prefix, created_at, created_by, expires_at: (.expires_at // 0), last_used_at: (.last_used_at // 0), expired: ((.expires_at // 0) != 0 and .expires_at <= $n)}] | sort_by(.created_at) | reverse, header: "Authorization: Bearer <key>  or  X-API-Key: <key>"}' "$f" 2>/dev/null || echo '{"keys": []}')"
}
# POST /auth/keys — Make an API key for a dashboard or a script {name, role: read|operate, expires_days?: 0 = never}: the key is in the answer once, DCS keeps its hash (admin, not with a key)
handle_auth_keys_create() {
    if [[ "${AUTH_ROLE:-}" != "admin" || "${AUTH_VIA_KEY:-}" == "true" ]]; then _api_error 403 "Admin access required"; return; fi
    local body="$1" f="$API_AUTH_DIR/api-keys.json" name role days key id now exp
    _api_init_auth_dir; _api_state_file "$f" '[]' array || true
    name=$(jq -r '.name // "" | tostring' <<< "$body" 2>/dev/null) || name=""
    role=$(jq -r '.role // "read"' <<< "$body" 2>/dev/null) || role=""
    days=$(jq -r '(.expires_days // 0) | tostring' <<< "$body" 2>/dev/null) || days=""
    [[ "$name" =~ ^[A-Za-z0-9][A-Za-z0-9\ ._-]{0,39}$ ]] || { _api_error 400 "name: 1 to 40 letters, digits, spaces, dots, dashes or underscores (what the key is for: Homarr, Home Assistant)"; return; }
    [[ "$role" == "read" || "$role" == "operate" ]] || { _api_error 400 "role is read (look only) or operate (also start, stop, restart and update)"; return; }
    [[ "$days" =~ ^[0-9]{1,4}$ ]] && (( days <= 3650 )) || { _api_error 400 "expires_days is a whole number of days up to 3650; 0 means the key does not expire"; return; }
    (( $(jq 'length' "$f" 2>/dev/null || echo 0) < 50 )) || { _api_error 409 "There are 50 keys already: remove one that is no longer used"; return; }
    jq -e --arg n "$name" 'all(.[]; .name != $n)' "$f" >/dev/null 2>&1 || { _api_error 409 "A key named \"$name\" exists already"; return; }
    key="dcs_$(openssl rand -hex 20 2>/dev/null || head -c 20 /dev/urandom | od -An -tx1 | tr -d ' \n')"
    [[ "$key" =~ ^dcs_[0-9a-f]{40}$ ]] || { _api_error 500 "Could not make a key"; return; }
    id=$(openssl rand -hex 4 2>/dev/null || head -c 4 /dev/urandom | od -An -tx1 | tr -d ' \n'); now=$(date +%s)
    exp=0; (( days > 0 )) && exp=$(( now + days * 86400 ))
    _api_jq_update_file "$f" --arg id "$id" --arg n "$name" --arg r "$role" --arg h "$(_api_key_hash "$key")" --arg p "${key:0:8}" --arg by "${AUTH_USERNAME:-unknown}" --argjson now "$now" --argjson exp "$exp" \
        '. + [{id: $id, name: $n, role: $r, hash: $h, prefix: $p, created_at: $now, created_by: $by, expires_at: $exp, last_used_at: 0}]' || { _api_error 500 "Could not save the key"; return; }
    _api_audit_log "${CLIENT_IP:-unknown}" "API_KEY_CREATED" "${AUTH_USERNAME:-anonymous}" "API key \"$name\" ($role, id $id$( (( exp > 0 )) && printf ', expires in %s days' "$days"))"
    _api_success "$(jq -nc --arg id "$id" --arg n "$name" --arg r "$role" --arg k "$key" --argjson exp "$exp" '{success: true, id: $id, name: $n, role: $r, key: $k, expires_at: $exp, message: "This key is shown once. Send it as Authorization: Bearer <key> or as X-API-Key: <key>."}')"
}
# DELETE /auth/keys/{id} — Remove an API key: it stops working at once (admin, not with a key)
handle_auth_keys_delete() {
    if [[ "${AUTH_ROLE:-}" != "admin" || "${AUTH_VIA_KEY:-}" == "true" ]]; then _api_error 403 "Admin access required"; return; fi
    local id="$1" f="$API_AUTH_DIR/api-keys.json" name
    [[ "$id" =~ ^[0-9a-f]{8}$ ]] || { _api_error 400 "Not a key id"; return; }
    name=$(jq -r --arg id "$id" '.[] | select(.id == $id) | .name' "$f" 2>/dev/null) || name=""
    [[ -n "$name" ]] || { _api_error 404 "No key with that id"; return; }
    _api_jq_update_file "$f" --arg id "$id" 'map(select(.id != $id))' || { _api_error 500 "Could not remove the key"; return; }
    _api_audit_log "${CLIENT_IP:-unknown}" "API_KEY_REMOVED" "${AUTH_USERNAME:-anonymous}" "API key \"$name\" (id $id)"
    _api_success "$(jq -nc --arg n "$name" '{success: true, message: ("The key \"" + $n + "\" no longer works.")}')"
}

# =============================================================================
# IP WHITELIST & RATE LIMITING
# =============================================================================

# Check if a given IP is within a CIDR range (supports /8 /16 /24 /32)
_api_ip_in_cidr() {
    local ip="$1" cidr="$2"
    local net mask
    net="${cidr%/*}"
    mask="${cidr#*/}"
    [[ "$mask" == "$cidr" ]] && mask=32  # no slash means exact match
    [[ "$ip" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ && "$net" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ && "$mask" =~ ^[0-9]{1,2}$ && "$mask" -le 32 ]] || return 1

    # Convert IP to integer
    local IFS='.'
    local -a ip_parts net_parts
    read -ra ip_parts <<< "$ip"
    read -ra net_parts <<< "$net"
    local ip_int=$(( (ip_parts[0] << 24) + (ip_parts[1] << 16) + (ip_parts[2] << 8) + ip_parts[3] ))
    local net_int=$(( (net_parts[0] << 24) + (net_parts[1] << 16) + (net_parts[2] << 8) + net_parts[3] ))
    local mask_int=0
    (( mask > 0 )) && mask_int=$(( (0xFFFFFFFF << (32 - mask)) & 0xFFFFFFFF ))

    (( (ip_int & mask_int) == (net_int & mask_int) ))
}

# Is $1 an exact entry or inside a CIDR of the comma-separated list $2?
_api_ip_in_list() {
    local ip="$1" list="$2" entry
    local IFS=','
    for entry in $list; do
        entry="${entry// /}"
        [[ -z "$entry" ]] && continue
        [[ "${ip,,}" == "${entry,,}" ]] && return 0
        [[ "$entry" == */* ]] && _api_ip_in_cidr "$ip" "$entry" && return 0
    done
    return 1
}

# Resolve the client IP for this request into CLIENT_IP. socat exposes the TCP
# peer as SOCAT_PEERADDR (ncat: NCAT_REMOTE_ADDR). When that peer is a trusted
# proxy, X-Forwarded-For is walked from the right, skipping trusted hops, so a
# client cannot spoof its address by sending its own X-Forwarded-For header.
_api_resolve_client_ip() {
    CLIENT_IP="${SOCAT_PEERADDR-}"
    [[ -z "$CLIENT_IP" ]] && CLIENT_IP="${NCAT_REMOTE_ADDR-}"
    [[ -z "$CLIENT_IP" ]] && CLIENT_IP="127.0.0.1"
    if [[ -n "$API_TRUSTED_PROXIES" && -n "${REQUEST_XFF_HEADER:-}" ]] && _api_ip_in_list "$CLIENT_IP" "$API_TRUSTED_PROXIES"; then
        local -a hops
        local IFS=','
        read -ra hops <<< "$REQUEST_XFF_HEADER"
        local i hop
        for (( i = ${#hops[@]} - 1; i >= 0; i-- )); do
            hop="${hops[$i]//[[:space:]]/}"; hop="${hop,,}"
            # IPv4, or IPv6 (an IPv6 hop used to end the walk: every IPv6 client then had the proxy's address and one lockout)
            [[ "$hop" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ || ( ${#hop} -le 45 && "$hop" == *:* && "$hop" =~ ^[0-9a-f:]+(:[0-9]{1,3}(\.[0-9]{1,3}){3})?$ ) ]] || break
            if _api_ip_in_list "$hop" "$API_TRUSTED_PROXIES"; then
                continue
            fi
            CLIENT_IP="$hop"
            break
        done
    fi
}

# Check if the connecting IP is allowed (CLIENT_IP is set by handle_request)
_api_check_ip_whitelist() {
    [[ -z "$API_IP_WHITELIST" ]] && return 0  # no whitelist = allow all

    local client_ip="${CLIENT_IP:-127.0.0.1}"

    # Always allow localhost
    case "$client_ip" in
        127.0.0.1|::1|localhost) return 0 ;;
    esac

    _api_ip_in_list "$client_ip" "$API_IP_WHITELIST"
}

# _api_rate_window FILE LIMIT SECONDS — a sliding window kept as one timestamp per line in FILE:
# returns 1 when LIMIT calls already landed in the last SECONDS, otherwise records this one
_api_rate_window() {
    local rate_file="$1" limit="$2" window="$3" now count=0 cutoff ts tmp_file
    now=$(date +%s); cutoff=$(( now - window ))
    [[ -d "$(dirname "$rate_file")" ]] || mkdir -p "$(dirname "$rate_file")" 2>/dev/null
    # one request at a time per window (FILE.lock): parallel ones each counted the same old lines and all passed
    (
        command -v flock >/dev/null 2>&1 && { flock -w 5 9 || exit 1; }
        if [[ -f "$rate_file" ]]; then
            # Remove expired timestamps and count valid ones
            tmp_file="${rate_file}.tmp"
            while IFS= read -r ts; do
                [[ "$ts" =~ ^[0-9]+$ ]] || continue
                if (( ts > cutoff )); then
                    echo "$ts"
                    count=$(( count + 1 ))
                fi
            done < "$rate_file" > "$tmp_file" 2>/dev/null
            mv -f "$tmp_file" "$rate_file" 2>/dev/null
        fi
        (( count >= limit )) && exit 1
        echo "$now" >> "$rate_file"
        exit 0
    ) 9>"$rate_file.lock"
}

# Check global rate limit for the connecting IP
# Returns 0 if within limit, 1 if rate limited
_api_check_global_rate_limit() {
    (( API_RATE_LIMIT <= 0 )) && return 0  # rate limiting disabled

    local client_ip="${CLIENT_IP:-127.0.0.1}"

    # Always allow localhost without rate limiting
    case "$client_ip" in
        127.0.0.1|::1|localhost) return 0 ;;
    esac

    # Rate file per IP (sanitize the IP for filename)
    local safe_ip="${client_ip//[^0-9a-fA-F.]/_}"
    _api_rate_window "${API_RATE_DIR}/${safe_ip}" "$API_RATE_LIMIT" "$API_RATE_WINDOW"
}

# Check authentication from request headers — sets AUTH_USERNAME and AUTH_ROLE
# Returns 0 on success, 1 on failure
_api_check_auth() {
    AUTH_USERNAME=""
    AUTH_ROLE=""
    AUTH_VIA_KEY=""; AUTH_KEY_ID=""      # (a worker serves many requests: nothing of the one before may stay)

    # If auth is disabled, allow everything
    if [[ "$API_AUTH_ENABLED" != "true" ]]; then
        AUTH_USERNAME="anonymous"
        AUTH_ROLE="admin"
        return 0
    fi
    # a one-time download link (POST /backups/download-link) the router found good for this very path: its admin's request
    if [[ -n "${DL_TICKET_USER:-}" ]]; then
        AUTH_USERNAME="$DL_TICKET_USER"; AUTH_ROLE="admin"
        return 0
    fi
    [[ -n "${QUERY_PARAMS[ticket]:-}" ]] && AUTH_ERROR="This download link has expired or was used already: start the download again from the Backups page."

    # First-run window: no account exists yet and setup has never completed
    # (fresh install or factory reset). Only what the setup wizard needs is
    # reachable anonymously — the public routes handled before this check plus
    # GET /version — so that an API exposed on the network can't be driven by
    # a bystander before the owner has created the admin account.
    # A node has no first admin and no wizard, so there is no window to keep open: an empty users.json there means
    # "not joined yet" (the hub's account arrives with the join), and a token is simply required.
    local user_count
    user_count=$(_api_user_count)
    if ! _api_is_node && [[ "$user_count" -eq 0 ]] && [[ ! -f "$API_AUTH_DIR/.setup-complete" ]]; then
        if [[ "${REQUEST_METHOD:-GET}" == "GET" && "${REQUEST_PATH:-/}" == "/version" ]]; then
            AUTH_USERNAME="anonymous"
            AUTH_ROLE="admin"
            return 0
        fi
        AUTH_ERROR="Setup required: create the first admin account with POST /auth/setup before using this endpoint."
        return 1
    fi

    _api_init_auth_dir

    # Extract token from Authorization header or ?token= query parameter
    local token=""
    if [[ -n "${REQUEST_AUTH_HEADER:-}" ]]; then
        # Strip "Bearer " prefix
        token="${REQUEST_AUTH_HEADER#Bearer }"
        token="${token#bearer }"
    fi

    # Fallback: check query parameter (needed for EventSource/SSE which can't set headers)
    if [[ -z "$token" && -n "${QUERY_PARAMS[token]:-}" ]]; then
        token="${QUERY_PARAMS[token]}"
    fi

    # an API key: its own header, or in place of a session token
    if [[ -z "$token" && -n "${REQUEST_API_KEY:-}" ]]; then token="$REQUEST_API_KEY"; fi

    if [[ -z "$token" ]]; then
        return 1
    fi

    AUTH_VIA_KEY=""; AUTH_KEY_ID=""
    if [[ "$token" == dcs_* ]]; then
        _api_validate_key "$token" || return 1
    elif ! _api_validate_token "$token"; then
        return 1
    fi
    # The credential must not linger in QUERY_PARAMS: _api_cached folds
    # every parameter into the cache file's name, which would write the
    # token to disk and give each token its own copy of the answer.
    unset 'QUERY_PARAMS[token]'
    return 0
}

# Check if authenticated user is admin — call after _api_check_auth
_api_check_admin() {
    [[ "${AUTH_ROLE:-}" == "admin" ]] && return 0
    # Bot accounts pass for the operations on their allow-list only
    if [[ "${AUTH_ROLE:-}" == "bot" ]] && _api_bot_allowed "${method:-}" "${path:-}"; then
        return 0
    fi
    return 1
}

# Bot accounts (role "bot") drive day-to-day operations from chat: they read
# what a user can plus the audit log, backups and update checks, and may start,
# stop, restart and update stacks and containers, deploy templates, run backups
# and schedules, prune, and lift CrowdSec bans — on this server and, through
# the hub's proxy, on fleet members (the same list applies to the inner path).
# Accounts, secrets, files, the host, the network and DCS itself stay with
# admins. Bots keep several sessions.
_api_bot_allowed() {
    local m="$1" p="$2"
    case "$m" in
        GET)
            # A bot reads more than a viewer on purpose: the audit log and the
            # operational views an automation account legitimately needs. The
            # route-policy tripwire records each case where bot ≠ viewer.
            case "$p" in
                /env|/stacks/*/env|/secrets|/secrets/*|/terminal/*|/containers/*/files|/containers/*/files/*|\
                /export/*|/auth/users|/auth/invites|/auth/sessions|/auth/keys|/ssh/*|/recovery|/recovery/*|/snapshots/*/download|\
                /system/crontab|/system/crontab/*|/dns/records|/plugins/*/hooks|/plugins/*/hooks/*|/containers/*/reset|/traefik/feed/*|/alerts/config|\
                /fleet/join-tokens|/fleet/discover|/fleet/jobs|/fleet/jobs/*|/fleet/provision/*|/proxmox/capabilities|/proxmox/storage|/fleet/members/*/terminal|\
                /backups/*/download|/backups/*/checksum|/fleet/members/*/backups/*|/authelia/verification-code|/feed/status|/stacks/*/files)
                    return 1 ;;
            esac
            return 0 ;;
        POST)
            # a guest's snapshots (take, roll back) are an admin's: a rollback throws away what changed since
            case "$p" in /proxmox/vms/*/snapshots|/proxmox/vms/*/snapshots/*) return 1 ;; esac
            case "$p" in
                /auth/logout|/auth/refresh|/settings/dashboard|/settings/profile|\
                /containers/*/start|/containers/*/stop|/containers/*/restart|/containers/*/recreate|\
                /stacks/*/start|/stacks/*/stop|/stacks/*/restart|/stacks/*/update|/batch/stacks|/batch/update|\
                /images/check-updates|/fleet/images/check|/images/*/update|/images/update-all|/templates/*/dry-run|/templates/*/deploy|\
                /backups/trigger|/maintenance/prune|/maintenance/image-prune|/sablier/repair|\
                /schedules/*/run|/automations/*/run|/crowdsec/unban-me|/routes/reconcile|\
                /power/sample|/metrics/snapshot|/notifications/test|/homarr/register|/proxmox/vms/*|/fleet/members/*/api/*)
                    return 0 ;;
            esac
            return 1 ;;
        DELETE)
            case "$p" in
                /crowdsec/decisions/*|/fleet/members/*/api/*) return 0 ;;
            esac
            return 1 ;;
    esac
    return 1
}

# Role policy for a route, applied by the router right after authentication.
# Admins may call everything. The "user" role is a viewer: it can read
# operational data and manage its own session/profile, but every request that
# changes the system, executes code or exposes secrets requires admin.
# Handlers keep their own _api_check_admin calls as defence in depth.
_api_route_allowed() {
    local method="$1" path="$2"
    [[ "${AUTH_ROLE:-}" == "admin" ]] && return 0
    # An API key is not an account: nothing of accounts, sessions or keys, no terminal, no settings of a person; a
    # "read" key reads and does nothing else
    if [[ "${AUTH_VIA_KEY:-}" == "true" ]]; then
        case "$path" in /auth/*|/terminal/*|/ssh/*|/chat/*) return 1 ;; esac
        [[ "$method" != "GET" && "$path" == /settings/* ]] && return 1
        [[ "${AUTH_ROLE:-}" == "user" && "$method" != "GET" ]] && return 1
    fi
    if [[ "${AUTH_ROLE:-}" == "bot" ]]; then
        # a bot account is not a person: the chat room is not for it
        [[ "$path" == /chat/* ]] && return 1
        _api_bot_allowed "$method" "$path"
        return $?
    fi
    case "$method" in
        GET)
            case "$path" in
                /env|/stacks/*/env|/snapshots|/snapshots/*|/audit|/terminal/history|\
                /backups|/backups/*|/secrets|/secrets/*|/system/crontab|/system/crontab/*|\
                /system/update/check|/system/update/history|/system/os-update/*|/ddns/status|/dns/records|/dns/zones|\
                /recovery|/recovery/*|/alerts/config|/terminal/web|/feed/status|/stacks/*/files|\
                /plugins/*/hooks|/plugins/*/hooks/*|/plugins/*/logs|/plugins/*/cards/*/source|\
                /containers/*/files|/containers/*/files/*|/containers/*/reset|/export/config|\
                /auth/users|/auth/invites|/auth/sessions|/auth/keys|/ssh/*|/templates/deploy-history|/traefik/feed/*|/fleet/join-tokens|/fleet/discover|/authelia/verification-code|\
                /fleet/jobs|/fleet/jobs/*|/fleet/templates|/fleet/templates/*|/fleet/versions|/fleet/provision/*|/proxmox/capabilities|/proxmox/storage|/fleet/members/*/terminal|\
                /fleet/members/*/backups/*)
                    return 1 ;;
            esac
            return 0 ;;
        *)
            case "$path" in
                /auth/logout|/auth/refresh|/auth/totp/*|/settings/dashboard|/settings/profile|\
                /setup/configure|/setup/complete|/stacks/*/compose/validate|\
                /env/validate|/templates/*/dry-run|/crowdsec/unban-me|/crowdsec/notifications/preview)
                    return 0 ;;
                # the chat: send, edit or delete one's own message, say one is typing (the handlers check whose it is;
                # clearing the whole room is DELETE /chat/messages, admin only)
                /chat/messages/*|/chat/typing) return 0 ;;
                /chat/messages) [[ "$method" == "POST" ]]; return ;;
            esac
            return 1 ;;
    esac
}

# Apply a jq filter to a JSON state file atomically under an exclusive lock.
# Usage: _api_jq_update_file FILE [jq options...] FILTER
_api_jq_update_file() {
    local file="$1"; shift
    (
        flock -w 5 200 || exit 1
        local out
        out=$(jq "$@" "$file" 2>/dev/null) || exit 1
        [[ -n "$out" ]] || exit 1
        printf '%s\n' "$out" > "$file.tmp" && chmod 600 "$file.tmp" 2>/dev/null && mv -f "$file.tmp" "$file"
    ) 200>"$file.lock"
}

# _api_state_file FILE DEFAULT [array|object] — make sure a JSON state file
# exists and holds valid JSON of the expected shape. A file left empty or
# corrupt (a crash mid-write, a full disk) is moved aside as FILE.corrupt-<ts>
# and replaced by DEFAULT, so one bad file never turns responses into broken
# JSON. Returns 0 when the file was fine, 1 when it was created or repaired.
_api_state_file() {
    local file="$1" default="$2" type="${3:-}" dir
    dir=$(dirname "$file")
    [[ -d "$dir" ]] || mkdir -p "$dir" 2>/dev/null || true
    if [[ ! -e "$file" ]]; then
        printf '%s\n' "$default" > "$file" 2>/dev/null || true
        chmod 600 "$file" 2>/dev/null || true
        return 1
    fi
    if [[ -s "$file" ]] && jq -e --arg t "$type" 'if $t == "" then true else type == $t end' "$file" >/dev/null 2>&1; then
        return 0
    fi
    local ts
    ts=$(date -u '+%Y%m%dT%H%M%SZ')
    mv -f "$file" "$file.corrupt-$ts" 2>/dev/null || true
    printf '%s\n' "$default" > "$file" 2>/dev/null || true
    chmod 600 "$file" 2>/dev/null || true
    echo "$(date '+%Y-%m-%d %H:%M:%S') state file repaired: $file was empty or corrupt (kept as $file.corrupt-$ts)" >&2
    _audit_log "STATE_FILE_REPAIRED" "$file (copy kept as .corrupt-$ts)" 2>/dev/null || true
    return 1
}

# Format a byte count for humans (K/M/G with one decimal)
_api_fmt_bytes() {
    local b="${1:-0}"
    [[ "$b" =~ ^[0-9]+$ ]] || b=0
    if (( b >= 1073741824 )); then printf '%d.%dG' $(( b / 1073741824 )) $(( (b % 1073741824) * 10 / 1073741824 ))
    elif (( b >= 1048576 )); then printf '%d.%dM' $(( b / 1048576 )) $(( (b % 1048576) * 10 / 1048576 ))
    elif (( b >= 1024 )); then printf '%dK' $(( b / 1024 ))
    else printf '%dB' "$b"; fi
}

# Validate an image reference (name[:tag][@digest]) — rejects option-like and
# shell-hostile values before it reaches docker.
_api_validate_image_ref() {
    local ref="$1"
    if [[ -z "$ref" || ${#ref} -gt 255 || ! "$ref" =~ ^[a-zA-Z0-9][a-zA-Z0-9._:/@-]*$ ]]; then
        _api_error 400 "Invalid image reference"
        return 1
    fi
    return 0
}

# Validate a stack name — rejects path traversal, shell metacharacters, etc.
# Returns 0 if valid, 1 if invalid (and sends 400 error response)
_api_validate_stack_name() {
    local name="$1"
    if [[ -z "$name" ]]; then
        _api_error 400 "Stack name is required"
        return 1
    fi
    # Reject path separators, parent traversal, leading dots
    # Note: null byte check removed — bash strings cannot contain \0, and $'\0' in [[ ]]
    # degrades to an empty string making the pattern ** which matches everything
    if [[ "$name" == *"/"* ]] || [[ "$name" == *".."* ]] || [[ "$name" == "."* ]]; then
        _api_error 400 "Invalid stack name"
        return 1
    fi
    # Enforce safe pattern: alphanumeric start, then alphanumeric/underscore/hyphen
    if [[ ! "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]*$ ]]; then
        _api_error 400 "Invalid stack name"
        return 1
    fi
    # Final realpath check — resolved path must stay within COMPOSE_DIR
    local resolved
    resolved=$(realpath -m "$COMPOSE_DIR/$name" 2>/dev/null)
    if [[ "$resolved" != "$COMPOSE_DIR/$name" ]] && [[ "$resolved" != "$COMPOSE_DIR/"* ]]; then
        _api_error 400 "Invalid stack name"
        return 1
    fi
    return 0
}

# Validate a resource name (container, network, volume, image, template, etc.)
# Returns 0 if valid, 1 if invalid (and sends 400 error response)
_api_validate_resource_name() {
    local name="$1" resource_type="${2:-resource}"
    if [[ -z "$name" ]]; then
        _api_error 400 "${resource_type} name is required"
        return 1
    fi
    # Reject path traversal and shell metacharacters
    # Note: null byte check removed — bash strings cannot contain \0, and $'\0' in [[ ]]
    # degrades to an empty string making the pattern ** which matches everything
    if [[ "$name" == *".."* ]] || [[ "$name" == *"/"* ]]; then
        _api_error 400 "Invalid ${resource_type} name"
        return 1
    fi
    # shellcheck disable=SC1003
    case "$name" in
        *';'*|*'|'*|*'`'*|*'$('*|*'&'*|*'>'*|*'<'*)
            _api_error 400 "Invalid ${resource_type} name"
            return 1
            ;;
    esac
    # Enforce safe pattern: alphanumeric start, then alphanumeric/dot/underscore/hyphen/colon
    if [[ ! "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9._:/-]*$ ]]; then
        _api_error 400 "Invalid ${resource_type} name"
        return 1
    fi
    return 0
}

# =============================================================================
# COMPOSE SECURITY SCANNER
# =============================================================================
# Scans docker-compose YAML content for dangerous Docker features that could
# allow container escape, host compromise, or privilege escalation.
# Returns 0 if safe, 1 if dangerous (and sends 400 error response with details).
#
# This prevents the #1 Docker attack vector: deploying a privileged container
# that mounts the host filesystem, escapes, and installs malware (e.g., crypto miners).
# =============================================================================

_api_scan_compose_security() {
    local content="$1"
    local context="${2:-compose file}"
    local mode="${3:-strict}"  # "strict" = block everything, "deploy" = allow docker.sock (trusted templates)
    local -a violations=()

    # SECURITY: Pre-resolve ${VAR:-default} patterns before scanning.
    # This prevents bypass via `privileged: ${X:-true}` which Docker Compose
    # resolves to `privileged: true` at runtime. We scan the resolved version.
    local resolved_content
    resolved_content=$(printf '%s' "$content" | sed 's/\${[A-Za-z_][A-Za-z0-9_]*:-\([^}]*\)}/\1/g')

    # Convert to lowercase for case-insensitive matching
    # Use resolved content for scanning (catches ${VAR:-dangerous} bypass)
    local lower_content="${resolved_content,,}"

    # ── CRITICAL: Container escape vectors ──
    # NOTE: We check for the KEY existing at all (not just specific values) for the most
    # dangerous features. This prevents bypass via YAML anchors, aliases, or variable
    # substitution (e.g., `privileged: *anchor` or `privileged: ${VAR:-true}`).

    # ── CRITICAL: Build context (Dockerfile can execute arbitrary code) ──
    # Block `build:` directive entirely — only pre-built images are allowed.
    # A Dockerfile can RUN any command during build, bypassing all runtime checks.
    if printf '%s' "$lower_content" | grep -qE '^\s+build:\s'; then
        violations+=("'build:' directive is not allowed — only pre-built images (image:) are permitted. Dockerfiles can execute arbitrary code during build.")
    fi

    # ── CRITICAL: File inclusion directives (can reference files outside App-Data) ──
    # `extends:` includes another compose file which may contain dangerous directives
    # that bypass our scanner (the included file is never scanned)
    if [[ "$mode" == "strict" ]]; then
        if printf '%s' "$lower_content" | grep -qE '^\s+extends:\s'; then
            violations+=("'extends:' directive is not allowed in user-edited compose files (can include unscanned external files)")
        fi
    fi

    # ── CRITICAL: Container escape vectors ──
    # privileged mode = full host access (most dangerous)
    if [[ "$mode" == "strict" ]]; then
        # Strict: block ANY use of privileged key
        if printf '%s' "$lower_content" | grep -qE '^\s+privileged:\s'; then
            violations+=("'privileged' key is not allowed in user-edited compose files (container escape risk)")
        fi
    else
        # Deploy: block privileged: true/yes AND YAML aliases (*anchor)
        # This prevents bypass via `x-p: &p true` + `privileged: *p`
        if printf '%s' "$lower_content" | grep -qE '^\s+privileged:\s*(true|yes|\*[a-z])'; then
            violations+=("privileged mode is not allowed (grants full host access). Template requires manual approval via --allow-privileged flag.")
        fi
    fi

    # Host PID namespace = can see/kill host processes
    if printf '%s' "$lower_content" | grep -qE '^\s+pid:\s*["'"'"']?host'; then
        violations+=("host PID namespace is not allowed (exposes host processes)")
    fi

    # Host network = bypass network isolation
    if printf '%s' "$lower_content" | grep -qE '^\s+network_mode:\s*["'"'"']?host'; then
        violations+=("host network mode is not allowed (bypasses network isolation)")
    fi

    # Host IPC namespace
    if printf '%s' "$lower_content" | grep -qE '^\s+ipc:\s*["'"'"']?host'; then
        violations+=("host IPC namespace is not allowed")
    fi

    # userns_mode: host = share user namespace with host
    if printf '%s' "$lower_content" | grep -qE '^\s+userns_mode:\s*["'"'"']?host'; then
        violations+=("host user namespace is not allowed")
    fi

    # cgroup_parent = custom cgroup (can escape resource limits)
    if printf '%s' "$lower_content" | grep -qE '^\s+cgroup_parent:\s'; then
        violations+=("cgroup_parent is not allowed")
    fi

    # ── HIGH: Dangerous volume mounts ──

    # Mount host root filesystem
    if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/:/'; then
        violations+=("mounting host root filesystem (/) is not allowed")
    fi

    # Mount /etc directly (system config) — but allow specific subdirs like /etc/localtime
    # Block: "- /etc:/something" or bare "- /etc"
    # Allow: "- /etc/localtime:/etc/localtime:ro" or "- /etc/timezone:/etc/timezone:ro"
    if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/etc["'"'"']?(:|[[:space:]]|$)'; then
        # Only flag if mounting /etc root, not a subdirectory like /etc/localtime
        local etc_lines
        etc_lines=$(printf '%s' "$lower_content" | grep -E '^\s+-\s*["'"'"']?/etc["'"'"']?(:|[[:space:]]|$)')
        if echo "$etc_lines" | grep -qvE '/etc/'; then
            violations+=("mounting /etc is not allowed (contains system configuration)")
        fi
    fi

    # Mount /root (root home directory)
    if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/root[/:]'; then
        violations+=("mounting /root is not allowed")
    fi

    # Mount /proc or /sys (kernel interfaces) — strict mode only
    # In deploy mode, monitoring tools (Netdata, Dashdot) need :ro access to /proc and /sys
    if [[ "$mode" == "strict" ]]; then
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/(proc|sys)[/:]'; then
            violations+=("mounting /proc or /sys is not allowed (kernel interface access)")
        fi
    else
        # Even in deploy mode, block writable /proc or /sys mounts
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/(proc|sys)[/:]' && \
           ! printf '%s' "$lower_content" | grep -E '^\s+-\s*["'"'"']?/(proc|sys)[/:]' | grep -q ':ro'; then
            violations+=("mounting /proc or /sys without :ro is not allowed")
        fi
    fi

    # /dev (device access). In a compose file someone edits (strict): only /dev/null, /dev/urandom, /dev/random.
    # In a built-in template (deploy): one device, or one folder of devices, is what a VPN client (/dev/net/tun), a
    # Zigbee or Z-Wave stick, a printer's serial port, a UPS on USB or a disk-health exporter is there for, so it
    # passes; the whole of /dev and the machine's memory stay refused. (This rule used to refuse every device in both
    # modes, so those templates could not be deployed at all.)
    local _dev_lines
    _dev_lines=$(printf '%s' "$lower_content" | grep -E '^\s+-\s*["'"'"']?/dev[/:]' || true)
    if [[ -n "$_dev_lines" ]]; then
        if [[ "$mode" == "strict" ]]; then
            if ! printf '%s' "$_dev_lines" | grep -qE '/dev/(null|urandom|random)'; then
                violations+=("mounting /dev is not allowed (device access)")
            fi
        elif printf '%s' "$_dev_lines" | grep -qE '^\s+-\s*["'"'"']?/dev/?:' || printf '%s' "$_dev_lines" | grep -qE '/dev/(mem|kmem|port)([:"'"'"'/[:space:]]|$)'; then
            violations+=("mounting the whole of /dev, or the machine's memory, is not allowed (name the one device the app needs)")
        fi
    fi

    # Mount Docker socket — container escape via Docker API
    # In "deploy" mode, allow docker.sock (trusted built-in templates need it for
    # Portainer, Watchtower, Docker Socket Proxy, etc.)
    # In "strict" mode (user compose edits), block it entirely
    if [[ "$mode" == "strict" ]]; then
        if printf '%s' "$lower_content" | grep -qE 'docker\.sock'; then
            violations+=("mounting docker.sock is not allowed in user-edited compose files (use docker-socket-proxy template instead)")
        fi
    fi

    # Mount /boot (bootloader access)
    if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/boot[/:]'; then
        violations+=("mounting /boot is not allowed")
    fi

    # Mount /var/run (runtime sockets including Docker) — only in strict mode
    # In deploy mode, some templates mount /var/run/docker.sock specifically
    if [[ "$mode" == "strict" ]]; then
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/var/run[/:]'; then
            violations+=("mounting /var/run is not allowed (contains system sockets)")
        fi
    fi

    # Mount /home with write access (user data access)
    if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/home[/:]' | grep -vq ':ro'; then
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*["'"'"']?/home[/:]' && \
           ! printf '%s' "$lower_content" | grep -E '^\s+-\s*["'"'"']?/home[/:]' | grep -q ':ro'; then
            violations+=("mounting /home with write access is not allowed")
        fi
    fi

    # ── MEDIUM: Dangerous capabilities ──
    # NOTE: In Docker Compose YAML, cap_add and the capability name are on SEPARATE lines:
    #   cap_add:
    #     - SYS_ADMIN
    # So we must check for the capability value as a standalone line, not on the same line as cap_add.
    # We look for the capability name in list items (- SYS_ADMIN) anywhere in the file.

    # In strict mode, block all dangerous capabilities.
    # In deploy mode, allow them (trusted templates like Netdata need SYS_ADMIN/SYS_PTRACE).
    if [[ "$mode" == "strict" ]]; then
        local -a _dangerous_caps=(sys_admin sys_ptrace net_admin net_raw sys_rawio sys_module dac_override dac_read_search)
        for _cap in "${_dangerous_caps[@]}"; do
            if printf '%s' "$lower_content" | grep -qE "^\s+-\s*[\"']?${_cap}[\"']?\s*$"; then
                violations+=("${_cap^^} capability is not allowed (container escape / privilege escalation risk)")
            fi
        done
        if printf '%s' "$lower_content" | grep -qE 'cap_add:\s*\[.*\b(sys_admin|sys_ptrace|net_admin|net_raw|sys_rawio|sys_module)\b'; then
            violations+=("Dangerous capabilities detected in inline cap_add format")
        fi
    fi

    # ── MEDIUM: Security options ──
    # In strict mode, block disabling security profiles.
    # In deploy mode, allow (trusted templates like Netdata need apparmor:unconfined).
    if [[ "$mode" == "strict" ]]; then
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*[\"'"'"']?apparmor[=:]unconfined'; then
            violations+=("disabling AppArmor is not allowed")
        fi
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*[\"'"'"']?seccomp[=:]unconfined'; then
            violations+=("disabling seccomp is not allowed")
        fi
        if printf '%s' "$lower_content" | grep -qE '^\s+-\s*[\"'"'"']?label[=:]disable'; then
            violations+=("disabling SELinux labels is not allowed")
        fi
        if printf '%s' "$lower_content" | grep -qE 'security_opt:\s*\[.*\b(apparmor|seccomp)[=:]unconfined\b'; then
            violations+=("Dangerous security_opt detected in inline format")
        fi
    fi

    # ── MEDIUM: Variable substitution bypass detection ──
    # Attackers can wrap dangerous values in ${VAR:-value} to bypass text scanning.
    # Docker Compose resolves these at runtime, so we must detect them.
    # Check for patterns like: privileged: ${ANYTHING:-true}
    if printf '%s' "$lower_content" | grep -qE 'privileged:\s*\$\{[^}]*:-\s*true\s*\}'; then
        violations+=("privileged with variable substitution default detected (bypass attempt)")
    fi
    if printf '%s' "$lower_content" | grep -qE 'pid:\s*\$\{[^}]*:-\s*host\s*\}'; then
        violations+=("host PID namespace via variable substitution default detected")
    fi
    if printf '%s' "$lower_content" | grep -qE 'network_mode:\s*\$\{[^}]*:-\s*host\s*\}'; then
        violations+=("host network mode via variable substitution default detected")
    fi
    if printf '%s' "$lower_content" | grep -qE 'ipc:\s*\$\{[^}]*:-\s*host\s*\}'; then
        violations+=("host IPC namespace via variable substitution default detected")
    fi

    # ── Report results ──

    if [[ ${#violations[@]} -gt 0 ]]; then
        local details=""
        for v in "${violations[@]}"; do
            details="${details}${details:+; }$v"
        done
        if [[ "${_API_SCAN_QUIET:-false}" == "true" ]]; then
            # Collect-only mode: print the findings and let the caller decide
            printf '%s' "$details"
            return 1
        fi
        _api_error 403 "Security policy violation in ${context}: ${details}"
        return 1
    fi

    return 0
}

# Validate a URL for SSRF protection — blocks private/internal IPs
# Returns 0 if safe, 1 if blocked (and sends 400 error response)
_api_validate_url() {
    local url="$1" context="${2:-URL}"

    # Must be http(s) or git@
    if [[ ! "$url" =~ ^https?:// ]] && [[ ! "$url" =~ ^git@ ]]; then
        _api_error 400 "$context must use http://, https://, or git@ scheme"
        return 1
    fi

    # Extract hostname from URL
    local host
    host=$(echo "$url" | sed -E 's|^https?://||; s|^git@||; s|[:/].*||; s|@.*||')

    if [[ -z "$host" ]]; then
        _api_error 400 "Cannot parse hostname from $context"
        return 1
    fi

    # Block obvious internal/private hostnames
    case "$host" in
        localhost|*.local|*.internal|*.localhost)
            _api_error 400 "$context blocked: private hostname ($host)"
            return 1
            ;;
    esac

    # Resolve hostname to IP and check for private ranges
    local resolved_ip
    resolved_ip=$(getent hosts "$host" 2>/dev/null | awk '{print $1; exit}')
    # Also try dig if getent fails
    [[ -z "$resolved_ip" ]] && resolved_ip=$(dig +short "$host" 2>/dev/null | head -1)

    if [[ -n "$resolved_ip" ]]; then
        case "$resolved_ip" in
            # IPv4 private ranges
            10.*|172.1[6-9].*|172.2[0-9].*|172.3[0-1].*|192.168.*) ;;
            # Loopback
            127.*) ;;
            # Link-local / metadata (AWS, GCP, Azure)
            169.254.*|100.100.100.200) ;;
            # IPv6 loopback/link-local
            ::1|fe80:*|fd*) ;;
            # Safe — skip blocking
            *) return 0 ;;
        esac
        _api_error 400 "$context blocked: resolves to private/internal address ($resolved_ip)"
        return 1
    fi

    # SECURITY: If we can't resolve the hostname, BLOCK the request.
    # This prevents DNS rebinding attacks where the hostname intentionally fails
    # resolution on the first attempt but succeeds when curl fetches it.
    _api_error 400 "$context blocked: hostname '$host' could not be resolved"
    return 1
}

# Rate limiting: check if an IP is locked out.
# Writes go through _api_jq_update_file (tmp + flock + mv), so the file a
# reader sees is always a complete, valid document — a half-written or
# corrupt file can never read as "no record" and silently disable the
# lockout, and concurrent failed logins each increment the counter.
_api_check_rate_limit() {
    local client_ip="${1:-unknown}"
    command -v jq >/dev/null 2>&1 || return 0
    local rate_file="$API_AUTH_DIR/rate_limits.json"
    _api_state_file "$rate_file" '{}' object >/dev/null

    local now locked_until
    now=$(date +%s)
    locked_until=$(jq -r --arg ip "$client_ip" '.[$ip].locked_until // 0' "$rate_file" 2>/dev/null)
    [[ "$locked_until" =~ ^[0-9]+$ ]] || locked_until=0
    (( locked_until > now )) && return 1
    # Reset an expired lock so the next failure starts a fresh count
    (( locked_until > 0 )) && _api_reset_rate_limit "$client_ip"
    return 0
}

# Rate limiting: record a failed login attempt
_api_record_failed_login() {
    local client_ip="${1:-unknown}"
    command -v jq >/dev/null 2>&1 || return 0
    local rate_file="$API_AUTH_DIR/rate_limits.json"
    _api_state_file "$rate_file" '{}' object >/dev/null

    local now max lock
    now=$(date +%s)
    max="$API_MAX_LOGIN_ATTEMPTS";   [[ "$max"  =~ ^[0-9]+$ ]] || max=5
    lock="$API_LOCKOUT_DURATION";  [[ "$lock" =~ ^[0-9]+$ ]] || lock=900

    _api_jq_update_file "$rate_file" \
        --arg ip "$client_ip" \
        --argjson now "$now" \
        --argjson max "$max" \
        --argjson lock "$lock" \
        '(.[$ip].attempts // 0) + 1 as $a | .[$ip] = {"attempts": $a, "locked_until": (if $a >= $max then $now + $lock else 0 end), "last_attempt": $now}'
}

# _api_claim_login_attempt IP — a sign-in attempt from IP counts before its password is looked at, in one step under the
# lock of rate_limits.json: 1 (nothing counted) while IP is locked out; otherwise the attempt is counted, the lockout starts
# with the API_MAX_LOGIN_ATTEMPTS-th, and a success resets it (_api_reset_rate_limit). Counted after the check, parallel
# wrong passwords all passed the check before the first of them was counted.
_api_claim_login_attempt() {
    local client_ip="${1:-unknown}" rate_file="$API_AUTH_DIR/rate_limits.json" now max lock
    command -v jq >/dev/null 2>&1 || return 0
    _api_state_file "$rate_file" '{}' object >/dev/null
    now=$(date +%s)
    max="$API_MAX_LOGIN_ATTEMPTS";   [[ "$max"  =~ ^[0-9]+$ ]] || max=5
    lock="$API_LOCKOUT_DURATION";  [[ "$lock" =~ ^[0-9]+$ ]] || lock=900
    (
        flock -w 5 200 || exit 1
        local out
        out=$(jq --arg ip "$client_ip" --argjson now "$now" --argjson max "$max" --argjson lock "$lock" '
            if (.[$ip].locked_until // 0) > $now then empty
            else ((if (.[$ip].locked_until // 0) > 0 then 0 else (.[$ip].attempts // 0) end) + 1) as $a
                | .[$ip] = {"attempts": $a, "locked_until": (if $a >= $max then $now + $lock else 0 end), "last_attempt": $now} end' "$rate_file" 2>/dev/null) || exit 1
        [[ -n "$out" ]] || exit 1
        printf '%s\n' "$out" > "$rate_file.tmp" && chmod 600 "$rate_file.tmp" 2>/dev/null && mv -f "$rate_file.tmp" "$rate_file"
    ) 200>"$rate_file.lock"
}

# Rate limiting: reset after successful login
_api_reset_rate_limit() {
    local client_ip="${1:-unknown}"
    local rate_file="$API_AUTH_DIR/rate_limits.json"
    [[ -f "$rate_file" ]] || return 0
    command -v jq >/dev/null 2>&1 || return 0
    _api_jq_update_file "$rate_file" --arg ip "$client_ip" 'del(.[$ip])'
}

# Clean up expired tokens (called periodically)
_api_cleanup_expired_tokens() { _api_with_auth_lock tokens _api_cleanup_expired_tokens_locked; }
_api_cleanup_expired_tokens_locked() {
    local tokens
    tokens=$(_api_read_auth_file "tokens.json")
    local now
    now=$(date +%s)

    if command -v jq >/dev/null 2>&1; then
        local cleaned
        cleaned=$(echo "$tokens" | jq --argjson n "$now" '[.[] | select(.expires_at > $n)]' 2>/dev/null)
        [[ -n "$cleaned" ]] && _api_write_auth_file "tokens.json" "$cleaned"
    fi
}

# Store an invite code
_api_store_invite() {
    local code="$1" role="$2" created_by="$3"
    local now
    now=$(date +%s)
    local expires_at=$(( now + API_INVITE_EXPIRY ))
    local created_at
    created_at=$(_api_now_iso)
    local invites
    invites=$(_api_read_auth_file "invites.json")

    if command -v jq >/dev/null 2>&1; then
        local new_invites
        new_invites=$(echo "$invites" | jq \
            --arg c "$code" \
            --arg r "$role" \
            --arg b "$created_by" \
            --arg ca "$created_at" \
            --argjson e "$expires_at" \
            '. + [{"code": $c, "role": $r, "created_by": $b, "created_at": $ca, "expires_at": $e, "used": false, "used_by": ""}]' 2>/dev/null)
        _api_write_auth_file "invites.json" "$new_invites"
    else
        local entry="{\"code\": \"$code\", \"role\": \"$role\", \"created_by\": \"$created_by\", \"created_at\": \"$created_at\", \"expires_at\": $expires_at, \"used\": false, \"used_by\": \"\"}"
        if [[ "$invites" == "[]" ]]; then
            _api_write_auth_file "invites.json" "[$entry]"
        else
            local trimmed="${invites%]}"
            _api_write_auth_file "invites.json" "${trimmed}, $entry]"
        fi
    fi
}

# Validate an invite code — returns role on success, empty on failure
_api_validate_invite() {
    local code="$1"
    local invites
    invites=$(_api_read_auth_file "invites.json")
    local now
    now=$(date +%s)

    local record
    record=$(echo "$invites" | jq -r --arg c "$code" --argjson n "$now" \
        '.[] | select(.code == $c and .expires_at > $n and (.used != true))' 2>/dev/null)
    if [[ -n "$record" ]]; then
        echo "$record" | jq -r '.role' 2>/dev/null
        return 0
    fi
    return 1
}

# Consume an invite code after use — marks as used instead of deleting
_api_consume_invite() {
    local code="$1" username="${2:-unknown}"
    local invites
    invites=$(_api_read_auth_file "invites.json")

    local new_invites
    new_invites=$(echo "$invites" | jq --arg c "$code" --arg u "$username" \
        '[.[] | if .code == $c then . + {"used": true, "used_by": $u} else . end]' 2>/dev/null)
    _api_write_auth_file "invites.json" "$new_invites"
}

# Delete a specific invite code by value
_api_delete_invite() {
    local code="$1"
    local invites
    invites=$(_api_read_auth_file "invites.json")

    if command -v jq >/dev/null 2>&1; then
        local exists
        exists=$(echo "$invites" | jq -r --arg c "$code" '[.[] | select(.code == $c)] | length' 2>/dev/null)
        if [[ "$exists" -eq 0 ]]; then
            return 1
        fi
        local new_invites
        new_invites=$(echo "$invites" | jq --arg c "$code" '[.[] | select(.code != $c)]' 2>/dev/null)
        _api_write_auth_file "invites.json" "$new_invites"
        return 0
    fi
    return 1
}

# Revoke all tokens for a user
_api_revoke_user_tokens() { _api_with_auth_lock tokens _api_revoke_user_tokens_locked "$1"; }
_api_revoke_user_tokens_locked() {
    local username="$1"
    local tokens
    tokens=$(_api_read_auth_file "tokens.json")

    if command -v jq >/dev/null 2>&1; then
        local new_tokens
        new_tokens=$(echo "$tokens" | jq --arg u "$username" '[.[] | select(.username != $u)]' 2>/dev/null)
        _api_write_auth_file "tokens.json" "$new_tokens"
    fi
}

# =============================================================================
# DATA COLLECTION HELPERS
# =============================================================================

# _container_running NAME — true when a container of that name exists and runs (exactly `docker inspect -f
# '{{.State.Running}}' NAME`; the test suite's stand-in docker answers that call)
_container_running() { [[ "$(docker inspect -f '{{.State.Running}}' "$1" 2>/dev/null)" == true ]]; }
# _container_label NAME LABEL — one label of a container (com.docker.compose.project, .service, .project.working_dir …); empty when
# the container or the label is missing
_container_label() { docker inspect --format "{{index .Config.Labels \"$2\"}}" "$1" 2>/dev/null; }

# Get all stack names
_api_get_stacks() {
    local -a stacks=()
    for dir in "$COMPOSE_DIR"/*/; do
        [[ -f "${dir}docker-compose.yml" ]] && stacks+=("$(basename "$dir")")
    done
    echo "${stacks[@]}"
}

# Get stack status: RUNNING (with count) or STOPPED
_api_stack_status() {
    local stack="$1"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
    local env_file="$COMPOSE_DIR/$stack/.env"

    local -a args=(-f "$compose_file")
    [[ -f "$env_file" ]] && args+=(--env-file "$env_file")

    local count
    count=$($DOCKER_COMPOSE_CMD "${args[@]}" ps -q 2>/dev/null | wc -l)
    if [[ "$count" -gt 0 ]]; then
        echo "running:$count"
    else
        echo "stopped:0"
    fi
}

# _stack_asleep STACK — a stopped stack whose every container is one Sablier stops on purpose: it is asleep, not down. The caller
# may read the on-demand names once for a whole list (a local _SAB_NAMES); alone, the function reads them itself.
_stack_asleep() {
    local stack="$1" id n any=false names
    if [[ -v _SAB_NAMES ]]; then names="$_SAB_NAMES"; else names=$(_sablier_names 2>/dev/null); fi
    [[ -n "$names" ]] || return 1
    local -a args=(-f "$COMPOSE_DIR/$stack/docker-compose.yml")
    [[ -f "$COMPOSE_DIR/$stack/.env" ]] && args+=(--env-file "$COMPOSE_DIR/$stack/.env")
    while IFS= read -r id; do
        [[ -n "$id" ]] || continue
        n=$(timeout 5 docker inspect -f '{{.Name}}' "$id" 2>/dev/null); n="${n#/}"; any=true
        grep -qxF -- "$n" <<< "$names" || return 1
    done < <($DOCKER_COMPOSE_CMD "${args[@]}" ps -a -q 2>/dev/null)
    [[ "$any" == true ]]
}

# Get container details as JSON array entry
_api_container_json() {
    local container_id="$1"

    # Use docker inspect with JSON output + jq for reliable parsing
    if command -v jq >/dev/null 2>&1; then
        local raw
        raw=$(timeout 5 docker inspect "$container_id" 2>/dev/null)
        [[ -z "$raw" ]] && { echo '{"name":"unknown","state":"unknown","health":"none","image":"","image_id":"","created":"","uptime_seconds":0,"ports":"","restart_count":0}'; return; }

        local now_epoch
        now_epoch=$(date +%s)

        printf '%s' "$raw" | jq -c --argjson now "$now_epoch" '
            .[0] | {
                name: (.Name | ltrimstr("/")),
                state: .State.Status,
                health: (if .State.Health then .State.Health.Status else "none" end),
                image: .Config.Image,
                image_id: (.Image | split(":") | .[1][:12] // ""),
                created: .Created,
                uptime_seconds: (if .State.Status == "running" and .State.StartedAt != "0001-01-01T00:00:00Z" then
                    (try ($now - (.State.StartedAt | split(".")[0] + "Z" | fromdateiso8601)) catch 0) else 0 end),
                ports: ([.NetworkSettings.Ports | to_entries[] |
                    select(.value != null) | .value[] |
                    (if .HostIp == "" or .HostIp == "0.0.0.0" then "0.0.0.0" else .HostIp end) +
                    ":" + .HostPort + "->" + (.key // "")] | join(", ")),
                restart_count: (.RestartCount // 0)
            }' 2>/dev/null
        return
    fi

    # Fallback without jq — single inspect call
    local _info name state health image
    _info=$(timeout 3 docker inspect --format='{{.Name}}|{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{else}}none{{end}}|{{.Config.Image}}' "$container_id" 2>/dev/null) || _info="/$container_id|unknown|none|unknown"
    _info="${_info#/}"
    IFS='|' read -r name state health image <<< "$_info"

    printf '{"name":"%s","state":"%s","health":"%s","image":"%s","image_id":"","created":"","uptime_seconds":0,"ports":"","restart_count":0}' \
        "$(_api_json_escape "$name")" "$(_api_json_escape "$state")" "$(_api_json_escape "$health")" "$(_api_json_escape "$image")"
}

# =============================================================================
# ENDPOINT HANDLERS
# =============================================================================

# GET / — API name, version, authentication mode, role (hub or node) and the endpoint list
handle_root() {
    # Endpoint catalogue — generated by .scripts/api-docs.sh (do not edit by hand)
    local endpoints
    read -r -d '' endpoints <<'DCS_ENDPOINTS' || true
[{"method":"GET","path":"/traefik/dynamic","access":"public","description":"Dynamic configuration for a Traefik on another machine (its HTTP provider); needs ?token= or a Bearer token equal to TRAEFIK_FEED_TOKEN"},{"method":"GET","path":"/feed/summary","access":"public","description":"The server at a glance, for a dashboard: version, stacks and containers (running of total, per stack), and the machine's load (processor, memory, disk, the graphics cards, the UPS when it is watched) and the last backup. Needs the dashboard feed's token (?token= or Bearer)"},{"method":"GET","path":"/feed/crowdsec","access":"public","description":"What CrowdSec has been seeing, for a dashboard: detections over time, the countries, the scenarios and the map points (window=24h|7d|30d). Needs the dashboard feed's token (?token= or Bearer)"},{"method":"GET","path":"/ping","access":"public","description":"Liveness probe: no auth, no Docker call, a tiny body. The dashboard's heartbeat uses it, so the latency it shows is the round trip alone."},{"method":"GET","path":"/fleet/bundle","access":"public","description":"The hub's own DCS code as a tar.gz for a VM being bootstrapped (needs ?token= — a valid join code, or the bundle code an update round minted for the member it names); never includes data, accounts, secrets, stacks or logs"},{"method":"GET","path":"/fleet/bootstrap","access":"public","description":"The node installer for any Debian, Ubuntu, Fedora or Arch machine (needs ?token=, a valid join code; &stack= names the one stack the node carries): a shell script that installs Docker and the tools, fetches this hub's code, sets DCS up as a node and joins — run as a user with sudo: curl -fsSL '…' | bash"},{"method":"GET","path":"/","access":"public","description":"API name, version, authentication mode, role (hub or node) and the endpoint list"},{"method":"GET","path":"/auth/verify","access":"public","description":"Verify a token is valid"},{"method":"GET","path":"/setup/status","access":"public","description":"Always available, no auth. Reports whether the server needs setup; a node answers its role and the hub that manages it (null until it joined one)"},{"method":"GET","path":"/setup/defaults","access":"public","description":"Defaults and detected system values for the setup wizard (anonymous until setup is complete, admin afterwards; the saved .env values only to the admin once one exists)"},{"method":"GET","path":"/auth/users","access":"admin","description":"List all users (admin only)"},{"method":"GET","path":"/auth/invites","access":"admin","description":"List active invite codes (admin only)"},{"method":"GET","path":"/auth/sessions","access":"admin","description":"List active sessions (admin only)"},{"method":"GET","path":"/auth/keys","access":"admin","description":"The API keys (name, role, when made, when last used, expiry); the key itself is never shown again (admin, not with a key)"},{"method":"GET","path":"/status","access":"user","description":"Host and Docker overview: containers, images, stacks, load, memory, disk, the graphics cards (NVIDIA, AMD, Intel); server_name is SERVER_NAME from .env (empty when unset)"},{"method":"GET","path":"/health","access":"user","description":"# GET /health?fleet=1 on a hub: the members' containers ride along (member, member_name, vmid on each row), the summary and the status cover the fleet, members[] says how each DCS is doing"},{"method":"GET","path":"/stacks","access":"user","description":"All stacks with running-container counts"},{"method":"GET","path":"/images","access":"user","description":"# GET /images?fleet=1 on a hub: every member's images in the same list, each tagged member, member_name, vmid; members[] counts per DCS"},{"method":"GET","path":"/images/stale","access":"user","description":"Images with age, size and staleness (/images/stale lists only stale ones) On a hub, ?fleet=1 adds every member's images (member, member_name, vmid) and per-member counts"},{"method":"GET","path":"/containers","access":"user","description":"All containers with state, health, ports and cached CPU/memory usage"},{"method":"GET","path":"/config","access":"user","description":"Effective configuration (secrets masked)"},{"method":"GET","path":"/system","access":"user","description":"Host resources: CPU, memory, uptime, kernel"},{"method":"GET","path":"/disks","access":"user","description":"Mounted filesystems and their usage"},{"method":"GET","path":"/storage/overview","access":"user","description":"Storage overview"},{"method":"GET","path":"/domains","access":"user","description":"This server's domains: the primary one (the hub's stacks), the others, the default domain for new VMs, which VMs use which, and whether each has its certificate and sign-in"},{"method":"GET","path":"/authelia/second-step","access":"user","description":"The second step at sign-in to the apps behind Authelia: the setting (off, all, or apps and which), what Authelia's configuration says now, the apps that can ask for it, the sign-in address, and how a device is registered"},{"method":"GET","path":"/authelia/verification-code","access":"admin","description":"The one-time code Authelia last sent to confirm who is registering a device (its file notifier writes it on this server, not in an e-mail): the code, when it was sent and the subject (admin)"},{"method":"GET","path":"/networks","access":"user","description":"Fleet merged"},{"method":"GET","path":"/volumes","access":"user","description":"Fleet merged"},{"method":"GET","path":"/logs","access":"user","description":"Tail of the framework log"},{"method":"GET","path":"/logs/stats","access":"user","description":"Log file size and per-level counts"},{"method":"GET","path":"/logs/archives","access":"user","description":"Rotated log archives"},{"method":"GET","path":"/events","access":"user","description":"Fleet merged"},{"method":"GET","path":"/version","access":"user","description":"API, framework, Docker and Compose versions"},{"method":"GET","path":"/summary","access":"user","description":"The server at a glance for whoever is signed in or holds an API key: the same answer as /feed/summary (version, stacks, containers, the machine's load and disk)"},{"method":"GET","path":"/maintenance/report","access":"user","description":"Docker disk usage report; ?fleet=1 on a hub adds the VMs' numbers up (totals) with members[] per DCS"},{"method":"GET","path":"/maintenance/orphans","access":"user","description":"Containers, volumes and networks no stack references; ?fleet=1 on a hub lists every VM's too, each row tagged member, member_name, vmid"},{"method":"GET","path":"/maintenance/disk","access":"user","description":"Per-stack App-Data sizes, Docker disk usage and volume sizes; ?fleet=1 on a hub merges every VM's (stacks tagged, docker's table added up per type)"},{"method":"GET","path":"/env","access":"admin","description":"The root .env file, raw and parsed"},{"method":"GET","path":"/backups","access":"admin","description":"Fleet merged"},{"method":"GET","path":"/backups/status","access":"admin","description":"Progress of the running backup or restore, or the last result (with what was missing, if anything)"},{"method":"GET","path":"/backups/config","access":"admin","description":"Backup source, destination and retention; upload: the largest archive an upload may be (API_MAX_BACKUP_UPLOAD_SIZE) and the room free in the destination"},{"method":"GET","path":"/backups/{file}/download","access":"admin","description":"Download a backup archive, streamed from disk (its SHA-256 in the X-Checksum-SHA256 header); a one-time ?ticket= from POST /backups/download-link stands in for the session"},{"method":"GET","path":"/backups/{file}/checksum","access":"admin","description":"Size and SHA-256 of a backup archive (from its .sha256), to check a download against"},{"method":"GET","path":"/terminal/history","access":"admin","description":"Recent terminal commands from the audit log"},{"method":"GET","path":"/terminal/web","access":"admin","description":"The web terminal (a real terminal on this server in a browser tab, behind Authelia): whether it is deployed and running, its address, whether its route is protected, what it needs, and its look (admin)"},{"method":"GET","path":"/system/metrics","access":"user","description":"CPU load, memory and per-mount disk usage"},{"method":"GET","path":"/system/update/check","access":"admin","description":"Newer DCS release on the channel? Version, release notes, local edits and how the API can restart"},{"method":"GET","path":"/system/docker-engine","access":"user","description":"Docker engine fleet"},{"method":"GET","path":"/system/docker-engine/status","access":"user","description":"The engine update in progress or the last one (idle, running, done, failed)"},{"method":"GET","path":"/system/update/history","access":"admin","description":"Outcomes of unattended self-updates (last 30) and whether a job runs now"},{"method":"GET","path":"/power","access":"user","description":"UPS status: mains or battery, charge, runtime, load, and whether the watch loop runs"},{"method":"GET","path":"/recovery","access":"admin","description":"Recovery bundles on this box and how they are made (destination, off-box copy, retention, passphrase set?), the result of the last bundle restore, and upload: the largest bundle an upload may be and the room free"},{"method":"GET","path":"/system/os-update/status","access":"admin","description":"Poll background OS update progress"},{"method":"GET","path":"/system/os-updates","access":"user","description":"Waiting OS updates (how many, how many are security fixes), whether a restart is needed to finish updates, and whether the system installs updates on its own (dnf-automatic, unattended-upgrades); unprivileged, looked at in the background at most every 6 h (sooner after packages changed or a restart) and answered from the last look. ?refresh=1 (admin) looks again now unless the last look is under five minutes old; ?fleet=1 on a hub adds every member's (members[], the hub first)"},{"method":"GET","path":"/ddns/status","access":"admin","description":"Check DDNS status and current IP"},{"method":"GET","path":"/alerts/config","access":"admin","description":"Read alert thresholds"},{"method":"GET","path":"/system/crontab","access":"admin","description":"User crontab entries"},{"method":"GET","path":"/system/crontab/system","access":"admin","description":"System-level cron entries"},{"method":"GET","path":"/metrics/trends","access":"user","description":"Metrics samples for a range (range=1h|6h|24h|7d|30d|90d|1y|all), downsampled, with min/max for rolled-up points"},{"method":"GET","path":"/images/check-updates","access":"user","description":"Images check updates get"},{"method":"GET","path":"/fleet/images","access":"user","description":"Every image on the hub and on each member in one list, each tagged with where it runs (member null = the hub); the counts add up across the fleet, registry_checked_at is the oldest check, last_update_at the newest pull"},{"method":"GET","path":"/notifications/rules","access":"user","description":"NTFY notification rules"},{"method":"GET","path":"/notifications/history","access":"user","description":"Recently sent notifications"},{"method":"GET","path":"/snapshots","access":"admin","description":"Fleet merged"},{"method":"GET","path":"/templates","access":"user","description":"List every template in the catalogue (one jq run for all of them, cached 60 s; any template write clears it)"},{"method":"GET","path":"/templates/deploy-history","access":"admin","description":"Template deploy and undeploy events"},{"method":"GET","path":"/automations","access":"user","description":"Fleet merged"},{"method":"GET","path":"/crowdsec/status","access":"user","description":"Which state CrowdSec is in (not deployed, stopped, unhealthy, healthy …), what is wrong and the one-click fixes, plus the numbers for the status strip; the ban list is included for the dashboard card"},{"method":"GET","path":"/chat/messages","access":"user","description":"The server's chat room: messages (?since=<id> for newer ones, or a time in epoch seconds for those sent, edited or deleted after it; ?before=<id> for older, ?limit= up to 500, default 100) and the room (who is online, retention, what the caller may do)"},{"method":"GET","path":"/chat/presence","access":"user","description":"Who is in the room now (dashboard open in the last minute), with their role; marks the caller as here"},{"method":"GET","path":"/routes/health","access":"user","description":"Probe every custom route through Traefik (no changes made)"},{"method":"GET","path":"/crowdsec/decisions","access":"user","description":"Active bans, filtered (q, scope, origin, type, country, scenario, simulated, sort, dir, limit, offset), with the facets for the filter chips"},{"method":"GET","path":"/crowdsec/decisions/export","access":"user","description":"The active bans as CSV or JSON (format=csv|json, the list's filters apply): {format, filename, count, content}"},{"method":"GET","path":"/crowdsec/alerts","access":"user","description":"Recent detections (window 1h/6h/24h/7d/30d, q, scenario, country, ip, simulated, limit, offset) with facets; each row says whether its source is banned now"},{"method":"GET","path":"/crowdsec/alerts/{id}","access":"user","description":"One alert with the requests that raised it (path, status, user agent, target …)"},{"method":"GET","path":"/crowdsec/allowlist","access":"user","description":"Everything that is never banned: entries with comment and expiry, which are managed by DCS (the home address, also kept on CrowdSec's allowlist for its AppSec WAF: home.allowlist) and which can be removed; says which mechanism is in use"},{"method":"GET","path":"/crowdsec/bouncers","access":"user","description":"The programs that enforce bans (Traefik's plugin, a firewall …): last pull, type, version, and what DCS registered for Traefik; the connections CrowdSec files under name@ip are folded into their bouncer (connections)"},{"method":"GET","path":"/crowdsec/machines","access":"user","description":"The engines that report to this CrowdSec (this container's own agent, others you enrolled)"},{"method":"GET","path":"/crowdsec/metrics","access":"user","description":"What has been happening: alerts over time, top scenarios, top countries, top sources and networks, the map points, log-reading counters (window=24h|7d|30d)"},{"method":"GET","path":"/crowdsec/hub","access":"user","description":"Installed collections, scenarios and parsers (with which have updates) and a short list of suggestions; ?type=collections|scenarios|parsers&available=1&q= lists what can be installed"},{"method":"GET","path":"/crowdsec/logs","access":"user","description":"The tail of the container's log: lines (10-500), level (all|warn|error), q (text), lapi=1 to include the noisy API request lines"},{"method":"GET","path":"/crowdsec/simulation","access":"user","description":"Which scenarios only alert (simulation mode) and which ban"},{"method":"GET","path":"/crowdsec/community","access":"user","description":"Is the community blocklist (CAPI) pulled, are signals shared, is the machine enrolled in the CrowdSec console, read locally (never a login at the central service): capi.state is ok, paused (the central service throttles the engine after many logins; it recovers by itself), refused (403 for 2 h or more: needs_register, POST /crowdsec/community/register fixes it), unknown or disabled; hint says it in plain words, last_register how the last attempt went"},{"method":"GET","path":"/crowdsec/settings","access":"user","description":"The default ban length CrowdSec uses, repeat-offender escalation and per-scenario lengths; says whether DCS can edit the file safely"},{"method":"GET","path":"/crowdsec/notifications","access":"user","description":"The Discord alert settings in force (webhook masked), what is wired, the placeholders for the message, and the last test/delivery outcome"},{"method":"GET","path":"/crowdsec/plugin","access":"user","description":"The Traefik bouncer plugin's settings (mode, how often it asks, how long it remembers, timeout, the status a banned visitor sees, trusted networks), the defaults and the limits"},{"method":"GET","path":"/crowdsec/cloudflare","access":"user","description":"Push bans to Cloudflare: on or off, the token (set or not, never its value), the zones and the list, the last pull and sync, how many addresses Cloudflare holds (read from Cloudflare at most once a minute), the error in plain words, the rights the token needs"},{"method":"GET","path":"/topology","access":"user","description":"Container and network topology graph (?fleet=1 on a hub: this server's map and every reachable VM's in one answer)"},{"method":"GET","path":"/traefik/status","access":"user","description":"Traefik status"},{"method":"GET","path":"/routes","access":"user","description":"Routes"},{"method":"GET","path":"/routes/certificates","access":"user","description":"Reverse-proxy health: domain, ACME challenge and account, certificates held, a live probe of every route through Traefik, the last Traefik errors, and hints"},{"method":"GET","path":"/routes/check","access":"user","description":"Check if a subdomain is available"},{"method":"GET","path":"/dns/status","access":"user","description":"Cloudflare integration: where the token comes from, whether it is valid, the zone"},{"method":"GET","path":"/proxmox/status","access":"user","description":"The Proxmox link: configured, reachable, version, node and VM counts, and what to fix when it is not"},{"method":"GET","path":"/proxmox/nodes","access":"user","description":"Every Proxmox node with CPU, memory, disk and uptime"},{"method":"GET","path":"/proxmox/vms","access":"user","description":"Every VM and LXC container with status, CPU, memory, disk, uptime and tags"},{"method":"GET","path":"/proxmox/self","access":"user","description":"The Proxmox guest this DCS runs in (found by its SMBIOS id, addresses or name) with the tags it has and the ones it should have: dcs, and hub on the hub of a fleet"},{"method":"GET","path":"/proxmox/tasks","access":"user","description":"Recent Proxmox tasks (starts, stops, backups, migrations): who ran them and how they ended"},{"method":"GET","path":"/proxmox/vms/{vmid}/snapshots","access":"user","description":"A guest's snapshots (name, note, when, with its RAM or not, the one it runs from now) and whether it runs"},{"method":"GET","path":"/proxmox/vms/{node}/{type}/{vmid}","access":"user","description":"One VM or container: live status and its configuration (cores, memory, OS, boot, description)"},{"method":"GET","path":"/traefik/feed/status","access":"admin","description":"The Traefik feed: on or off, token, target host, what it serves and skips, what the members offered and the hub refused or renamed (member_skipped), when it was last pulled, and the provider snippet to paste"},{"method":"GET","path":"/fleet/status","access":"user","description":"What this server is in the fleet: a hub (members, join codes), a member (its hub), or standalone; plus a pending join and how others reach this API"},{"method":"GET","path":"/fleet/members","access":"user","description":"The members this hub manages, with the guest each one runs in and when it last answered"},{"method":"GET","path":"/fleet/overview","access":"user","description":"Every member with its stacks, containers and Docker counts (images, networks, volumes), and the totals, fetched from the members in parallel (10 s cache)"},{"method":"GET","path":"/fleet/services","access":"user","description":"The fleet's services by name (the hub's and every reachable VM's running containers with a published port): where each runs, its LAN address, its route — what a deploy's URL and host variables are pointed at when they were left at their compose-network default"},{"method":"GET","path":"/fleet/discover","access":"admin","description":"Scan the guests for DCS installs: Proxmox gives each running guest's addresses (guest agent / container interfaces) and the API port is probed; found installs come back with the guest already matched (30 s cache; POST forces a new scan and accepts Proxmox values to try before they are saved)"},{"method":"GET","path":"/fleet/join-tokens","access":"admin","description":"The join codes that are still valid (admin), each with node_command: the one line that installs DCS as a node of this hub on any VM and joins it"},{"method":"GET","path":"/fleet/provision/defaults","access":"admin","description":"Suggested values for creating VMs: node and its size, storages, bridge, an address range next to the hub, the cloud image, the admin name, the guests Proxmox already has (a stack cannot get a VM named like one), the stacks that already run on this server (they stay on it) and whether the hub's firewalld keeps the API port closed (admin)"},{"method":"GET","path":"/fleet/provision/move-check","access":"admin","description":"What moving a stack of this server into a VM would take with it: the size of its folders and named volumes, the disk a VM needs for them, its routes, and the folders outside the stack that do not travel (admin)"},{"method":"GET","path":"/ssh/access","access":"admin","description":"What the ssh sheet needs: the VMs (name, address, whether they answer), the hub (address, user, port) and the keys made so far (admin, not with an API key)"},{"method":"GET","path":"/ssh/keys/*/config","access":"admin","description":"The ssh config for a key, as the VMs are now (?via=hub|direct, ?hub_host=address of the hub as you reach it) (admin)"},{"method":"GET","path":"/fleet/jobs","access":"admin","description":"VMs being created (and the ones that finished or failed), newest first"},{"method":"GET","path":"/fleet/templates","access":"admin","description":"The DCS templates the hub baked (VMs cloned from one build in about half a minute)"},{"method":"GET","path":"/fleet/versions","access":"admin","description":"The hub's DCS version next to every member's, asked live; behind = members on another version, plus the last update round and whether one is queued for after the hub's restart"},{"method":"GET","path":"/fleet/jobs/{id}","access":"admin","description":"One VM job with its steps and log"},{"method":"GET","path":"/proxmox/capabilities","access":"admin","description":"What the API token may do on /: the privileges that creating VMs needs, and which are missing (POST with {url, token_id, token_secret, verify_tls} before the link is saved)"},{"method":"GET","path":"/proxmox/storage","access":"admin","description":"The node's storages with content types and free space (import_ready: can hold a cloud image)"},{"method":"GET","path":"/fleet/identity","access":"user","description":"What a hub needs to match this server to a guest: hostname, SMBIOS uuid, addresses, API port, version"},{"method":"GET","path":"/fleet/feed","access":"user","description":"This server's routes in Traefik feed form, for the hub to merge into its own feed (needs no feed token; the routes point at this host's published ports)"},{"method":"GET","path":"/fleet/members/{id}/api/{path}","access":"user","description":"Forward the call (GET, POST, PUT or DELETE) to that member with the hub's account; the caller's own role is checked against the inner path as if it were local (streams and auth are not forwarded)"},{"method":"GET","path":"/fleet/members/{id}/backups/{file}/download","access":"admin","description":"Download a VM's backup archive through the hub, streamed from the VM (a one-time ?ticket= from POST /backups/download-link with that member stands in for the session)"},{"method":"GET","path":"/fleet/members/{id}/terminal","access":"admin","description":"Can the hub open a shell in this VM: its ssh key, the VM's address and a live test {available, member, member_name, vmid, host, user, reason}"},{"method":"GET","path":"/fleet/members/{id}/folders","access":"user","description":"The folders of the Proxmox host a VM of the fleet has (virtiofs): what Proxmox maps, what the VM is given, where the VM mounts it and which containers use it; whether the token may share folders (it needs the role PVEMappingAdmin on /mapping/dir) and the steps under way. ?op=1: the steps alone (for polling)"},{"method":"GET","path":"/fleet/members/{id}","access":"user","description":"One member, with a live check that it answers"},{"method":"GET","path":"/dns/zones","access":"admin","description":"Zones the Cloudflare token can manage"},{"method":"GET","path":"/dns/records","access":"admin","description":"DNS records of the zone (all types) with their DCS route links"},{"method":"GET","path":"/homarr/status","access":"user","description":"Check if Homarr is deployed and has an API key configured"},{"method":"GET","path":"/feed/status","access":"admin","description":"The dashboard feed: on or off, and its two addresses (admin). The token itself is shown once, when it is made"},{"method":"GET","path":"/themes","access":"user","description":"The themes stored on this server (without their CSS) and the one every dashboard follows (active, \"\" = the default look)"},{"method":"GET","path":"/themes/{name}","access":"user","description":"One stored theme, the whole document (palette and CSS)"},{"method":"GET","path":"/metrics/history","access":"user","description":"Metrics samples for a range (range=1h|6h|24h|7d|30d|90d|1y|all); same data as /metrics/trends under \"data\""},{"method":"GET","path":"/metrics/summary","access":"user","description":"Min, max and average CPU, memory and disk over a range (range=1h|6h|24h|7d|30d|90d|1y|all)"},{"method":"GET","path":"/health/score","access":"user","description":"# GET /health/score?fleet=1 on a hub: the members' scores folded in — containers and images add up across the fleet, the score is"},{"method":"GET","path":"/health/score/history","access":"user","description":"Recorded health scores over a range"},{"method":"GET","path":"/settings/dashboard","access":"user","description":"Fetch user's dashboard layout"},{"method":"GET","path":"/settings/profile","access":"user","description":"Fetch user's profile settings"},{"method":"GET","path":"/secrets","access":"admin","description":"Fleet merged"},{"method":"GET","path":"/schedules","access":"user","description":"Fleet merged"},{"method":"GET","path":"/plugins","access":"user","description":"Scan .plugins/ directory, return plugin manifest data"},{"method":"GET","path":"/plugins/cards","access":"user","description":"List all available plugin cards across all enabled plugins"},{"method":"GET","path":"/plugins/catalog","access":"user","description":"Plugins available to install, with their manifest and installed state"},{"method":"GET","path":"/plugins/{plugin}/cards/{card}/source","access":"admin","description":"The card's manifest and raw HTML, for editing"},{"method":"GET","path":"/plugins/{plugin}/cards/{card}","access":"user","description":"Return card HTML content as JSON"},{"method":"GET","path":"/plugins/{plugin}/hooks/{hook}","access":"admin","description":"Read hook script content"},{"method":"GET","path":"/plugins/{plugin}/hooks","access":"admin","description":"List all hooks with metadata"},{"method":"GET","path":"/plugins/{plugin}/logs","access":"admin","description":"Execution history"},{"method":"GET","path":"/config/schema","access":"user","description":"Return contents of .config/schema.json"},{"method":"GET","path":"/stream","access":"user","description":"SSE endpoint: docker events + periodic metrics, and for a signed-in person the chat room's events (event \"chat\": message, edit, delete, clear, typing, state) while chat is on (on a hub ?fleet=1 adds every VM's docker events, ?member=id one VM's instead; each carries member, member_name, vmid)"},{"method":"GET","path":"/rollback/{stack}/snapshots/{snapshot}","access":"user","description":"Content of a rollback snapshot"},{"method":"GET","path":"/rollback/{stack}/snapshots","access":"user","description":"Rollback snapshots of a stack"},{"method":"GET","path":"/rollback/{stack}/diff/{snapshot}","access":"user","description":"Diff between a snapshot and the current stack files"},{"method":"GET","path":"/secrets/{key}/exists","access":"admin","description":"Check if a secret exists (boolean)"},{"method":"GET","path":"/secrets/{key}/references","access":"admin","description":"Stacks and env files that reference a secret"},{"method":"GET","path":"/health/score/{stack}","access":"user","description":"Compute health score for a specific stack"},{"method":"GET","path":"/schedules/{id}/history","access":"user","description":"Return execution history filtered by schedule id"},{"method":"GET","path":"/templates/gallery","access":"user","description":"List templates from gallery catalog"},{"method":"GET","path":"/templates/{template}","access":"user","description":"Template metadata, compose file and .env"},{"method":"GET","path":"/images/search","access":"user","description":"Search Docker Hub for images"},{"method":"GET","path":"/export/{health|system|config}","access":"user","description":"Export data"},{"method":"GET","path":"/audit","access":"admin","description":"Fleet merged"},{"method":"GET","path":"/webhooks","access":"user","description":"List webhooks"},{"method":"GET","path":"/recovery/*/download","access":"admin","description":"Download a recovery bundle"},{"method":"GET","path":"/snapshots/{snapshot}/download","access":"admin","description":"Download a snapshot archive"},{"method":"GET","path":"/stacks/{stack}/compose/history/{version}","access":"user","description":"View a specific compose version's content"},{"method":"GET","path":"/stacks/{stack}/compose/history","access":"user","description":"Saved versions of a stack's compose file"},{"method":"GET","path":"/automations/{id}/history","access":"user","description":"Run history of an automation"},{"method":"GET","path":"/containers/{container}/files","access":"admin","description":"List directory contents inside a container"},{"method":"GET","path":"/containers/{container}/files/content","access":"admin","description":"Read file contents inside a container"},{"method":"GET","path":"/containers/{container}/logs/live","access":"user","description":"Fetch recent logs for polling"},{"method":"GET","path":"/logs/live","access":"user","description":"Stream DCS application log"},{"method":"GET","path":"/stacks/{stack}/activity","access":"user","description":"Progress of the action running (or last run) on a stack: phase, per-service state, compose output"},{"method":"GET","path":"/stacks/{stack}/services","access":"user","description":"Services of a stack with container state, health and image"},{"method":"GET","path":"/stacks/{stack}/containers","access":"user","description":"Containers of one stack"},{"method":"GET","path":"/stacks/{stack}/logs","access":"user","description":"Recent log lines of a stack"},{"method":"GET","path":"/stacks/{stack}/files","access":"admin","description":"The files of a stack's folder (compose, .env, configuration; no data, logs, caches, certificates or edit backups), each base64: what a hub keeps of a VM's stack"},{"method":"GET","path":"/stacks/{stack}/appdata","access":"user","description":"Where a stack's App-Data is. A stack this server runs: its folder {placement: \"local\", path, exists}. A VM's stack on a hub: Stacks/<name>/VM-App-Data on the hub is a live view of the VM's App-Data (sshfs over the hub's ssh key), with whether it is mounted and why not {placement: \"vm\", state: mounted|waiting|unavailable|held|off, mounted, link, path, remote, access, reason, member, member_name}"},{"method":"GET","path":"/stacks/{stack}/compose","access":"user","description":"The stack's docker-compose.yml"},{"method":"GET","path":"/stacks/{stack}/env","access":"admin","description":"The stack's .env file"},{"method":"GET","path":"/stacks/{stack}","access":"user","description":"Stack detail: services, containers and images"},{"method":"GET","path":"/containers/{container}/stats","access":"user","description":"Live CPU, memory, network and block I/O of a container"},{"method":"GET","path":"/containers/{container}/logs","access":"user","description":"Recent log lines of a container (tail 1–9999, default 100)"},{"method":"GET","path":"/containers/{container}/sablier","access":"user","description":"The container's on-demand settings: whether Sablier starts it on the first request, the idle time, the waiting page, its name and whether details show (read from the Sablier middleware on its route, wherever a deploy put it), whether Traefik routes it and Sablier is deployed, and group when a hand-written block wakes it with others"},{"method":"GET","path":"/containers/{container}/homarr","access":"user","description":"Is this container on the Homarr dashboard: Homarr here (board with an API key, library without, none), the address DCS would put there (its HTTPS route, else a published port), the name and icon from its template, and the app when added; ?member=id on a hub answers for a VM's container (the address from the VM, Homarr from the hub)"},{"method":"GET","path":"/containers/{container}/theme","access":"user","description":"The theme.park theme on this container's pages: whether theme.park has themes for its app, whether a Traefik route serves it (the theme reaches the app through it), the theme and add-ons on now, and the themes and add-ons to choose from; ?member=id on a hub answers for a VM's container (its route from the VM, the theme applied by the hub's Traefik)"},{"method":"GET","path":"/containers/{container}/processes","access":"user","description":"Process list inside a container"},{"method":"GET","path":"/containers/{container}/reset","access":"admin","description":"Preview a nuke & reinstall: stack, service, image, App-Data folders that would be emptied (with sizes), named volumes, and folders kept because another container shares them"},{"method":"GET","path":"/networks/{network}","access":"user","description":"Network detail with its members"},{"method":"GET","path":"/containers/{container}","access":"user","description":"Container detail"},{"method":"POST","path":"/auth/setup","access":"public","description":"Create the first admin account (only when no users exist)"},{"method":"POST","path":"/auth/login","access":"public","description":"Authenticate and get a session token"},{"method":"POST","path":"/auth/register","access":"public","description":"Register a new account with an invite code"},{"method":"POST","path":"/auth/totp/validate","access":"public","description":"Validate TOTP code during login (second step)"},{"method":"POST","path":"/setup/restore","access":"public","description":"First-run only: restore a recovery bundle sent by the setup wizard {content_b64, passphrase}; once an admin exists, only that admin. App-Data already here is set aside and stacks that run are stopped and started again, as POST /recovery/restore does"},{"method":"POST","path":"/fleet/join","access":"public","description":"A member registers itself with a join code {token, name, url, username, password, identity?, vmid?, node?, type?}: the hub logs in to it, matches it to a guest and keeps it (no session; rate-limited like a login)"},{"method":"POST","path":"/fleet/relay","access":"public","description":"A member's event for the hub {token, event, context}: the hub notes it in its activity (fleet_event) and fires its own notification rules with the VM named; public, the relay token says who; at most 30 events a minute per member (429 beyond)"},{"method":"POST","path":"/setup/configure","access":"user","description":"Apply the setup wizard's settings and stack list"},{"method":"POST","path":"/setup/complete","access":"user","description":"Mark first-run setup as finished"},{"method":"POST","path":"/auth/logout","access":"user","description":"Invalidate the current session token"},{"method":"POST","path":"/auth/refresh","access":"user","description":"Refresh the current session token"},{"method":"POST","path":"/auth/totp/setup","access":"user","description":"Generate TOTP secret and return QR URI (not yet enabled)"},{"method":"POST","path":"/auth/totp/verify","access":"user","description":"Verify a TOTP code and enable 2FA"},{"method":"POST","path":"/auth/totp/disable","access":"user","description":"Disable 2FA (requires password confirmation)"},{"method":"POST","path":"/auth/invite","access":"admin","description":"Generate an invite code (admin only)"},{"method":"POST","path":"/auth/users","access":"admin","description":"Create a user account directly {username, password, role} (admin; for bots and family)"},{"method":"POST","path":"/auth/keys","access":"admin","description":"Make an API key for a dashboard or a script {name, role: read|operate, expires_days?: 0 = never}: the key is in the answer once, DCS keeps its hash (admin, not with a key)"},{"method":"POST","path":"/ssh/keys","access":"admin","description":"Make a key of your own and put its public half on the VMs you tick {name, members: [member ids], hub_access?, password}: the private half is in the answer once, and only after your dashboard password was typed again (admin, not with an API key)"},{"method":"POST","path":"/ssh/keys/*/vms","access":"admin","description":"Put an existing key on more VMs {members: [ids]}: the private half is not needed, the hub holds the public one (admin)"},{"method":"POST","path":"/auth/users/*/role","access":"admin","description":"Change an account's role {role: admin|user|bot} (admin; the last admin cannot be demoted; the account's sessions are signed out)"},{"method":"POST","path":"/proxmox/test","access":"admin","description":"Try a Proxmox connection with the given url, token_id, token_secret and verify_tls without saving them"},{"method":"POST","path":"/proxmox/vms/{vmid}/snapshots","access":"admin","description":"Take a snapshot of a guest: {name, description?, vmstate?} (vmstate: a running VM's RAM too); waits for Proxmox and answers what it made. The API token needs VM.Snapshot"},{"method":"POST","path":"/proxmox/vms/{vmid}/snapshots/{name}/rollback","access":"admin","description":"Return a guest to a snapshot ({confirm: true}; start?: false leaves a VM that was running stopped). Everything since is lost; a fleet member's DCS goes back too and the hub checks it again. Refused for the VM this DCS runs in. The API token needs VM.Snapshot.Rollback"},{"method":"POST","path":"/proxmox/vms/{node}/{type}/{vmid}/{action}","access":"admin","description":"Power action on a VM or container: start, shutdown, stop, reboot, reset (VMs only), balloon (VMs only: a memory balloon whose floor keeps the guest three quarters of its memory, so Proxmox reports the guest's real usage and can take a little back; reboot afterwards), suspend, resume — audited and sent to the webhooks"},{"method":"POST","path":"/traefik/feed/token","access":"admin","description":"Mint a new feed token (paste the new one into the remote Traefik)"},{"method":"POST","path":"/fleet/members","access":"admin","description":"Add a member by address and an account on it {url, username, password, name?, vmid?, node?, type?, insecure?}; the hub logs in, learns who it is and matches it to a guest"},{"method":"POST","path":"/fleet/join-tokens","access":"admin","description":"Mint a join code {ttl_hours?: 24}: node_command is the one line that installs DCS as a node of this hub on any Debian, Ubuntu, Fedora or Arch VM and joins it; a VM that already runs DCS joins with ./setup.sh --join (or ./setup.sh with DCS_HUB_URL and DCS_JOIN_TOKEN)"},{"method":"POST","path":"/fleet/join-hub","access":"admin","description":"Make this server a member of a hub {hub_url, token, name?, url?} or {pending: true} for the join setup.sh saved: creates the account dcs-hub here and registers with the hub"},{"method":"POST","path":"/fleet/discover","access":"admin","description":"Scan the guests for DCS installs: Proxmox gives each running guest's addresses (guest agent / container interfaces) and the API port is probed; found installs come back with the guest already matched (30 s cache; POST forces a new scan and accepts Proxmox values to try before they are saved)"},{"method":"POST","path":"/fleet/provision","access":"admin","description":"Build one VM per stack (the whole request is checked before anything is queued — a refused stack leaves nothing behind): {node, storage, image_storage, bridge, cidr, gateway, dns, ip_start, image|image_url|image_file|iso, vms: [{stack, source, cores, memory_mb, disk_gb, ip, image|image_url|image_file|iso}]}; a cloud image builds unattended, an ISO is installed by hand and joined; the hub's Stacks/<source> moves into the VM"},{"method":"POST","path":"/fleet/provision/defaults","access":"admin","description":"Suggested values for creating VMs: node and its size, storages, bridge, an address range next to the hub, the cloud image, the admin name, the guests Proxmox already has (a stack cannot get a VM named like one), the stacks that already run on this server (they stay on it) and whether the hub's firewalld keeps the API port closed (admin)"},{"method":"POST","path":"/proxmox/capabilities","access":"admin","description":"What the API token may do on /: the privileges that creating VMs needs, and which are missing (POST with {url, token_id, token_secret, verify_tls} before the link is saved)"},{"method":"POST","path":"/proxmox/storage","access":"admin","description":"The node's storages with content types and free space (import_ready: can hold a cloud image)"},{"method":"POST","path":"/proxmox/self/tag","access":"admin","description":"Give the VM this DCS runs in its Proxmox tags (dcs, and hub on the hub); tags it already has stay. The API token needs VM.Config.Options on that VM"},{"method":"POST","path":"/fleet/templates","access":"admin","description":"Bake a DCS template from a cloud image {node, storage, image_storage, bridge, cidr, gateway, dns, ip_start, image|image_url|image_file, cores?, memory_mb?, disk_gb?}: a build job of kind \"bake\""},{"method":"POST","path":"/fleet/update","access":"admin","description":"Bring members to this hub's DCS version {members: [\"id\", …] or \"all\"}: each fetches the hub's code bundle, keeps its own files and re-executes; the round runs on its own — the answer lists what happened per member when it finished within 25 s, otherwise it is 202 {running: true} and GET /fleet/versions (last_round) follows it"},{"method":"POST","path":"/fleet/self-update","access":"admin","description":"Fleet self update"},{"method":"POST","path":"/fleet/hub/relay-token","access":"admin","description":"The hub hands this member the token its events travel with {token} (admin: the hub's own account)"},{"method":"POST","path":"/fleet/routes","access":"admin","description":"The hub hands this DCS the other servers' routes for the Traefik that runs here {http: {routers, services}}; written as custom_routes/fleet-members.yml (admin: the hub's own account); 409 without a Traefik here"},{"method":"POST","path":"/fleet/hub/domain","access":"admin","description":"The hub hands this member the fleet's proxy domain {domain, force}: written as PROXY_DOMAIN when this DCS has none yet (or the example.com placeholder), so the routes it writes for its stacks carry the fleet's domain; a domain of its own (a Traefik here) is kept unless force is true"},{"method":"POST","path":"/domains","access":"admin","description":"Add a domain {domain}: one Cloudflare token covers it; it gets its wildcard certificate, its sign-in (auth.<domain>) and its apex record (admin)"},{"method":"POST","path":"/authelia/second-step","access":"admin","description":"Set the second step at sign-in {mode: off|all|apps, apps: [\"dash\",\"traefik\"]}: kept in .env and written into Authelia's access rules (only the rules DCS manages; a copy of the file is kept), then Authelia restarts to read it. off brings back a password alone (admin)"},{"method":"POST","path":"/authelia/second-step/repair","access":"admin","description":"Put DCS's registration rule (second-step.<domain>, two_factor, marked \"# dcs-second-step: enrol\") back into Authelia's access rules when an older file lacks it, the setting as it is; a copy of the file is kept and Authelia restarts to read it (admin)"},{"method":"POST","path":"/domains/vm-default","access":"admin","description":"The domain new VMs get {domain} (\"\" = this server's own) (admin)"},{"method":"POST","path":"/fleet/members/{id}/domain","access":"admin","description":"The VM answers under another of the hub's domains {domain} (\"\" = the hub's own): its routes move to it at once (admin)"},{"method":"POST","path":"/traefik/routes/rebuild","access":"admin","description":"Write the missing routes for the services of one stack {stack} or of every stack: services that publish a port and have no route file yet get Host(service.domain) → the container, like a fresh deploy (a domain is needed: TRAEFIK_DOMAIN or PROXY_DOMAIN); routes written before Authelia arrived go behind it (answer: routes_written, authelia_protected)"},{"method":"POST","path":"/fleet/docker-engine/update","access":"admin","description":"Bring the Docker Engine up to date on members {members: [\"id\", …] or \"all\"} (each VM the hub built has passwordless sudo, so no password travels); the answer says what each member started"},{"method":"POST","path":"/fleet/jobs/{id}/retry","access":"admin","description":"Run a failed VM job again from the step that failed"},{"method":"POST","path":"/fleet/members/{id}/relink","access":"admin","description":"Take a VM back after its password was lost (a deleted FLEET_MEMBER_*_PASSWORD secret, a changed dcs-hub account): the hub lifts its own lock-out on the VM, joins the VM again over ssh with a fresh join code, and keeps the new password; the VM's stacks, placement and settings stay as they were {} (admin session; answers manual_command when the hub's ssh key does not open the VM)"},{"method":"POST","path":"/fleet/members/{id}/test","access":"admin","description":"Log in to the member afresh, read its identity and version, and say which guest it matches"},{"method":"POST","path":"/fleet/members/{id}/sync","access":"admin","description":"Pull the files of every stack a VM runs into the hub's Stacks/ folders; {direction: \"push\"} sends the hub's copies into the VM instead; {stacks: [names]} limits it. The answer lists what moved and what failed"},{"method":"POST","path":"/fleet/members/{id}/terminal/exec","access":"admin","description":"Run a shell command inside a VM over the hub's ssh key {terminal_token, command, cwd?}: the hub's own Terminal session unlocks it; the same command guard, rate limit, 60 s limit and audit log as the host terminal"},{"method":"POST","path":"/fleet/members/{id}/api/{path}","access":"admin","description":"Forward the call (GET, POST, PUT or DELETE) to that member with the hub's account; the caller's own role is checked against the inner path as if it were local (streams and auth are not forwarded)"},{"method":"POST","path":"/fleet/members/{id}/backups/upload","access":"admin","description":"Upload a backup archive into a VM's BACKUP_DEST_DIR through the hub (the body and ?filename= as POST /backups/upload takes them): streamed on to the VM as it arrives, nothing of it kept on the hub; the VM's limit and free room are asked first, and the VM checks it as it checks its own uploads"},{"method":"POST","path":"/fleet/members/{id}/folders","access":"admin","description":"Share a folder of the Proxmox host with a VM {name, path?, mount?, readonly?, restart?}: the mapping on Proxmox (made from path when name is new), the virtiofs device on the VM, a restart of the VM when it runs (restart: false leaves that to you), the mount in the VM (default /mnt/<name>) and a restart of the stacks that already name the folder. Answers at once (202); GET …/folders?op=1 follows the steps"},{"method":"POST","path":"/fleet/members/{id}/folders/*/mount","access":"admin","description":"Mount a folder the VM was given, in the VM, now {mount?, readonly?}: the line in its /etc/fstab and the mount (after a VM that was off is started, or to change read-only); the stacks that name the folder are restarted"},{"method":"POST","path":"/fleet/members/{id}/folders/*/use","access":"admin","description":"Mount a folder the VM was given, in the VM, now {mount?, readonly?}: the line in its /etc/fstab and the mount (after a VM that was off is started, or to change read-only); the stacks that name the folder are restarted"},{"method":"POST","path":"/auth/password","access":"admin","description":"Change your own password {current_password, new_password}: the current one must match, the new one needs 8 characters, and every session of the account ends (sign in again with the new password)"},{"method":"POST","path":"/auth/revoke","access":"admin","description":"Revoke a user's access (admin only)"},{"method":"POST","path":"/auth/logout-all","access":"admin","description":"Auth logout all"},{"method":"POST","path":"/auth/factory-reset","access":"admin","description":"Wipe auth state and return server to first-run mode"},{"method":"POST","path":"/stacks/rename","access":"admin","description":"Rename a stack directory"},{"method":"POST","path":"/stacks/reorder","access":"admin","description":"Set stack startup order"},{"method":"POST","path":"/terminal/exec","access":"admin","description":"Run a shell command on the host (terminal session required, 60 s limit)"},{"method":"POST","path":"/terminal/auth","access":"admin","description":"Authenticate with Linux credentials"},{"method":"POST","path":"/terminal/auth/verify","access":"admin","description":"Verify a terminal session token"},{"method":"POST","path":"/terminal/auth/logout","access":"admin","description":"Invalidate a terminal session"},{"method":"POST","path":"/terminal/web/theme","access":"admin","description":"The web terminal's look: {theme: {background, foreground, cursor, selectionBackground, black … brightWhite} (colours as #hex), font_size: 10-28}; the terminal restarts with it, open tabs reconnect (admin)"},{"method":"POST","path":"/terminal/web/embed","access":"admin","description":"Let other pages show the web terminal in a frame (a card on a Homarr board): {origins: [\"https://dash.example.com\"]}, at most 4; an empty list takes the permission away. Authelia stays in front of it (admin)"},{"method":"POST","path":"/alerts/config","access":"admin","description":"Update alert thresholds"},{"method":"POST","path":"/system/crontab","access":"admin","description":"Update user crontab"},{"method":"POST","path":"/system/restart","access":"admin","description":"Restart the API listener without root: it re-executes itself (older listeners under systemd are relaunched by the unit)"},{"method":"POST","path":"/power/sample","access":"admin","description":"Read the UPS right now (also refreshes what GET /power shows)"},{"method":"POST","path":"/sablier/repair","access":"admin","description":"Recreate on-demand containers that a prune removed (created, not started, so Sablier can wake them)"},{"method":"POST","path":"/homarr/key","access":"admin","description":"Store Homarr's API key {key} after checking it against the Homarr running here (its /api/boards must answer); the secret HOMARR_API_KEY then puts every registered app on the home board as a tile"},{"method":"POST","path":"/feed/token","access":"admin","description":"Switch the dashboard feed on: makes a new token (the one before stops working) and answers it once (admin)"},{"method":"POST","path":"/homarr/sync","access":"admin","description":"Register every routed service Homarr does not have yet (the hub's own routes and the VMs' in fleet-members.yml): an app plus a tile with the key stored, a library entry without; answers how many were queued"},{"method":"POST","path":"/themes","access":"admin","description":"Store a theme: the document itself {schema: 1, name, title, mode, palette: {accent, accentSecondary, bg, surface, surfaceRaised, border, text, textMuted, success, warning, danger, info}, font, radius, css}; replaces a theme of the same name; CSS that loads or runs something is cut out and reported (stripped)"},{"method":"POST","path":"/chat/messages","access":"user","description":"Send a message to the server's room ({\"text\": \"…\"}, 1-2000 characters of plain text; admins and users, CHAT_RATE_LIMIT a minute)"},{"method":"POST","path":"/chat/typing","access":"user","description":"Tell the room the caller is typing (one live event per 3 s at most; nothing is stored)"},{"method":"POST","path":"/themes/import","access":"admin","description":"Fetch a theme document from an https address {url, replace} (256 KB at most) and store it; 409 when the name is taken and replace is not true"},{"method":"POST","path":"/homarr/register","access":"admin","description":"Put an app on the Homarr dashboard now {name, url, icon, description}"},{"method":"POST","path":"/recovery/bundle","access":"admin","description":"Write an encrypted recovery bundle now {passphrase?, include_app_data: [stacks], copy_remote}"},{"method":"POST","path":"/recovery/restore","access":"admin","description":"Restore a bundle from this box {file, passphrase, confirm, restart}: the configuration is replaced (a pre-restore snapshot is kept); the stacks whose App-Data it holds are stopped, their App-Data set aside (.data/pre-restore, or <path>.before-restore-<time> on a drive), restored, and started again"},{"method":"POST","path":"/recovery/upload","access":"admin","description":"Store a recovery bundle: the file itself as the body (application/octet-stream, ?filename=&sha256=, at most API_MAX_BACKUP_UPLOAD_SIZE, streamed to disk; 507 when there is no room) or, from an older dashboard, JSON {filename, content_b64} (at most API_MAX_UPLOAD_SIZE). Kept only when it is whole and an encrypted bundle"},{"method":"POST","path":"/system/update/apply","access":"admin","description":"Update to the channel's release {confirm, replace_local, restart}; user files are kept, a backup tag allows rollback"},{"method":"POST","path":"/system/ui-update/apply","access":"admin","description":"Pull latest DCS-UI image and recreate container"},{"method":"POST","path":"/system/update/rollback","access":"admin","description":"Return to a backup tag {backup_tag, restart}; user files are kept, edited framework files backed up"},{"method":"POST","path":"/system/os-update/check","access":"admin","description":"List available OS package updates (a terminal session, or passwordless sudo as on a VM the hub built)"},{"method":"POST","path":"/system/os-update/apply","access":"admin","description":"Apply OS package updates in the background (a terminal session, or passwordless sudo as on a VM the hub built)"},{"method":"POST","path":"/system/docker-engine/update","access":"admin","description":"Bring the Docker Engine to the newest version the package source offers, in the background: unattended where this API has passwordless sudo (a VM the hub built), otherwise with {terminal_token, password} like the OS updates; the daemon restarts and every container comes back on its restart policy; GET /system/docker-engine/status follows it"},{"method":"POST","path":"/stacks","access":"admin","description":"Create an empty stack directory; app_data_dir (a full path on a mounted drive) keeps its App-Data on a drive of its own, app_data_adopt uses files already there"},{"method":"POST","path":"/stacks/{stack}/delete","access":"admin","description":"Delete a stopped stack directory"},{"method":"POST","path":"/config","access":"admin","description":"Update allow-listed .env settings"},{"method":"POST","path":"/containers/{container}/start","access":"admin","description":"Start, stop, restart, recreate (Compose-managed only) or remove a container"},{"method":"POST","path":"/containers/{container}/stop","access":"admin","description":"Start, stop, restart, recreate (Compose-managed only) or remove a container"},{"method":"POST","path":"/containers/{container}/restart","access":"admin","description":"Start, stop, restart, recreate (Compose-managed only) or remove a container"},{"method":"POST","path":"/containers/{container}/recreate","access":"admin","description":"Start, stop, restart, recreate (Compose-managed only) or remove a container"},{"method":"POST","path":"/containers/{container}/remove","access":"admin","description":"Start, stop, restart, recreate (Compose-managed only) or remove a container"},{"method":"POST","path":"/containers/{container}/reset","access":"admin","description":"Nuke & reinstall {confirm: \"<container>\", wipe_app_data: true, wipe_volumes: false, pull: true}: remove the container, move its App-Data folders to App-Data/.trash, drop its own named volumes when asked, pull and create it again from the compose file"},{"method":"POST","path":"/containers/{container}/exec","access":"admin","description":"Run a command inside a container (30 s limit)"},{"method":"POST","path":"/containers/{container}/homarr","access":"admin","description":"Put this container on the Homarr dashboard now: an app with its template's name and icon, plus a tile on the home board when an API key is stored (the app library alone without one); already there answers already: true; ?member=id on a hub adds a VM's container to the hub's Homarr"},{"method":"POST","path":"/containers/{container}/theme","access":"admin","description":"Put a theme.park theme on this container's pages {enabled: true, theme, addons?} (a Traefik middleware on its route under the plugin name this Traefik declares theme.park by; the plugin is declared when missing; a hand-written theme.park middleware on the route gives way) or take it off {enabled: false}; the route is checked through Traefik afterwards and a change Traefik refuses (the route answers 404) is undone; ?member=id on a hub themes a VM's route in the hub's Traefik"},{"method":"POST","path":"/containers/{container}/sablier","access":"admin","description":"Start this container on demand through Sablier (enabled: true) or serve it normally again {enabled, session?, theme?, display_name?, show_details?}: writes the Traefik middleware on its route (a block a template deploy put there is rewritten with the new settings) or removes it"},{"method":"POST","path":"/containers/{container}/env","access":"admin","description":"Change a Compose-managed container's environment in its stack {set{}, unset[], recreate}"},{"method":"POST","path":"/containers/{container}/rename","access":"admin","description":"Rename a container"},{"method":"POST","path":"/networks","access":"admin","description":"Create a Docker network {name, driver, subnet, gateway, ip_range, internal, attachable, ipv6, labels}"},{"method":"POST","path":"/networks/{network}/delete","access":"admin","description":"Remove a Docker network"},{"method":"POST","path":"/networks/{network}/connect","access":"admin","description":"Connect a container to a network"},{"method":"POST","path":"/networks/{network}/disconnect","access":"admin","description":"Disconnect a container from a network"},{"method":"POST","path":"/networks/{network}/recreate","access":"admin","description":"Rebuild a network with new settings and reconnect its containers"},{"method":"POST","path":"/images/delete","access":"admin","description":"Remove an image by reference {image: \"registry/name:tag\" or an id}: a tagged image goes by its name, which Docker takes even when the id carries several tags"},{"method":"POST","path":"/images/{image}/delete","access":"admin","description":"Image delete"},{"method":"POST","path":"/volumes/{volume}/delete","access":"admin","description":"Remove a Docker volume"},{"method":"POST","path":"/maintenance/prune","access":"admin","description":"Maintenance prune"},{"method":"POST","path":"/maintenance/image-prune","access":"admin","description":"Prune unused images"},{"method":"POST","path":"/maintenance/deep-prune","access":"admin","description":"Prune everything unused, volumes included (confirmation required)"},{"method":"POST","path":"/maintenance/log-rotate","access":"admin","description":"Rotate and archive the framework log"},{"method":"POST","path":"/batch/stacks","access":"admin","description":"Start, stop or restart several stacks in dependency order"},{"method":"POST","path":"/batch/update","access":"admin","description":"Pull images for several stacks and recreate what changed"},{"method":"POST","path":"/env","access":"admin","description":"Save the root .env file (validated as plain KEY=value data)"},{"method":"POST","path":"/env/validate","access":"user","description":"Validate .env content without saving it"},{"method":"POST","path":"/backups/trigger","access":"admin","description":"Start a backup in the background: every stack with its App-Data and named volumes and the install's own state, or one stack ({stack}); checked, with a .sha256"},{"method":"POST","path":"/backups/cancel","access":"admin","description":"Kill a running backup (its paused containers are resumed, its partial files removed)"},{"method":"POST","path":"/backups/verify","access":"admin","description":"Check a backup without restoring it: its .sha256, gzip and tar read it to the end, every part its manifest names is in it {filename}"},{"method":"POST","path":"/backups/restore","access":"admin","description":"Restore a backup (confirmation required): the stacks it holds are stopped, set aside in .data/pre-restore, restored with their volumes and owners, and started again; {stack} restores that stack alone"},{"method":"POST","path":"/backups/upload","access":"admin","description":"Store a backup archive sent as the request body (application/octet-stream, at most API_MAX_BACKUP_UPLOAD_SIZE, 20 GiB; streamed to disk, refused with 507 when BACKUP_DEST_DIR has no room for it) in BACKUP_DEST_DIR ?filename=&sha256=: listed only once it reads back whole as a DCS backup (manifest, every part, nothing unsafe to unpack); kept under its own name, or one made from its manifest"},{"method":"POST","path":"/backups/download-link","access":"admin","description":"A one-time link (two minutes) that downloads a backup archive in the browser, with its size and SHA-256 {filename, member}: this server's archive, or on a hub a VM's (it streams through the hub)"},{"method":"POST","path":"/stacks/{stack}/compose/validate","access":"user","description":"Validate compose content for a stack without saving it"},{"method":"POST","path":"/stacks/{stack}/files","access":"admin","description":"Write a stack's files {files: [{path, mode, content (base64)}], prune: false}: the hub pushing the files it owns into this VM's stack folder; on a hub, a VM stack's files are written here and pushed on"},{"method":"POST","path":"/stacks/{stack}/compose","access":"admin","description":"Save the stack's docker-compose.yml (policy-scanned, previous version kept)"},{"method":"POST","path":"/stacks/{stack}/env","access":"admin","description":"Save the stack's .env file"},{"method":"POST","path":"/stacks/{stack}/compose/rollback","access":"admin","description":"Restore a saved compose version"},{"method":"POST","path":"/settings/dashboard","access":"user","description":"Save user's dashboard layout"},{"method":"POST","path":"/settings/profile","access":"user","description":"Save user's profile settings"},{"method":"POST","path":"/metrics/snapshot","access":"admin","description":"Record a metrics sample now"},{"method":"POST","path":"/dns/records","access":"admin","description":"Create a record {type, name, content, ttl, proxied, priority, comment, zone}"},{"method":"POST","path":"/dns/records/sync","access":"admin","description":"Create the proxied CNAME records that DCS routes are missing"},{"method":"POST","path":"/images/check-updates","access":"admin","description":"Images check updates post"},{"method":"POST","path":"/fleet/images/check","access":"admin","description":"Registry check on the hub and on every member at once (each compares digests with its registries, no pulls); the answer counts per DCS"},{"method":"POST","path":"/images/pull","access":"admin","description":"Pull an image by name {image} and leave the containers on its old copy alone (the Images page's Pull button; /images/update recreates them)"},{"method":"POST","path":"/images/update-all","access":"admin","description":"Update every image now: the unattended image update (pull what runs, recreate the containers on the old copy) started in the background; 409 while one runs"},{"method":"POST","path":"/images/update","access":"admin","description":"Pull an image and recreate the Compose services that use it"},{"method":"POST","path":"/images/{image}/update","access":"admin","description":"Pull an image and recreate the Compose services that use it"},{"method":"POST","path":"/notifications/rules","access":"admin","description":"Create or update a notification rule"},{"method":"POST","path":"/notifications/test","access":"admin","description":"Send a test notification to every configured channel (NTFY, Discord)"},{"method":"POST","path":"/snapshots/create","access":"admin","description":"A configuration snapshot (every stack's configuration files, .env files, accounts and rules, templates, encrypted secrets, routes, schedules; no App-Data); ?fleet=1 on a hub takes one here and one on every member at the same moment (each DCS keeps its own, listed together by GET /snapshots?fleet=1), the answer says what each DCS did"},{"method":"POST","path":"/snapshots/{snapshot}/restore","access":"admin","description":"Restore a snapshot (confirmation required, policy-scanned): a snapshot of the current state is taken first; the stacks' files go back (and into the VM of a stack that runs in one), with routes, schedules, templates and settings"},{"method":"POST","path":"/templates/{template}/deploy","access":"admin","description":"Template deploy"},{"method":"POST","path":"/templates/{template}/undeploy","access":"admin","description":"Remove a template's services from a stack with their containers (remove_containers=false keeps them; optionally data, images, routes)"},{"method":"POST","path":"/templates/{template}/dry-run","access":"user","description":"Preview a deployment: conflicts, ports, variables and policy findings"},{"method":"POST","path":"/templates/import","access":"admin","description":"Import a template from compose content"},{"method":"POST","path":"/templates/fetch-url","access":"admin","description":"Fetch compose content from URL without saving"},{"method":"POST","path":"/templates/import-url","access":"admin","description":"Import a template from a URL"},{"method":"POST","path":"/stacks/{stack}/clone","access":"admin","description":"Clone a stack"},{"method":"POST","path":"/compose/validate","access":"admin","description":"Validate a compose file"},{"method":"POST","path":"/webhooks","access":"admin","description":"Create a webhook"},{"method":"POST","path":"/webhooks/{id}/test","access":"admin","description":"Test a webhook"},{"method":"POST","path":"/templates/{template}/update","access":"admin","description":"Update an existing template's compose, metadata, and .env"},{"method":"POST","path":"/routes/reconcile","access":"admin","description":"Probe the routes and restart Traefik once if they are dead"},{"method":"POST","path":"/crowdsec/trust","access":"admin","description":"Add an address to the whitelist (body {ip}; defaults to the home public address and the caller)"},{"method":"POST","path":"/crowdsec/unban-me","access":"user","description":"Unban the caller: its client address and the home public address"},{"method":"POST","path":"/crowdsec/notifications","access":"admin","description":"Send CrowdSec's alerts to Discord: {webhook?, test?}. Turns the alerts on with the message settings in force (the shipped message on a fresh install), stores a webhook you pass, restarts CrowdSec and optionally posts a test message."},{"method":"POST","path":"/crowdsec/notifications/preview","access":"user","description":"Render the message for a sample alert (probe, ssh, exploit, manual, simulated) or a real one (alert_id) with the settings you are editing: {settings?, sample?, alert_id?}"},{"method":"POST","path":"/crowdsec/notifications/test","access":"admin","description":"Post a real sample message to Discord and say what Discord answered: {sample?, settings?, webhook_url?, include_mention?}; a test never pings anyone unless include_mention is true"},{"method":"POST","path":"/crowdsec/notifications/reset","access":"admin","description":"Back to the message CrowdSec ships with (title, text, fields, colours, delivery); the webhook and the on/off switch stay"},{"method":"POST","path":"/crowdsec/notifications/digest","access":"admin","description":"Send the daily summary (the last 24 hours) to Discord now, whatever the hour; answers what Discord said and the numbers"},{"method":"POST","path":"/crowdsec/decisions","access":"admin","description":"Ban an address or a network: {value, duration (90m, 4h, 7d …) or permanent: true, reason}; refuses your own address, this server, the home address, private and far too wide networks"},{"method":"POST","path":"/crowdsec/decisions/delete","access":"admin","description":"Lift several bans at once: {ids: [decision ids], values: [addresses or networks]} (at most 200)"},{"method":"POST","path":"/crowdsec/decisions/import","access":"admin","description":"Ban many addresses at once: {format: auto|csv|json|values, content, duration?, reason?, permanent?}; every entry is checked like a single ban, refused ones are listed"},{"method":"POST","path":"/crowdsec/allowlist","access":"admin","description":"Never ban an address or network: {value, comment?, expires? (30m, 12h, 7d …; CrowdSec 1.6.8+)}; lifts any ban it covers"},{"method":"POST","path":"/crowdsec/bouncers","access":"admin","description":"Register a bouncer and show its API key ONCE: {name}"},{"method":"POST","path":"/crowdsec/bouncers/register-traefik","access":"admin","description":"Register the Traefik bouncer again: a fresh key, the middleware file and the chain entry (the fix for \"bans are not enforced\")"},{"method":"POST","path":"/crowdsec/service","access":"admin","description":"Start, restart or reload CrowdSec: {action: start|restart|reload}"},{"method":"POST","path":"/crowdsec/community/register","access":"admin","description":"Register this engine with CrowdSec's Central API again (a new login, for when CAPI has refused it for hours): keeps a copy of the old login beside it, restarts CrowdSec and answers with the community status. While the central service is only pausing the engine (capi.state paused) it answers 409 paused, unless the body says {\"force\": true}: registering is one more login and extends the pause. Console enrolment belongs to the engine's identity and may need doing again"},{"method":"POST","path":"/crowdsec/community/check","access":"admin","description":"Ask the central service now whether it accepts this engine (cscli capi status: a real login, so at most once per 10 minutes; 429 with retry_after otherwise) and answer with the community status"},{"method":"POST","path":"/crowdsec/console/enroll","access":"admin","description":"Enrol this engine in the CrowdSec console: {key (the enrolment key from app.crowdsec.net), name?, overwrite?, force?}; the key is never logged or echoed. 409 paused while the central service is pausing the engine (unless force: true)"},{"method":"POST","path":"/crowdsec/traefik/restart","access":"admin","description":"Restart Traefik (it loads a plugin declared in its static configuration only when it starts) and wait until it runs again"},{"method":"POST","path":"/crowdsec/hub/update","access":"admin","description":"Fetch the newest hub index (needs internet on the server)"},{"method":"POST","path":"/crowdsec/hub/upgrade","access":"admin","description":"Upgrade every installed collection, scenario and parser, then reload"},{"method":"POST","path":"/crowdsec/hub/install","access":"admin","description":"Install a collection, scenario or parser from the hub: {type: collections|scenarios|parsers, name}; CrowdSec reloads afterwards"},{"method":"POST","path":"/crowdsec/hub/remove","access":"admin","description":"Remove an installed collection, scenario or parser: {type: collections|scenarios|parsers, name}; CrowdSec reloads afterwards"},{"method":"POST","path":"/crowdsec/simulation","access":"admin","description":"{scenario, enabled}: make one scenario alert-only (enabled true) or ban again; {global: true, enabled} switches the whole engine"},{"method":"POST","path":"/crowdsec/cloudflare/verify","access":"admin","description":"Check a Cloudflare token without changing anything: {token?} (else the stored one). Answers the zones it found, the rights that are missing (400) and the free plan's limits it would hit"},{"method":"POST","path":"/crowdsec/cloudflare/enable","access":"admin","description":"Turn Push bans to Cloudflare on: {token? (kept as the secret CLOUDFLARE_BOUNCER_TOKEN), capacity?, community?, domains?}. Checks the token's rights first (400 with what is missing, nothing changed), registers the bouncer dcs-cloudflare-bouncer in CrowdSec, makes the list dcs_crowdsec_bans and the blocking custom rule in each zone, and starts the first push in the background (the answer does not wait for it: first_sync \"running\"; the community blocklist only when the body asks for it)"},{"method":"POST","path":"/crowdsec/cloudflare/disable","access":"admin","description":"Turn Push bans to Cloudflare off: the background sync stops, the bouncer dcs-cloudflare-bouncer is deleted in CrowdSec; {cleanup: true} also deletes the custom rule of each zone and the list at Cloudflare (otherwise they stay, frozen, with the last bans), {forget_token: true} deletes the stored token. Safe to repeat (cleanup after an earlier off)"},{"method":"POST","path":"/crowdsec/cloudflare/sync","access":"admin","description":"Sync with Cloudflare now (pull the bans, push them when they changed, read the list and the rules back and repair them) and answer the status; within a minute of the last sync the list is not read back, and a change waits for Cloudflare's one change a minute (message says so: \"Already synced N s ago\", \"The change goes to Cloudflare in N s\")"},{"method":"POST","path":"/crowdsec/cloudflare/settings","access":"admin","description":"Change how many addresses go to Cloudflare and which: {capacity? (1-500000; the free plan holds 10000), community? (also the community blocklist, within the capacity), domains? (the domains whose zones are protected; [] = all of this server's)}. Nothing is sent from the request: the next sync (within seconds, when it is on) works the items out afresh and sends one change when they differ"},{"method":"POST","path":"/automations","access":"admin","description":"Create an automation rule"},{"method":"POST","path":"/automations/{id}/update","access":"admin","description":"Update an automation rule"},{"method":"POST","path":"/automations/{id}/run","access":"admin","description":"Run an automation now"},{"method":"POST","path":"/stacks/{stack}/push","access":"admin","description":"Push the hub's files of a VM stack (Stacks/<name>/) into the VM that runs it: how a rebuilt VM gets its stack back, and how a change made on the hub by hand reaches the VM"},{"method":"POST","path":"/stacks/{stack}/appdata/mount","access":"admin","description":"Mount a VM stack's App-Data on the hub now (Stacks/<name>/VM-App-Data): installs sshfs on the hub when it is missing and the DCS account has passwordless sudo, and brings back a mount taken down with unmount; 409 with the reason when it cannot be mounted"},{"method":"POST","path":"/stacks/{stack}/appdata/unmount","access":"admin","description":"Take the mount of a VM stack's App-Data down on the hub and keep it down until mount is called (nothing changes in the VM)"},{"method":"POST","path":"/stacks/{stack}/pull","access":"admin","description":"Pull a VM stack's files from the VM into the hub's Stacks/<name>/ (the hub's copy becomes the VM's, file for file; the copy it replaces is kept in the compose history)"},{"method":"POST","path":"/stacks/{stack}/start","access":"admin","description":"Start, stop, restart or update (pull + recreate) a stack"},{"method":"POST","path":"/stacks/{stack}/stop","access":"admin","description":"Start, stop, restart or update (pull + recreate) a stack"},{"method":"POST","path":"/stacks/{stack}/restart","access":"admin","description":"Start, stop, restart or update (pull + recreate) a stack"},{"method":"POST","path":"/stacks/{stack}/update","access":"admin","description":"Start, stop, restart or update (pull + recreate) a stack"},{"method":"POST","path":"/secrets","access":"admin","description":"Store an encrypted secret (also POST /secrets/{key})"},{"method":"POST","path":"/secrets/{key}","access":"admin","description":"Store an encrypted secret (also POST /secrets/{key})"},{"method":"POST","path":"/schedules","access":"admin","description":"Create a scheduled task"},{"method":"POST","path":"/plugins/install","access":"admin","description":"Install a plugin from a git URL (installed disabled)"},{"method":"POST","path":"/plugins/scaffold","access":"admin","description":"Create a plugin from an inline manifest, hooks and cards"},{"method":"POST","path":"/rollback/{stack}/restore","access":"admin","description":"Restore a stack from a rollback snapshot (policy-scanned)"},{"method":"POST","path":"/schedules/{id}/update","access":"admin","description":"Update a scheduled task"},{"method":"POST","path":"/schedules/{id}/toggle","access":"admin","description":"Enable/disable a schedule"},{"method":"POST","path":"/schedules/{id}/run","access":"admin","description":"Execute a schedule immediately"},{"method":"POST","path":"/plugins/catalog/*/install","access":"admin","description":"Install a catalogue plugin (copied into .plugins, disabled)"},{"method":"POST","path":"/plugins/{plugin}/cards/{card}","access":"admin","description":"Create or replace a dashboard card in a plugin {meta{}, html}"},{"method":"POST","path":"/plugins/{plugin}/toggle","access":"admin","description":"Enable/disable by writing to plugin.json"},{"method":"POST","path":"/plugins/{plugin}/hooks/{hook}/test","access":"admin","description":"Dry-run a hook"},{"method":"POST","path":"/plugins/{plugin}/hooks/{hook}/update","access":"admin","description":"Update hook script"},{"method":"POST","path":"/plugins/{plugin}/config","access":"admin","description":"Update plugin configuration"},{"method":"PUT","path":"/themes/active","access":"admin","description":"The theme every dashboard follows {name} (\"\" = the default look); it must be stored here first"},{"method":"PUT","path":"/chat/messages/{id}","access":"user","description":"Edit one's own message ({\"text\": \"…\"}) within 15 minutes of sending it"},{"method":"PUT","path":"/crowdsec/settings","access":"admin","description":"Change the ban profile: {profile: {duration, range_duration, escalate: {enabled, max}, overrides: [{pattern, duration}]}, manual_duration, take_over}; validates with CrowdSec, restarts it and rolls back on failure"},{"method":"PUT","path":"/crowdsec/notifications","access":"admin","description":"Save and apply the Discord alert settings: {settings: {…any part…}, webhook_url?: \"https://discord.com/api/webhooks/…\", clear_custom_webhook?: true}; the URL is stored as a secret and never sent back"},{"method":"PUT","path":"/crowdsec/notifications/digest","access":"admin","description":"When the daily summary goes out: {hour: 0-23} or {hour: \"off\"} (CROWDSEC_DIGEST_HOUR in .env, local time)"},{"method":"PUT","path":"/crowdsec/plugin","access":"admin","description":"Change the plugin's settings: {settings: {mode, update_interval, default_decision_seconds, http_timeout, remediation_status_code, log_level, trust_home, client_trusted_ips, forwarded_headers_trusted_ips}} (any part); written to Traefik's middleware file atomically, the old one is kept, Traefik reloads by itself"},{"method":"PUT","path":"/fleet/members/{id}/api/{path}","access":"admin","description":"Forward the call (GET, POST, PUT or DELETE) to that member with the hub's account; the caller's own role is checked against the inner path as if it were local (streams and auth are not forwarded)"},{"method":"PUT","path":"/fleet/members/{id}","access":"admin","description":"Change a member's name, address, account, the guest it is mapped to, or the stacks it answers for {name?, url?, username?, password?, vmid?, node?, type?, insecure?, stacks?: [\"name\", …]} (a placement makes the hub forward that stack's requests to this member; a stack the hub runs itself cannot be placed)"},{"method":"PUT","path":"/dns/records/*","access":"admin","description":"Change a record's type, name, content, TTL, proxy status, priority or comment"},{"method":"PUT","path":"/routes/{stack}/{service}","access":"admin","description":"Update a route file's subdomain"},{"method":"DELETE","path":"/themes/{name}","access":"admin","description":"Remove a stored theme (dashboards following it go back to the default look)"},{"method":"DELETE","path":"/chat/messages","access":"admin","description":"Clear the room: every message goes (admin, audited)"},{"method":"DELETE","path":"/chat/messages/{id}","access":"user","description":"Delete a message: one's own, or any as an admin (audited, never with the text); it stays as \"deleted\" in the room"},{"method":"DELETE","path":"/homarr/key","access":"admin","description":"Forget Homarr's API key (apps then land in the library only)"},{"method":"DELETE","path":"/feed/token","access":"admin","description":"Switch the dashboard feed off: the token is removed and both addresses answer 401 (admin)"},{"method":"DELETE","path":"/fleet/members/{id}/api/{path}","access":"admin","description":"Forward the call (GET, POST, PUT or DELETE) to that member with the hub's account; the caller's own role is checked against the inner path as if it were local (streams and auth are not forwarded)"},{"method":"DELETE","path":"/fleet/members/{id}/folders/*","access":"admin","description":"Take a shared folder from a VM (?restart=false leaves the VM running: the device goes at its next start; ?mapping=true also removes the mapping from Proxmox): unmounted in the VM and out of its /etc/fstab, the device off the VM. Answers at once (202); nothing is deleted on the host"},{"method":"DELETE","path":"/domains/*","access":"admin","description":"Take a domain off this server: no VM may still use it (admin)"},{"method":"DELETE","path":"/fleet/members/{id}","access":"admin","description":"Forget a member (its dcs-hub account is removed there when it answers)"},{"method":"DELETE","path":"/fleet/templates/{vmid}","access":"admin","description":"Forget a DCS template and destroy the template VM on Proxmox"},{"method":"DELETE","path":"/proxmox/vms/{vmid}/snapshots/{name}","access":"admin","description":"Delete a guest's snapshot (the guest itself stays as it is now). The API token needs VM.Snapshot"},{"method":"DELETE","path":"/fleet/jobs/{id}","access":"admin","description":"Forget a finished or failed job; ?destroy=true also destroys the VM a failed build (or a by-hand install that never joined) left behind"},{"method":"DELETE","path":"/fleet/join-tokens/{token}","access":"admin","description":"Revoke a join code"},{"method":"DELETE","path":"/fleet/hub","access":"admin","description":"Leave the hub: forget it and remove its dcs-hub account here (the hub drops this member when it next fails to answer, or when removed there)"},{"method":"DELETE","path":"/auth/sessions/{token-prefix}","access":"admin","description":"Revoke a specific session by token prefix (admin only)"},{"method":"DELETE","path":"/auth/invite/{code}","access":"admin","description":"Delete an invite code (admin only)"},{"method":"DELETE","path":"/auth/keys/*","access":"admin","description":"Remove an API key: it stops working at once (admin, not with a key)"},{"method":"DELETE","path":"/ssh/keys/*","access":"admin","description":"Take a key away: its line is removed from every VM (and the hub) it was put on (admin)"},{"method":"DELETE","path":"/notifications/rules/{id}","access":"admin","description":"Delete a notification rule"},{"method":"DELETE","path":"/snapshots/{snapshot}","access":"admin","description":"Delete a snapshot"},{"method":"DELETE","path":"/webhooks/{id}","access":"admin","description":"Delete a webhook"},{"method":"DELETE","path":"/templates/{template}","access":"admin","description":"Delete a template"},{"method":"DELETE","path":"/crowdsec/decisions/{value}","access":"admin","description":"Lift the ban on one address or network (the value may be an IP or a CIDR range such as 192.0.2.0/24)"},{"method":"DELETE","path":"/crowdsec/allowlist/{value}","access":"admin","description":"Take an entry off the allowlist (the home address DCS keeps in sync cannot be removed here)"},{"method":"DELETE","path":"/crowdsec/bouncers/{name}","access":"admin","description":"Unregister a bouncer (its API key stops working at once)"},{"method":"DELETE","path":"/crowdsec/trust/{value}","access":"admin","description":"Remove an address from the whitelist"},{"method":"DELETE","path":"/automations/{id}","access":"admin","description":"Delete an automation rule"},{"method":"DELETE","path":"/secrets/{key}","access":"admin","description":"Securely delete a secret"},{"method":"DELETE","path":"/schedules/{id}","access":"admin","description":"Remove a schedule"},{"method":"DELETE","path":"/plugins/{plugin}/cards/{card}","access":"admin","description":"Remove a dashboard card from a plugin"},{"method":"DELETE","path":"/plugins/{plugin}","access":"admin","description":"Remove plugin directory"},{"method":"DELETE","path":"/dns/records/*","access":"admin","description":"Delete a record (the zone apex and names DCS routes use need force=true)"},{"method":"DELETE","path":"/routes/{stack}/{service}","access":"admin","description":"Delete a route file and optionally clean up DNS"}]
DCS_ENDPOINTS

    _api_success "{\"name\": \"DCS Orchestrator API\", \"version\": \"$API_VERSION\", \"auth_enabled\": $API_AUTH_ENABLED, \"role\": \"$DCS_ROLE\", \"endpoints\": $endpoints}"
}

# GET /version — API, framework, Docker and Compose versions
handle_version() {
    local docker_version compose_version
    docker_version=$(_api_json_escape "$(docker --version 2>/dev/null)")
    compose_version=$(_api_json_escape "$($DOCKER_COMPOSE_CMD version 2>/dev/null)")

    _api_success "{\"api_version\": \"$API_VERSION\", \"framework_version\": \"$(_api_json_escape "$DCS_VERSION")\", \"docker_version\": \"$docker_version\", \"compose_version\": \"$compose_version\", \"compose_command\": \"$(_api_json_escape "$DOCKER_COMPOSE_CMD")\"}"
}

# The graphics cards in this machine as a JSON array, the busiest kind first: NVIDIA from nvidia-smi, AMD from the amdgpu
# driver's sysfs files (no ROCm or Mesa needed on the host), Intel by name only (its load needs root). Each card:
# {vendor, name, slot, render, utilization, memory_used_mb, memory_total_mb, temperature, temperature_hotspot, fan_speed,
# fan_rpm, power_w, power_cap_w, asleep}; a reading the card does not give is null. A card the driver has put to sleep
# (runtime power management, common for a card with no screen) is not woken to read it: 0 % busy, no temperature or power. DCS_SYSFS_DRM and DCS_AMDGPU_IDS point the tests at a fake tree.
_gpu_name_lspci() {
    local d; d=$(lspci -vmm -s "$1" 2>/dev/null | awk -F'\t' '$1 == "Device:" {print $2; exit}') || d=""
    [[ "$d" =~ \[([^]]+)\] ]] && d=${BASH_REMATCH[1]}
    printf '%s' "$d"
}
# one sysfs value, or nothing: a card without the file (no fan, no power cap) must not end the caller (errexit, pipefail)
_gpu_rd() { cat "$1" 2>/dev/null || true; }
_gpu_list() {
    local drm=${DCS_SYSFS_DRM:-/sys/class/drm} ids=${DCS_AMDGPU_IDS:-/usr/share/libdrm/amdgpu.ids}
    local -a rows=() nv_slots=()
    local line c dev slot vendor render name
    if command -v nvidia-smi >/dev/null 2>&1; then
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            line=$(jq -Rc 'split(", ") | map(if test("^\\[?N/?A\\]?$") then null else . end)
                | {vendor: "nvidia", name: (.[0] // "NVIDIA GPU"), slot: ((.[1] // "") | ascii_downcase | .[-12:]), render: null,
                   utilization: (.[2] | tonumber? // null), memory_used_mb: (.[3] | tonumber? // null), memory_total_mb: (.[4] | tonumber? // null),
                   temperature: (.[5] | tonumber? // null), temperature_hotspot: null, fan_speed: (.[6] | tonumber? // null), fan_rpm: null,
                   power_w: (.[7] | tonumber? // null | if . == null then null else (. * 10 | round / 10) end),
                   power_cap_w: (.[8] | tonumber? // null | if . == null then null else round end), asleep: false}' <<< "$line" 2>/dev/null) || continue
            [[ "$line" == \{* ]] || continue
            rows+=("$line"); nv_slots+=("$(jq -r '.slot' <<< "$line")")
        done < <(timeout 4 nvidia-smi --query-gpu=name,pci.bus_id,utilization.gpu,memory.used,memory.total,temperature.gpu,fan.speed,power.draw,power.limit --format=csv,noheader,nounits 2>/dev/null)
    fi
    for c in "$drm"/card[0-9]*; do
        [[ -e "$c/device/vendor" && "${c##*/}" != *-* ]] || continue
        dev=$(readlink -f "$c/device" 2>/dev/null) || continue
        slot=${dev##*/}; vendor=$(<"$c/device/vendor") 2>/dev/null || continue
        render=$(cd "$c/device/drm" 2>/dev/null && compgen -G 'renderD*' | head -1) || render=""
        case "$vendor" in
            0x1002)
                local did rev hw="" asleep=false busy="" mu="" mt="" t1="" t2="" fr="" pw="" pm="" pc="" p=""
                did=$(_gpu_rd "$c/device/device" | tr '[:lower:]' '[:upper:]'); did=${did#0X}
                rev=$(_gpu_rd "$c/device/revision" | tr '[:lower:]' '[:upper:]'); rev=${rev#0X}
                name=""
                [[ -r "$ids" && -n "$did" ]] && name=$(awk -F',[ \t]*' -v d="$did" -v r="$rev" 'toupper($1) == d && toupper($2) == r {print $3; exit}' "$ids" 2>/dev/null) || name=""
                [[ -z "$name" && -r "$c/device/product_name" ]] && name=$(<"$c/device/product_name")
                if [[ -z "$name" ]]; then name=$(_gpu_name_lspci "$slot"); [[ -n "$name" ]] && name="AMD $name"; fi
                [[ "$(_gpu_rd "$c/device/power/runtime_status")" == "suspended" ]] && asleep=true
                # the memory figures are the driver's own bookkeeping (no wake-up); a sleeping card is idle by definition
                mu=$(_gpu_rd "$c/device/mem_info_vram_used"); mt=$(_gpu_rd "$c/device/mem_info_vram_total")
                if [[ "$asleep" == true ]]; then
                    busy=0
                else
                    busy=$(_gpu_rd "$c/device/gpu_busy_percent")
                    for p in "$c"/device/hwmon/hwmon*; do [[ -d "$p" ]] && { hw=$p; break; }; done
                    if [[ -n "$hw" ]]; then
                        t1=$(_gpu_rd "$hw/temp1_input"); t2=$(_gpu_rd "$hw/temp2_input")
                        fr=$(_gpu_rd "$hw/fan1_input"); pw=$(_gpu_rd "$hw/pwm1"); pm=$(_gpu_rd "$hw/pwm1_max")
                        p=$(_gpu_rd "$hw/power1_average"); [[ -n "$p" ]] || p=$(_gpu_rd "$hw/power1_input"); pc=$(_gpu_rd "$hw/power1_cap")
                    fi
                fi
                line=$(jq -nc --arg name "${name:-AMD GPU}" --arg slot "$slot" --arg render "$render" --argjson asleep "$asleep" \
                    --arg busy "$busy" --arg mu "$mu" --arg mt "$mt" --arg t1 "$t1" --arg t2 "$t2" --arg fr "$fr" --arg pw "$pw" --arg pm "$pm" --arg p "$p" --arg pc "$pc" '
                    def n($v): $v | tonumber? // null;
                    {vendor: "amd", name: $name, slot: $slot, render: (if $render == "" then null else $render end),
                     utilization: n($busy), memory_used_mb: (n($mu) | if . == null then null else (. / 1048576 | floor) end),
                     memory_total_mb: (n($mt) | if . == null then null else (. / 1048576 | floor) end),
                     temperature: (n($t1) | if . == null then null else (. / 1000 | round) end),
                     temperature_hotspot: (n($t2) | if . == null then null else (. / 1000 | round) end),
                     fan_speed: (if n($pw) != null and (n($pm) // 0) > 0 then (n($pw) * 100 / n($pm) | round) else null end), fan_rpm: n($fr),
                     power_w: (n($p) | if . == null then null else (. / 100000 | round / 10) end),
                     power_cap_w: (n($pc) | if . == null then null else (. / 1000000 | round) end), asleep: $asleep}' 2>/dev/null) || continue
                rows+=("$line") ;;
            0x10de|0x8086)
                [[ "$vendor" == 0x10de && " ${nv_slots[*]} " == *" $slot "* ]] && continue
                name=$(_gpu_name_lspci "$slot")
                if [[ "$vendor" == 0x8086 ]]; then name="Intel ${name:-GPU}"; else name="NVIDIA ${name:-GPU} (no driver)"; fi
                rows+=("$(jq -nc --arg v "$([[ "$vendor" == 0x8086 ]] && echo intel || echo nvidia)" --arg name "$name" --arg slot "$slot" --arg render "$render" \
                    '{vendor: $v, name: $name, slot: $slot, render: (if $render == "" then null else $render end), utilization: null, memory_used_mb: null,
                      memory_total_mb: null, temperature: null, temperature_hotspot: null, fan_speed: null, fan_rpm: null, power_w: null, power_cap_w: null, asleep: false}')") ;;
        esac
    done
    if (( ${#rows[@]} )); then
        printf '%s\n' "${rows[@]}" | jq -sc 'to_entries | sort_by((if .value.utilization == null then 1 else 0 end), .key) | map(.value)' 2>/dev/null || echo '[]'
    else
        echo '[]'
    fi
}

# A graphics card for a template's services. The template says which services can use one and how, in template.json:
#   "gpu": [{"service": "ollama", "use": "compute", "images": {"amd": "ollama/ollama:rocm"}}]
# "use" is compute (AI: AMD needs /dev/kfd as well) or video (transcoding); "images" swaps the image for that vendor. The
# card is the one at PCI slot $3 (_gpu_list). Into each service of the compose ($1) go: AMD and Intel → the card's render
# node (the same path inside, so an app setting such as /dev/dri/renderD129 holds) and the host's video and render groups;
# NVIDIA → a device reservation for the NVIDIA Container Toolkit. Entries a service already has are not repeated. Prints
# the compose; when there is no such card, or it has no render node, prints one `__error=<why>` line and returns 1 (the
# reason cannot travel through a variable: this runs in a command substitution).
_template_gpu_apply() {
    local compose="$1" spec="$2" slot="$3" card vendor render gids="" g id
    card=$(_gpu_list | jq -c --arg s "$slot" 'map(select(.slot == $s)) | first // empty' 2>/dev/null)
    [[ -n "$card" ]] || { printf '__error=%s\n' "There is no graphics card at $slot on this server"; return 1; }
    vendor=$(jq -r '.vendor // ""' <<< "$card"); render=$(jq -r '.render // ""' <<< "$card")
    [[ "$vendor" == nvidia || "$render" =~ ^renderD[0-9]+$ ]] || { printf '__error=%s\n' "$(jq -r '.name' <<< "$card") has no render node (/dev/dri/renderD…): is its driver loaded?"; return 1; }
    for g in video render; do id=$(getent group "$g" 2>/dev/null | cut -d: -f3) || id=""; [[ "$id" =~ ^[0-9]+$ ]] && gids+="${gids:+,}$id"; done
    local svc use img devs grps nv out="$compose"
    while IFS=$'\t' read -r svc use img; do
        [[ "$svc" =~ ^[A-Za-z_][A-Za-z0-9_.-]*$ ]] || continue
        [[ -z "$img" || "$img" =~ ^[A-Za-z0-9][A-Za-z0-9._/:@-]*$ ]] || img=""
        devs=""; grps="$gids"; nv=""
        case "$vendor" in
            amd)    devs="/dev/dri/$render:/dev/dri/$render"; [[ "$use" == compute ]] && devs+=",/dev/kfd:/dev/kfd" ;;
            intel)  devs="/dev/dri/$render:/dev/dri/$render" ;;
            nvidia) grps=""; nv="gpu, compute, utility"; [[ "$use" == video ]] && nv+=", video" ;;
        esac
        out=$(printf '%s\n' "$out" | awk -v svc="$svc" -v img="$img" -v devs="$devs" -v grps="$grps" -v nv="$nv" '
            function items(list, quote, blk,   k, a, j, v) {
                k = split(list, a, ",")
                for (j = 1; j <= k; j++) { v = a[j]; if (v == "") continue; if (quote) v = "\"" v "\""; if (blk != "" && index(blk, a[j])) continue; print "      - " v }
            }
            function flush(   i, blk, hasdev, hasgrp, hasdep, line) {
                if (!n) return
                blk = ""; hasdev = hasgrp = hasdep = 0
                for (i = 1; i <= n; i++) { blk = blk "\n" buf[i]; if (buf[i] ~ /^    devices:/) hasdev = 1; if (buf[i] ~ /^    group_add:/) hasgrp = 1; if (buf[i] ~ /^    deploy:/) hasdep = 1 }
                for (i = 1; i <= n; i++) {
                    line = buf[i]
                    if (img != "" && line ~ /^    image:/) line = "    image: " img
                    print line
                    if (line ~ /^    devices:/) items(devs, 0, blk)
                    if (line ~ /^    group_add:/) items(grps, 1, blk)
                    if (i == 1) {
                        if (devs != "" && !hasdev) { print "    devices:"; items(devs, 0, "") }
                        if (grps != "" && !hasgrp) { print "    group_add:"; items(grps, 1, "") }
                        if (nv != "" && !hasdep) {
                            print "    deploy:"; print "      resources:"; print "        reservations:"; print "          devices:"
                            print "            - driver: nvidia"; print "              count: all"; print "              capabilities: [" nv "]"
                        }
                    }
                }
                n = 0
            }
            /^[A-Za-z]/ { flush(); insvc = 0; section = $1 }
            section == "services:" && /^  [A-Za-z0-9_.-]+:[ \t]*$/ {
                flush(); cur = $1; sub(/:$/, "", cur)
                if (cur == svc) { insvc = 1; n = 1; buf[1] = $0; next }
                insvc = 0
            }
            insvc { buf[++n] = $0; next }
            { print }
            END { flush() }')
    done < <(jq -r --arg v "$vendor" '.[]? | [.service // "", (.use // "video"), (.images[$v] // "")] | @tsv' <<< "$spec" 2>/dev/null)
    printf '%s\n' "$out"
}

# GET /status — Host and Docker overview: containers, images, stacks, load, memory, disk, the graphics cards (NVIDIA, AMD, Intel); server_name is SERVER_NAME from .env (empty when unset)
handle_status() {
    # PERFORMANCE: Use docker system info for counts (single command) + parallel for the rest
    local total_containers=0 running_containers=0 stopped_containers=0
    local total_images=0 total_volumes=0 total_networks=0

    # Get all counts from docker system info in one call
    if command -v jq >/dev/null 2>&1; then
        local dinfo
        dinfo=$(timeout 5 docker system info --format '{{json .}}' 2>/dev/null)
        if [[ -n "$dinfo" ]]; then
            total_containers=$(printf '%s' "$dinfo" | jq '.Containers // 0' 2>/dev/null)
            running_containers=$(printf '%s' "$dinfo" | jq '.ContainersRunning // 0' 2>/dev/null)
            stopped_containers=$(printf '%s' "$dinfo" | jq '.ContainersStopped // 0' 2>/dev/null)
            # Top-level images, the same rows the Images page lists (docker info's
            # count also includes untagged intermediate layers)
            total_images=$(docker images -q 2>/dev/null | wc -l | tr -d ' ')
        fi
    fi

    # on-demand containers asleep (Sablier stopped them on purpose): part of "stopped" as Docker counts it, healthy all the same
    local sleeping_containers=0; [[ -n "${dinfo:-}" ]] && sleeping_containers=$(_sablier_asleep_count)
    [[ "$sleeping_containers" =~ ^[0-9]+$ ]] || sleeping_containers=0

    # Volumes and networks (fast, no heavy operations)
    total_volumes=$(timeout 3 docker volume ls -q 2>/dev/null | wc -l)
    total_networks=$(timeout 3 docker network ls --format '{{.Name}}' 2>/dev/null | grep -cv '^bridge$\|^host$\|^none$') || total_networks=0

    # Disk: the filesystem that holds this installation (stacks and App-Data)
    local disk_usage
    disk_usage=$(df -hP "$BASE_DIR" 2>/dev/null | tail -1 | awk '{printf "{\"total\": \"%s\", \"used\": \"%s\", \"available\": \"%s\", \"percent\": \"%s\", \"mount\": \"%s\"}", $2, $3, $4, $5, $6}')
    [[ -z "$disk_usage" || "$disk_usage" == *'""'* ]] && disk_usage=$(df -hP / 2>/dev/null | tail -1 | awk '{printf "{\"total\": \"%s\", \"used\": \"%s\", \"available\": \"%s\", \"percent\": \"%s\", \"mount\": \"/\"}", $2, $3, $4, $5}')

    local load_avg mem_total mem_available swap_total swap_free
    load_avg=$(awk '{printf "[%s, %s, %s]", $1, $2, $3}' /proc/loadavg 2>/dev/null || echo "[0,0,0]")
    mem_total=$(awk '/MemTotal/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
    mem_available=$(awk '/MemAvailable/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
    swap_total=$(awk '/SwapTotal/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
    swap_free=$(awk '/SwapFree/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)

    local uptime_seconds
    uptime_seconds=$(awk '{printf "%d", $1}' /proc/uptime 2>/dev/null || echo 0)

    # Fast stack count: use docker compose ls (single command, lists all projects)
    local stacks
    read -ra stacks <<< "$(_api_get_stacks)"
    local running_stacks=0
    local active_projects
    active_projects=$(timeout 5 docker compose ls --format json 2>/dev/null | jq -r '.[].Name' 2>/dev/null) || active_projects=""
    # a hub: a folder left behind by a stack that moved into a VM is that VM's stack, not one of the hub's (the
    # hub's own stacks — in DOCKER_STACKS or with containers up — always count); the VMs' stacks are counted apart
    if _fleet_has_members; then
        local vm_names kept=()
        vm_names=" $(_fleet_load | jq -r '[.members[].stacks[]?] | unique | join(" ")' 2>/dev/null) "
        for s in "${stacks[@]}"; do
            if [[ "$vm_names" == *" $s "* ]] && [[ " ${DOCKER_STACKS:-} " != *" $s "* ]]; then
                grep -qx -- "$s" <<< "$active_projects" 2>/dev/null || continue
            fi
            kept+=("$s")
        done
        stacks=("${kept[@]+"${kept[@]}"}")
    fi
    for s in "${stacks[@]}"; do
        if echo "$active_projects" | grep -q "^${s}$" 2>/dev/null; then
            running_stacks=$(( running_stacks + 1 ))
        fi
    done

    local cpu_count
    cpu_count=$(nproc 2>/dev/null || echo 0)

    # the graphics cards: "gpu" stays the busiest one in the shape older dashboards read, "gpus" lists them all
    local gpus_json gpu_json
    gpus_json=$(_gpu_list) || gpus_json='[]'; [[ "$gpus_json" == \[* ]] || gpus_json='[]'
    gpu_json=$(jq -c 'map(select(.utilization != null)) | first // null | if . == null then null else . + {fan_speed: (.fan_speed // 0)} end' <<< "$gpus_json" 2>/dev/null) || gpu_json=null
    [[ -n "$gpu_json" ]] || gpu_json=null

    _api_success "{\"timestamp\": \"$(_api_now_iso)\", \"hostname\": \"$(_api_json_escape "$(_hostname)")\", \"server_name\": \"$(_api_json_escape "${SERVER_NAME:-}")\", \"uptime_seconds\": $uptime_seconds, \"docker\": {\"containers\": {\"total\": $total_containers, \"running\": $running_containers, \"stopped\": $stopped_containers, \"sleeping\": $sleeping_containers}, \"images\": $total_images, \"volumes\": $total_volumes, \"networks\": $total_networks}, \"stacks\": {\"total\": ${#stacks[@]}, \"running\": $running_stacks}, \"system\": {\"load_average\": $load_avg, \"memory_mb\": {\"total\": $mem_total, \"available\": $mem_available}, \"swap_mb\": {\"total\": $swap_total, \"free\": $swap_free}, \"gpu\": $gpu_json, \"gpus\": $gpus_json, \"disk\": $disk_usage, \"cpu_count\": $cpu_count}}"
}

# Internal variant — returns JSON to stdout (used by export handler)
handle_system_info_internal() {
    local load_avg mem_total mem_available uptime_seconds cpu_count disk_usage
    load_avg=$(awk '{printf "[%s, %s, %s]", $1, $2, $3}' /proc/loadavg 2>/dev/null || echo "[0,0,0]")
    mem_total=$(awk '/MemTotal/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
    mem_available=$(awk '/MemAvailable/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
    uptime_seconds=$(awk '{printf "%d", $1}' /proc/uptime 2>/dev/null || echo 0)
    cpu_count=$(nproc 2>/dev/null || echo 0)
    disk_usage=$(df -hP "$BASE_DIR" 2>/dev/null | tail -1 | awk '{printf "{\"total\":\"%s\",\"used\":\"%s\",\"available\":\"%s\",\"percent\":\"%s\"}", $2, $3, $4, $5}')
    [[ -z "$disk_usage" || "$disk_usage" == *'""'* ]] && disk_usage=$(df -hP / 2>/dev/null | tail -1 | awk '{printf "{\"total\":\"%s\",\"used\":\"%s\",\"available\":\"%s\",\"percent\":\"%s\"}", $2, $3, $4, $5}')
    printf '{"hostname":"%s","uptime_seconds":%d,"system":{"load_average":%s,"memory_mb":{"total":%d,"available":%d},"disk":%s,"cpu_count":%d}}' \
        "$(_api_json_escape "$(_hostname)")" "$uptime_seconds" "$load_avg" "$mem_total" "$mem_available" "${disk_usage:-"{}"}" "$cpu_count"
}

# GET /health — Health report for every container (running, unhealthy, stopped, restart loops) On a hub, ?fleet=1 adds every member's containers (member, member_name, vmid) and per-member summaries
handle_health() {
    local -a results=()
    local total=0 healthy=0 unhealthy=0 stopped=0 sleeping=0 od_stuck=0
    # the first minutes after a boot the stacks are still being started: a container not up yet is not news
    local _hw_boot=false; (( $(cut -d. -f1 /proc/uptime 2>/dev/null || echo 999999) <= ${HEALTH_WATCH_BOOT_GRACE:-300} )) && _hw_boot=true
    # Containers Sablier stops on purpose are idle, not down
    local -A _on_demand=()
    local _sn
    while IFS= read -r _sn; do [[ -n "$_sn" ]] && _on_demand["$_sn"]=1; done < <(_sablier_names)
    # ...as long as Sablier runs to wake them (null: nothing here starts on demand)
    local _sab_up=null; local -A _asleep=()
    (( ${#_on_demand[@]} > 0 )) && { _sablier_up && _sab_up=true || _sab_up=false; }

    # Get restart threshold from config
    local _restart_threshold=5
    if [[ -f "$BASE_DIR/.data/config.json" ]] && command -v jq >/dev/null 2>&1; then
        local _rt
        _rt=$(jq -r '.thresholds.restart_threshold // 5' "$BASE_DIR/.data/config.json" 2>/dev/null)
        [[ "$_rt" =~ ^[0-9]+$ ]] && _restart_threshold="$_rt"
    fi

    # Single docker inspect for ALL containers — include restart count
    local inspect_data=""
    local all_cids _dps _dps_rc=0 docker_down=false docker_err=""
    # A Docker that does not answer is not "no containers": every container is down. The empty list must not read as healthy.
    _dps=$(timeout 5 docker ps -a -q 2>&1) || _dps_rc=$?
    if (( _dps_rc != 0 )); then
        docker_down=true
        if (( _dps_rc == 124 )); then docker_err="Docker did not answer within 5 seconds"
        elif [[ "$_dps_rc" == 127 ]]; then docker_err="Docker is not installed on this server"
        else docker_err=$(printf '%s' "$_dps" | tr '\n' ' ' | head -c 200); fi
        all_cids=""
    else
        all_cids=$(printf '%s' "$_dps" | tr '\n' ' ')
    fi
    if [[ -n "$all_cids" ]] && command -v jq >/dev/null 2>&1; then
        inspect_data=$(timeout 10 docker inspect $all_cids 2>/dev/null | jq -r '.[] | "\(.Name | ltrimstr("/"))\t\(.State.Status)\t\(if .State.Health then .State.Health.Status else "none" end)\t\(.RestartCount // 0)\t\(.Config.Labels["com.docker.compose.project"] // "")"' 2>/dev/null) || inspect_data=""
    fi

    local -a _bad_names=() _stopped_names=() _unhealthy_names=()
    local _bad_list="" cstack
    while IFS=$'\t' read -r name state health restart_count cstack; do
        [[ -z "$name" ]] && continue
        name="${name#/}"
        total=$(( total + 1 ))

        if [[ "$state" != "running" && -n "${_on_demand[$name]:-}" ]]; then
            sleeping=$(( sleeping + 1 )); _asleep["$name"]=1
            # stopped on purpose: its last health check is history, not a problem (unless nothing can wake it)
            health="sleeping"
            [[ "$_sab_up" == false ]] && od_stuck=$(( od_stuck + 1 ))
        elif [[ "$state" != "running" ]]; then
            stopped=$(( stopped + 1 ))
            _bad_names+=("$name"); _stopped_names+=("$name")
            [[ "$_hw_boot" == true ]] || _fire_notifications "container_stopped" "container=$name" "status=stopped" "stack=$cstack" 2>/dev/null
        elif [[ "$health" == "unhealthy" ]]; then
            unhealthy=$(( unhealthy + 1 ))
            _bad_names+=("$name"); _unhealthy_names+=("$name"); _bad_list+="${_bad_list:+, }$name"
            [[ "$_hw_boot" == true ]] || _fire_notifications "container_unhealthy" "container=$name" "status=unhealthy" "stack=$cstack" 2>/dev/null
        else
            healthy=$(( healthy + 1 ))
        fi

        # Check restart threshold
        if [[ "${restart_count:-0}" -ge "$_restart_threshold" ]] 2>/dev/null; then
            _bad_names+=("$name"); _unhealthy_names+=("$name")
            [[ "$_hw_boot" == true ]] || _fire_notifications "container_unhealthy" "container=$name" "status=restarting (${restart_count}x)" "stack=$cstack" 2>/dev/null
        fi

        results+=("{\"name\": \"$(_api_json_escape "$name")\", \"state\": \"$state\", \"health\": \"$health\", \"restart_count\": ${restart_count:-0}, \"on_demand\": $([[ -n "${_on_demand[$name]:-}" ]] && echo true || echo false), \"sablier_up\": $([[ -n "${_on_demand[$name]:-}" ]] && echo "$_sab_up" || echo null)}")
    done <<< "$inspect_data"

    # Status logic: stopped containers are expected/normal and don't affect health.
    # Only actually unhealthy containers (failed healthchecks) trigger warnings.
    local overall="healthy"
    if (( unhealthy >= 3 )); then
        overall="critical"
    elif (( unhealthy > 0 )); then
        overall="degraded"
    fi
    [[ "$docker_down" == "true" ]] && overall="critical"

    local containers_json
    containers_json=$(printf '%s,' "${results[@]}")
    containers_json="[${containers_json%,}]"

    # API server metrics: uptime, request/error counts, memory usage
    local api_uptime=0 api_requests=0 api_errors=0
    local now_epoch
    now_epoch=$(date +%s)
    api_uptime=$(( now_epoch - ${API_START_EPOCH:-now_epoch} ))

    if [[ -f "$API_STATS_FILE" ]]; then
        api_requests=$(sed -n '1p' "$API_STATS_FILE" 2>/dev/null || echo 0)
        api_errors=$(sed -n '2p' "$API_STATS_FILE" 2>/dev/null || echo 0)
    fi

    # API process memory (RSS in KB)
    local api_pid_val api_mem_kb=0
    if [[ -f "$API_PID_FILE" ]]; then
        api_pid_val=$(cat "$API_PID_FILE" 2>/dev/null)
        if [[ -n "$api_pid_val" ]] && kill -0 "$api_pid_val" 2>/dev/null; then
            api_mem_kb=$(ps -o rss= -p "$api_pid_val" 2>/dev/null | tr -d ' ' || echo 0)
        fi
    fi

    # What changed since the last poll goes to the audit log and the Integrations
    # webhooks: containers that stopped on their own, failed their health check,
    # or came back. Stops and starts DCS performed itself are not news.
    local _tr_kind _tr_name
    local -a _tr_stopped=() _tr_unhealthy=() _tr_recovered=()
    while read -r _tr_kind _tr_name; do
        [[ -n "$_tr_name" ]] || continue
        case "$_tr_kind" in
            stopped)   _container_intended "$_tr_name" "$(_container_label "$_tr_name" com.docker.compose.project)" || _tr_stopped+=("$_tr_name") ;;
            unhealthy) _tr_unhealthy+=("$_tr_name") ;;
            # an on-demand container that fell asleep left the "bad" list without coming back: it is not news either way
            recovered) [[ -n "${_asleep[$_tr_name]:-}" ]] && continue
                       _container_intended "$_tr_name" "$(_container_label "$_tr_name" com.docker.compose.project)" || _tr_recovered+=("$_tr_name") ;;
        esac
    done < <(_health_transitions "${_stopped_names[*]}" "${_unhealthy_names[*]}")
    _health_announce container_stopped "stopped on its own" ${_tr_stopped[@]+"${_tr_stopped[@]}"}
    _health_announce container_unhealthy "is failing its health check" ${_tr_unhealthy[@]+"${_tr_unhealthy[@]}"}
    _health_announce container_recovered "is running and healthy again" ${_tr_recovered[@]+"${_tr_recovered[@]}"}

    # Containers that recovered may alert again right away
    _notify_state_prune_containers ${_bad_names[@]+"${_bad_names[@]}"}

    # The overall verdict (healthy, degraded, critical) is announced once per change
    local _hs_file="$BASE_DIR/.data/health-state" _prev_overall=""
    [[ -f "$_hs_file" ]] && _prev_overall=$(cat "$_hs_file" 2>/dev/null)
    if [[ "$_prev_overall" != "$overall" ]]; then
        printf '%s' "$overall" > "$_hs_file" 2>/dev/null || true
        if [[ -n "$_prev_overall" ]]; then
            local _hmsg="Health went from $_prev_overall to $overall: $healthy healthy, $unhealthy unhealthy, $stopped stopped"
            [[ -n "$_bad_list" ]] && _hmsg+=" (unhealthy: $_bad_list)"
            _audit_log "health_change" "$_hmsg" 2>/dev/null
            _fire_notifications "health_change" "status=$overall" "message=$_hmsg" 2>/dev/null
        fi
    fi

    local _od_missing
    _od_missing=$(_sablier_missing | tr '\n' ' ')
    _api_success "{\"status\": \"$overall\", \"summary\": {\"total\": $total, \"healthy\": $healthy, \"unhealthy\": $unhealthy, \"stopped\": $stopped, \"sleeping\": $sleeping, \"sablier_running\": $_sab_up, \"on_demand_stuck\": $od_stuck, \"on_demand_missing\": $(_upd_json_list ${_od_missing})}, \"containers\": $containers_json, \"api\": {\"uptime_seconds\": $api_uptime, \"requests_total\": ${api_requests:-0}, \"errors_total\": ${api_errors:-0}, \"memory_kb\": ${api_mem_kb:-0}, \"pid\": ${api_pid_val:-0}}, \"docker\": {\"reachable\": $([[ "$docker_down" == "true" ]] && echo false || echo true), \"error\": \"$(_api_json_escape "$docker_err")\"}}"
}

# Internal variant — returns JSON to stdout (used by export handler)
handle_health_internal() {
    local -a results=()
    local total=0 healthy=0 unhealthy=0 stopped=0
    local inspect_data="" all_cids
    all_cids=$(timeout 5 docker ps -a -q 2>/dev/null | tr '\n' ' ')
    if [[ -n "$all_cids" ]] && command -v jq >/dev/null 2>&1; then
        inspect_data=$(timeout 10 docker inspect $all_cids 2>/dev/null | jq -r '.[] | "\(.Name | ltrimstr("/"))\t\(.State.Status)\t\(if .State.Health then .State.Health.Status else "none" end)"' 2>/dev/null) || inspect_data=""
    fi
    while IFS=$'\t' read -r name state health; do
        [[ -z "$name" ]] && continue
        name="${name#/}"; total=$(( total + 1 ))
        if [[ "$state" != "running" ]]; then stopped=$(( stopped + 1 ))
        elif [[ "$health" == "unhealthy" ]]; then unhealthy=$(( unhealthy + 1 ))
        else healthy=$(( healthy + 1 )); fi
        results+=("{\"name\":\"$(_api_json_escape "$name")\",\"state\":\"$state\",\"health\":\"$health\"}")
    done <<< "$inspect_data"
    local overall="healthy"
    (( unhealthy >= 3 )) && overall="critical"
    (( unhealthy > 0 && unhealthy < 3 )) && overall="degraded"
    local cj; cj=$(printf '%s,' "${results[@]}"); cj="[${cj%,}]"
    printf '{"status":"%s","summary":{"total":%d,"healthy":%d,"unhealthy":%d,"stopped":%d},"containers":%s}' \
        "$overall" "$total" "$healthy" "$unhealthy" "$stopped" "$cj"
}

# _stacks_card_facts — for the stack cards, per compose project: every container (stopped ones too), the CPU and memory of
# its running ones (the stats cache, percent of the machine), the images with an update waiting (the registry cache; an
# untagged image is :latest) and the TCP ports it publishes beyond localhost. Rows on stdin, one docker call for all:
# name<TAB>project<TAB>image<TAB>state<TAB>ports
_stacks_card_facts() {
    local stats ic
    stats=$(jq -c . "$BASE_DIR/.data/container-stats-cache.json" 2>/dev/null) || stats='{}'; [[ "$stats" == \{* ]] || stats='{}'
    ic=$(jq -c . "$BASE_DIR/.data/image-update-cache.json" 2>/dev/null) || ic='{}'; [[ "$ic" == \{* ]] || ic='{}'
    jq -Rsc --argjson st "$stats" --argjson ic "$ic" '
        [split("\n")[] | select(length > 0) | split("\t")
            | {name: .[0], project: (.[1] // ""), image: (.[2] // ""), state: (.[3] // ""), ports: (.[4] // "")} | select(.project != "")]
        | group_by(.project) | map({key: .[0].project, value: {
            total: length,
            cpu: ([.[] | select(.state == "running") | $st[.name].cpu | numbers] | if length == 0 then null else add * 100 | round / 100 end),
            mem: ([.[] | select(.state == "running") | $st[.name].mem | numbers] | if length == 0 then null else add * 100 | round / 100 end),
            updates: ([.[] | .image | select(($ic[.] // (if test(":[^/]+$") then null else $ic[. + ":latest"] end) // false) == true)] | unique | length),
            ports: ([.[] | .ports | scan("(?:^|, )([0-9.]+|\\[[0-9a-f:]*\\]):([0-9]+)->[0-9]+/tcp")
                     | select(.[0] != "127.0.0.1" and .[0] != "[::1]") | .[1] | tonumber] | unique)
        }}) | from_entries' 2>/dev/null || printf '{}'
}
# _stack_card_hosts STACK [ROUTES_DIR] — the hostnames Traefik serves the stack on (its compose labels and its route files), one
# per line; a rule that still holds a variable is left out. A ROUTES_DIR given empty means "no Traefik here": the lookup
# (a pass over every stack) is not repeated for each stack of a list
_stack_card_hosts() {
    local s="$1" rdir="${2-}" f
    [[ $# -ge 2 ]] || { rdir=$(_find_traefik_routes_dir 2>/dev/null) || rdir=""; }
    {
        grep -oE 'Host\(`[^`]+`\)' "$COMPOSE_DIR/$s/docker-compose.yml" 2>/dev/null
        if [[ -n "$rdir" && -d "$rdir/$s" ]]; then for f in "$rdir/$s"/*.yml "$rdir/$s"/*.yaml; do [[ -f "$f" ]] && grep -oE 'Host\(`[^`]+`\)' "$f" 2>/dev/null; done; fi
    } | sed -E 's/^Host\(`//; s/`\)$//' | grep -vE '\$|[[:space:]]' | awk '!seen[$0]++' || true
}
# _backup_stack_times_record PARTS_JSON — when each stack in a finished backup was taken (.data/backup-stack-times.json)
_backup_stack_times_record() {
    local f="$BASE_DIR/.data/backup-stack-times.json" cur
    cur=$(jq -c . "$f" 2>/dev/null) || cur='{}'; [[ "$cur" == \{* ]] || cur='{}'
    mkdir -p "$BASE_DIR/.data" 2>/dev/null
    jq -c --argjson p "${1:-[]}" --arg t "$(_api_now_iso)" '. + ([$p[]? | select(.kind == "stack") | {key: .name, value: $t}] | from_entries)' <<< "$cur" > "$f.tmp" 2>/dev/null \
        && mv -f "$f.tmp" "$f" 2>/dev/null
    rm -f "$f.tmp" 2>/dev/null
    return 0
}

# GET /stacks — All stacks with running-container counts
handle_stacks() {
    local stacks _SAB_NAMES _down_od="" _sab_up=null
    _SAB_NAMES=$(_sablier_names 2>/dev/null)
    # asleep is fine while Sablier runs to wake them (null: nothing here starts on demand)
    [[ -n "$_SAB_NAMES" ]] && { _sablier_up && _sab_up=true || _sab_up=false; }
    read -ra stacks <<< "$(_api_get_stacks)"
    # on-demand containers that are not running (Sablier wakes them on a request): "<project>" per container, one docker call
    [[ -n "$_SAB_NAMES" ]] && _down_od=$(timeout 10 docker ps -a --filter status=created --filter status=exited --format '{{.Names}}	{{.Label "com.docker.compose.project"}}' 2>/dev/null \
        | awk -F'\t' 'NR == FNR { od[$0] = 1; next } ($1 in od) && $2 != "" { print $2 }' <(printf '%s\n' "$_SAB_NAMES") - 2>/dev/null)
    # the cards' facts: every container in one docker call, the backup times and Traefik's route folder read once
    local _cf _bt _rdir
    _cf=$(timeout 10 docker ps -a --format '{{.Names}}	{{.Label "com.docker.compose.project"}}	{{.Image}}	{{.State}}	{{.Ports}}' 2>/dev/null | _stacks_card_facts) || _cf='{}'
    [[ "$_cf" == \{* ]] || _cf='{}'
    _bt=$(jq -c . "$BASE_DIR/.data/backup-stack-times.json" 2>/dev/null) || _bt='{}'; [[ "$_bt" == \{* ]] || _bt='{}'
    _rdir=$(_find_traefik_routes_dir 2>/dev/null) || _rdir=""
    # a hub lists the stacks its member VMs run next to its own; the hub's folder of such a stack (its copy) is not
    # looked at, the VM's entry stands for it
    local remote="" _rn=""
    if _fleet_has_members; then
        remote=$(_fleet_remote_stacks_json); [[ "$remote" == \[* ]] || remote='[]'
        _rn=$(jq -r '.[].name' <<< "$remote" 2>/dev/null)
    fi

    local -a entries=()
    for stack in "${stacks[@]}"; do
        [[ -n "$_rn" ]] && grep -qxF -- "$stack" <<< "$_rn" && continue
        local st
        st=$(_api_stack_status "$stack")
        local status="${st%%:*}"
        local count="${st#*:}"

        local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
        local has_env="false"
        [[ -f "$COMPOSE_DIR/$stack/.env" ]] && has_env="true"

        # Count services defined in compose file
        local service_count
        service_count=$(grep -c '^\s\+[a-zA-Z]' "$compose_file" 2>/dev/null) || service_count=0

        local asleep=false
        [[ "$status" == stopped ]] && _stack_asleep "$stack" && asleep=true
        local zc=0 ho=false; [[ -n "$_down_od" ]] && zc=$(grep -cxF -- "$stack" <<< "$_down_od"); [[ "$zc" =~ ^[0-9]+$ ]] || zc=0
        _fleet_hub_only "$stack" && ho=true
        local _tot="$count" _cpu=null _mem=null _upd=0 _ports='[]' _links='[]' _lb=null
        IFS=$'\t' read -r _tot _cpu _mem _upd _ports _lb < <(jq -r --arg s "$stack" --argjson bt "$_bt" --argjson run "$count" \
            '(.[$s] // {total: $run, cpu: null, mem: null, updates: 0, ports: []}) | [([.total, $run] | max), (.cpu | tojson), (.mem | tojson), .updates, (.ports | tojson), ($bt[$s] // null | tojson)] | @tsv' \
            <<< "$_cf" 2>/dev/null) || true
        [[ "$_tot" =~ ^[0-9]+$ ]] || _tot="$count"; [[ "$_cpu" =~ ^[0-9.]+$ ]] || _cpu=null; [[ "$_mem" =~ ^[0-9.]+$ ]] || _mem=null
        [[ "$_upd" =~ ^[0-9]+$ ]] || _upd=0; [[ "$_ports" == \[* ]] || _ports='[]'; [[ -n "$_lb" ]] || _lb=null
        _links=$(_stack_card_hosts "$stack" "$_rdir" | jq -Rsc 'split("\n") | map(select(length > 0) | "https://" + .)') || _links='[]'
        [[ "$_links" == \[* ]] || _links='[]'
        entries+=("{\"name\": \"$stack\", \"status\": \"$status\", \"running_containers\": $count, \"sleeping\": $asleep, \"sleeping_containers\": $zc, \"sablier_up\": $_sab_up, \"hub_only\": $ho, \"app_data\": $(_stack_appdata_json "$stack"), \"has_env\": $has_env, \"compose_file\": \"$(_api_json_escape "$compose_file")\", \"total_containers\": $_tot, \"cpu_percent\": $_cpu, \"mem_percent\": $_mem, \"updates_available\": $_upd, \"ports\": $_ports, \"links\": $_links, \"last_backup\": $_lb}")
    done

    local json
    json=$(printf '%s,' "${entries[@]}")
    json="[${json%,}]"

    if [[ -n "$remote" ]]; then
        # a member's stack replaces the hub's entry of the same name (a leftover folder on the hub)
        json=$(jq -c --argjson r "$remote" '($r | map(.name)) as $rn | (map(select(.name as $n | ($rn | index($n)) == null) | . + {placement: "hub"})) + $r' <<< "$json")
        _api_success "$(jq -nc --argjson s "$json" '{total: ($s | length), stacks: $s, local: ([$s[] | select(.placement == "hub")] | length), remote: ([$s[] | select(.placement == "vm")] | length)}')"
        return
    fi
    _api_success "{\"total\": ${#stacks[@]}, \"stacks\": $json}"
}

# GET /stacks/{stack} — Stack detail: services, containers and images
handle_stack_detail() {
    local stack="$1"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if [[ ! -f "$compose_file" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    local -a compose_args=(-f "$compose_file")
    [[ -f "$env_file" ]] && compose_args+=(--env-file "$env_file")

    local st
    st=$(_api_stack_status "$stack")
    local status="${st%%:*}"
    local count="${st#*:}"

    # Get services from config
    local -a services=()
    while IFS= read -r svc; do
        [[ -n "$svc" ]] && services+=("\"$(_api_json_escape "$svc")\"")
    done < <($DOCKER_COMPOSE_CMD "${compose_args[@]}" config --services 2>/dev/null)

    local services_json
    services_json=$(printf '%s,' "${services[@]}")
    services_json="[${services_json%,}]"

    # Get containers
    local -a container_entries=()
    while IFS= read -r cid; do
        [[ -z "$cid" ]] && continue
        container_entries+=("$(_api_container_json "$cid")")
    done < <($DOCKER_COMPOSE_CMD "${compose_args[@]}" ps -a -q 2>/dev/null)

    local containers_json
    containers_json=$(printf '%s,' "${container_entries[@]}")
    containers_json="[${containers_json%,}]"
    # every container of the stack, a sleeping one too (Sablier stopped it on purpose): each says whether it starts on demand
    local _sabn _sabu=null; _sabn=$(_sablier_names 2>/dev/null)
    [[ -n "$_sabn" ]] && { _sablier_up && _sabu=true || _sabu=false; }
    containers_json=$(jq -c --arg n "$_sabn" --argjson up "$_sabu" '($n | split("\n") | map(select(. != ""))) as $od
        | map(. + {on_demand: (((.name // "") | ltrimstr("/")) as $x | ($od | index($x)) != null)})
        | map(. + {sleeping: (.on_demand and ((.state // "") | ascii_downcase) != "running"), sablier_up: (if .on_demand then $up else null end)})' <<< "$containers_json" 2>/dev/null || printf '%s' "$containers_json")

    # Get images used
    local -a image_entries=()
    while IFS= read -r img; do
        [[ -z "$img" ]] && continue
        local img_id size
        img_id=$(docker image inspect --format='{{.Id}}' "$img" 2>/dev/null)
        size=$(docker image inspect --format='{{.Size}}' "$img" 2>/dev/null)
        image_entries+=("{\"name\": \"$(_api_json_escape "$img")\", \"id\": \"${img_id:7:12}\", \"size\": ${size:-0}}")
    done < <($DOCKER_COMPOSE_CMD "${compose_args[@]}" config 2>/dev/null | grep 'image:' | awk '{print $2}' | sort -u)

    local images_json
    images_json=$(printf '%s,' "${image_entries[@]}")
    images_json="[${images_json%,}]"

    local asleep=false; [[ "$status" == stopped ]] && _stack_asleep "$stack" && asleep=true
    local _zc; _zc=$(jq -r '[.[] | select(.sleeping == true)] | length' <<< "$containers_json" 2>/dev/null); [[ "$_zc" =~ ^[0-9]+$ ]] || _zc=0
    _api_success "{\"name\": \"$stack\", \"status\": \"$status\", \"running_containers\": $count, \"sleeping\": $asleep, \"sleeping_containers\": $_zc, \"sablier_up\": $_sabu, \"app_data\": $(_stack_appdata_json "$stack"), \"has_env\": $([[ -f "$env_file" ]] && echo true || echo false), \"services\": $services_json, \"containers\": $containers_json, \"images\": $images_json}"
}

# GET /stacks/{stack}/containers — Containers of one stack
handle_stack_containers() {
    local stack="$1"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if [[ ! -f "$compose_file" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    local -a compose_args=(-f "$compose_file")
    [[ -f "$env_file" ]] && compose_args+=(--env-file "$env_file")

    local -a entries=()
    while IFS= read -r cid; do
        [[ -z "$cid" ]] && continue
        entries+=("$(_api_container_json "$cid")")
    done < <($DOCKER_COMPOSE_CMD "${compose_args[@]}" ps -q 2>/dev/null)

    local json
    json=$(printf '%s,' "${entries[@]}")
    json="[${json%,}]"

    _api_success "{\"stack\": \"$stack\", \"containers\": $json}"
}

# GET /stacks/{stack}/logs — Recent log lines of a stack
handle_stack_logs() {
    local stack="$1"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if [[ ! -f "$compose_file" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    local -a compose_args=(-f "$compose_file")
    [[ -f "$env_file" ]] && compose_args+=(--env-file "$env_file")

    local logs_raw
    logs_raw=$($DOCKER_COMPOSE_CMD "${compose_args[@]}" logs --tail 50 --no-color 2>&1)
    local escaped
    escaped=$(_api_json_escape "$logs_raw")

    _api_success "{\"stack\": \"$stack\", \"lines\": 50, \"logs\": \"$escaped\"}"
}

# GET /stacks/{stack}/compose — The stack's docker-compose.yml
handle_stack_compose() {
    local stack="$1"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"

    if [[ ! -f "$compose_file" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    local content
    content=$(cat "$compose_file" 2>/dev/null) || {
        _api_error 500 "Failed to read compose file for stack: $stack"
        return
    }

    local escaped
    escaped=$(_api_json_escape "$content")

    _api_success "{\"stack\": \"$(_api_json_escape "$stack")\", \"content\": \"$escaped\"}"
}

# =============================================================================
# COMPOSE EDITOR & STACK ENV HANDLERS (Phase 1)
# =============================================================================

# POST /stacks/{stack}/compose/validate — Validate compose content for a stack without saving it
handle_stack_compose_validate() {
    local stack="$1"
    local body="$2"

    if [[ ! -d "$COMPOSE_DIR/$stack" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    if ! command -v jq >/dev/null 2>&1; then
        _api_error 500 "jq is required for compose validation"
        return
    fi

    local content
    content=$(printf '%s' "$body" | jq -r '.content // empty' 2>/dev/null)
    if [[ -z "$content" ]]; then
        _api_error 400 "Missing 'content' field in request body"
        return
    fi

    # SECURITY: Scan compose content for dangerous Docker features.
    # Use "deploy" mode if the stack was created from a trusted template (has .dcs-trusted-templates).
    # This allows template-required capabilities (docker.sock, label:disable) to persist through edits.
    local _scan_mode="strict"
    [[ -f "$COMPOSE_DIR/$stack/.dcs-trusted-templates" ]] && _scan_mode="deploy"
    if ! _api_scan_compose_security "$content" "compose validation for $stack" "$_scan_mode"; then
        return
    fi

    # Normalize ${SECRETS.KEY} → ${SECRETS_KEY} for validation
    content=$(printf '%s' "$content" | _normalize_secrets_syntax)

    local tmpfile
    tmpfile=$(mktemp /tmp/dcs-compose-validate-XXXXXX.yml)
    printf '%s' "$content" > "$tmpfile"

    local _stack_env="$COMPOSE_DIR/$stack/.env"
    local env_args=()
    [[ -f "$_stack_env" ]] && env_args=(--env-file "$_stack_env")

    # Validation is open to the viewer role and returns compose's output, so it
    # must never interpolate: no secrets are injected and --no-interpolate keeps
    # every ${VAR} (including values from the stack .env) out of the response.
    # Saving is a separate, admin-only step that normalizes the .env file.
    local validation_output
    local valid=true
    validation_output=$(
        _compose_config_flags
        "${_CCF_ENV[@]}" $DOCKER_COMPOSE_CMD -f "$tmpfile" "${env_args[@]}" config "${_CCF_FLAGS[@]}" 2>&1
    ) || valid=false
    rm -f "$tmpfile"

    local escaped_output
    escaped_output=$(_api_json_escape "$validation_output")

    _api_success "{\"valid\": $valid, \"stack\": \"$(_api_json_escape "$stack")\", \"output\": \"$escaped_output\"}"
}

# POST /stacks/{stack}/compose — Save the stack's docker-compose.yml (policy-scanned, previous version kept)
handle_stack_compose_save() {
    local stack="$1"
    local body="$2"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"

    if ! _api_check_admin; then _api_error 403 "Admin access required"; return; fi

    if [[ ! -d "$COMPOSE_DIR/$stack" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    if ! command -v jq >/dev/null 2>&1; then
        _api_error 500 "jq is required for compose save"
        return
    fi

    local content
    content=$(printf '%s' "$body" | jq -r '.content // empty' 2>/dev/null)
    if [[ -z "$content" ]]; then
        _api_error 400 "Missing 'content' field in request body"
        return
    fi

    # Normalize ${SECRETS.KEY} → ${SECRETS_KEY} (dots invalid in compose var names)
    content=$(printf '%s' "$content" | _normalize_secrets_syntax)

    # SECURITY: Scan compose content for dangerous Docker features.
    # Use "deploy" mode for stacks deployed from trusted templates.
    local _scan_mode="strict"
    [[ -f "$COMPOSE_DIR/$stack/.dcs-trusted-templates" ]] && _scan_mode="deploy"
    if ! _api_scan_compose_security "$content" "compose save for $stack" "$_scan_mode"; then
        return
    fi

    # Validate before saving
    local tmpfile
    tmpfile=$(mktemp /tmp/dcs-compose-save-XXXXXX.yml)
    printf '%s' "$content" > "$tmpfile"

    local env_args=()
    if [[ -f "$COMPOSE_DIR/$stack/.env" ]]; then
        env_args=(--env-file "$COMPOSE_DIR/$stack/.env")
    fi

    # Inject decrypted SECRETS_* as env vars for validation
    local validation_output
    validation_output=$(
        eval "$(secrets_env_exports "$tmpfile")"
        $DOCKER_COMPOSE_CMD -f "$tmpfile" "${env_args[@]}" config 2>&1
    )
    local valid=$?
    rm -f "$tmpfile"

    if [[ $valid -ne 0 ]]; then
        local escaped_errors
        escaped_errors=$(_api_json_escape "$validation_output")
        _api_success "{\"success\": false, \"stack\": \"$(_api_json_escape "$stack")\", \"message\": \"Validation failed\", \"validated\": false, \"validation_errors\": \"$escaped_errors\"}"
        return
    fi

    # Backup original
    if [[ -f "$compose_file" ]]; then
        cp "$compose_file" "${compose_file}.bak" 2>/dev/null
        # Save version history before overwriting
        _save_compose_version "$stack"
    fi

    # Write new content (atomic: write to temp then rename to prevent corruption)
    local tmpwrite="${compose_file}.tmp.$$"
    printf '%s' "$content" > "$tmpwrite" 2>/dev/null && mv -f "$tmpwrite" "$compose_file" 2>/dev/null || {
        rm -f "$tmpwrite" 2>/dev/null
        _api_error 500 "Failed to write compose file"
        return
    }

    _api_success "$(_fleet_with_push "$stack" "{\"success\": true, \"stack\": \"$(_api_json_escape "$stack")\", \"message\": \"Compose file saved successfully\", \"validated\": true}")"
}

# _env_file_vars_json FILE — the body of GET /env and GET /stacks/{stack}/env for an existing FILE: "raw": the file, "variables":
# one entry per KEY=value line (surrounding quotes taken off) and per comment line, with its line number
_env_file_vars_json() {
    local env_file="$1"
    local raw
    raw=$(cat "$env_file" 2>/dev/null)
    local escaped_raw
    escaped_raw=$(_api_json_escape "$raw")

    local -a vars=()
    local line_num=0
    while IFS= read -r line || [[ -n "$line" ]]; do
        (( line_num++ ))
        if [[ -z "$line" ]]; then
            continue
        fi
        if [[ "$line" =~ ^[[:space:]]*# ]]; then
            vars+=("{\"key\": \"\", \"value\": \"\", \"line\": $line_num, \"comment\": \"$(_api_json_escape "$line")\"}")
            continue
        fi
        if [[ "$line" =~ ^([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]]; then
            local key="${BASH_REMATCH[1]}"
            local value="${BASH_REMATCH[2]}"
            value="${value#\"}" ; value="${value%\"}"
            value="${value#\'}" ; value="${value%\'}"
            vars+=("{\"key\": \"$(_api_json_escape "$key")\", \"value\": \"$(_api_json_escape "$value")\", \"line\": $line_num, \"comment\": \"\"}")
        fi
    done < "$env_file"

    local vars_json
    if [[ ${#vars[@]} -gt 0 ]]; then
        vars_json=$(printf '%s,' "${vars[@]}")
        vars_json="[${vars_json%,}]"
    else
        vars_json="[]"
    fi

    printf '"raw": "%s", "variables": %s' "$escaped_raw" "$vars_json"
}

# GET /stacks/{stack}/env — The stack's .env file
handle_stack_env() {
    local stack="$1"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if [[ ! -d "$COMPOSE_DIR/$stack" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    if [[ ! -f "$env_file" ]]; then
        _api_success "{\"stack\": \"$(_api_json_escape "$stack")\", \"raw\": \"\", \"variables\": []}"
        return
    fi

    _api_success "{\"stack\": \"$(_api_json_escape "$stack")\", $(_env_file_vars_json "$env_file")}"
}

# POST /stacks/{stack}/env — Save the stack's .env file
handle_stack_env_save() {
    local stack="$1"
    local body="$2"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if ! _api_check_admin; then _api_error 403 "Admin access required"; return; fi

    if [[ ! -d "$COMPOSE_DIR/$stack" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    if ! command -v jq >/dev/null 2>&1; then
        _api_error 500 "jq is required for env save"
        return
    fi

    local content
    # an empty file is a file: only a body without content is refused
    jq -e 'has("content")' <<< "$body" >/dev/null 2>&1 || { _api_error 400 "Missing 'content' field in request body"; return; }
    content=$(printf '%s' "$body" | jq -r '.content // ""' 2>/dev/null)

    # Backup existing
    if [[ -f "$env_file" ]]; then
        cp "$env_file" "${env_file}.bak" 2>/dev/null
    fi

    printf '%s' "$content" > "$env_file" 2>/dev/null || {
        _api_error 500 "Failed to write .env file"
        return
    }

    _api_success "$(_fleet_with_push "$stack" "{\"success\": true, \"stack\": \"$(_api_json_escape "$stack")\", \"message\": \"Stack .env file saved successfully\"}")"
}

# POST /stacks/{stack}/start — Start, stop, restart or update (pull + recreate) a stack
handle_stack_action() {
    local stack="$1"
    local action="$2"
    local compose_file="$COMPOSE_DIR/$stack/docker-compose.yml"
    local env_file="$COMPOSE_DIR/$stack/.env"

    if [[ ! -f "$compose_file" ]]; then
        _api_error 404 "Stack not found: $stack"
        return
    fi

    local -a compose_args=(-f "$compose_file")
    [[ -f "$env_file" ]] && compose_args+=(--env-file "$env_file")

    local output=""
    local success=true
    local _hook_ctx="{\"stack\":\"$stack\",\"action\":\"$action\"}"

    # A referenced secret that does not exist would start the service with an
    # empty value; refuse up front and name what is missing. Names the platform
    # generates itself are created first (secrets_ensure_generated).
    if [[ "$action" != "stop" ]]; then
        local _missing
        secrets_ensure_generated "$compose_file" "$env_file" "$BASE_DIR/.env"
        _missing=$(secrets_missing "$compose_file" "$env_file" "$BASE_DIR/.env" | tr '\n' ' ')
        if [[ -n "${_missing// /}" ]]; then
            _api_error 422 "Stack $stack references secrets that do not exist: ${_missing% }. Create them on the Secrets page first."
            return
        fi
    fi

    # App-Data on a drive of its own that is not there: nothing is taken down or started (a restart would remove the
    # containers and then be refused by Compose); the reason goes back to the caller
    if [[ "$action" != "stop" ]]; then
        local _adm; _adm=$(_stack_appdata_missing "$stack") || _adm=""
        if [[ -n "$_adm" ]]; then
            _api_error 409 "$_adm"
            return
        fi
    fi

    case "$action" in
        start|stop|restart)
            # Hooks and notifications run in order with a success flag inside
            # the detached job (see _stack_run_detached)
            _stack_run_detached "$action" "$stack"
            case "$action" in
                start)   output="Starting $stack (background)" ;;
                stop)    output="Stopping $stack (background)" ;;
                restart) output="Restarting $stack (background)" ;;
            esac
            ;;
        update)
            _run_plugin_hooks "pre-update" "$(_hook_ctx "$stack" "$_hook_ctx")" sync
            # Record pre-update IDs
            local -A pre_ids=()
            while IFS= read -r img; do
                [[ -z "$img" ]] && continue
                local cid
                cid=$(docker image inspect --format='{{.Id}}' "$img" 2>/dev/null)
                [[ -n "$cid" ]] && pre_ids["$img"]="$cid"
            done < <(compose_with_secrets "$compose_file" "$env_file" config 2>/dev/null | grep 'image:' | awk '{print $2}' | sort -u)

            # Pull
            output=$(compose_with_secrets "$compose_file" "$env_file" pull 2>&1) || success=false

            # Compare
            local changes_found=false
            local -a changes=()
            for img in "${!pre_ids[@]}"; do
                local new_id
                new_id=$(docker image inspect --format='{{.Id}}' "$img" 2>/dev/null)
                if [[ "${pre_ids[$img]}" != "$new_id" ]]; then
                    changes_found=true
                    changes+=("$img")
                fi
            done

            if [[ "$changes_found" == "true" ]] && [[ "$success" == "true" ]]; then
                output+=$'\n'
                output+=$(compose_with_secrets "$compose_file" "$env_file" up -d --remove-orphans 2>&1) || success=false
            fi

            local changes_json
            changes_json=$(printf '"%s",' "${changes[@]}")
            changes_json="[${changes_json%,}]"

            _run_plugin_hooks "post-update" "$(_hook_ctx "$stack" "{\"action\":\"update\",\"changed_images\":$changes_json}" "$success")"
            local escaped_output
            escaped_output=$(_api_json_escape "$output")
            _audit_log "stack_update" "Updated $stack: $([[ "$changes_found" == "true" ]] && echo "images changed" || echo "already current")$([[ "$success" == "true" ]] || echo " (with errors)")" 2>/dev/null
            _api_success "{\"stack\": \"$stack\", \"action\": \"update\", \"success\": $success, \"changes_detected\": $changes_found, \"changed_images\": $changes_json, \"output\": \"$escaped_output\"}"
            return
            ;;
    esac

    local escaped_output
    escaped_output=$(_api_json_escape "$output")
    _api_success "{\"stack\": \"$stack\", \"action\": \"$action\", \"success\": $success, \"output\": \"$escaped_output\"}"
}

# GET /images — Images with age, size and staleness (/images/stale lists only stale ones) On a hub, ?fleet=1 adds every member's images (member, member_name, vmid) and per-member counts
handle_images() {
    local stale_only="${1:-false}"

    # Load registry cache for staleness override
    local _ic="$BASE_DIR/.data/image-update-cache.json"
    local -A _ic_cache=()
    if [[ -f "$_ic" ]]; then
        while IFS='=' read -r k v; do
            [[ -n "$k" ]] && _ic_cache["$k"]="$v"
        done < <(jq -r 'to_entries[] | "\(.key)=\(.value)"' "$_ic" 2>/dev/null)
    fi

    local -a entries=()
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        IFS='|' read -r repo tag id created size <<< "$line"

        local age_days=-1
        local staleness="unknown"
        if [[ -n "$created" ]] && [[ "$created" != "<none>" ]]; then
            local created_clean="${created% [A-Z]*}"
            local img_epoch
            img_epoch=$(date -d "$created_clean" '+%s' 2>/dev/null || date -d "$created" '+%s' 2>/dev/null || echo 0)
            if [[ "$img_epoch" -gt 0 ]]; then
                local now_epoch
                now_epoch=$(date '+%s')
                age_days=$(( (now_epoch - img_epoch) / 86400 ))
                if [[ $age_days -lt 7 ]]; then staleness="current"
                elif [[ $age_days -lt 30 ]]; then staleness="aging"
                else staleness="stale"
                fi
            fi
        fi

        # Override with registry cache — confirmed latest = current, confirmed update = stale
        local full_image="${repo}:${tag}"
        local update_available="null"
        if [[ "${_ic_cache[$full_image]:-}" == "false" ]]; then
            staleness="current"
            update_available="false"
        elif [[ "${_ic_cache[$full_image]:-}" == "true" ]]; then
            staleness="stale"
            update_available="true"
        fi

        if [[ "$stale_only" == "true" ]] && [[ "$staleness" != "stale" ]]; then
            continue
        fi

        entries+=("{\"repository\": \"$(_api_json_escape "$repo")\", \"tag\": \"$(_api_json_escape "$tag")\", \"id\": \"$(_api_json_escape "$id")\", \"created\": \"$(_api_json_escape "$created")\", \"size\": \"$(_api_json_escape "$size")\", \"age_days\": $age_days, \"staleness\": \"$staleness\", \"update_available\": $update_available}")
    done < <(docker images --format '{{.Repository}}|{{.Tag}}|{{.ID}}|{{.CreatedAt}}|{{.Size}}' 2>/dev/null)

    local json
    json=$(printf '%s,' "${entries[@]}")
    json="[${json%,}]"

    _api_success "{\"total\": ${#entries[@]}, \"images\": $json}"
}

# The jq program that turns `docker ps` rows into the container list (a variable so the tests can feed it rows).
# health: "unhealthy" is looked for first (its text contains "healthy"); uptime: "Up 3 hours" counts from the start, RunningFor from the creation.
_CONTAINERS_JQ='
            ($stats[0] // {}) as $st |
            [.[] | {
                name: .Names,
                state: .State,
                health: (if .Status | test("unhealthy") then "unhealthy"
                         elif .Status | test("healthy") then "healthy"
                         elif .Status | test("health:") then "starting"
                         else "none" end),
                image: .Image,
                image_id: (.ID[:12] // ""),
                created: .CreatedAt,
                uptime_seconds: (if .State != "running" then 0
                    else (((.Status // "") | if startswith("Up ") then sub("^Up "; "") else null end) // .RunningFor // "") as $rf
                        | ($rf
                        # "About an hour ago" / "About a minute ago" carry no digit: a
                        # missing match must not empty the whole entry out of the list
                        | ([$rf | match("[0-9]+").string | tonumber] | .[0]) as $n
                        | (if ($rf | test("About a")) then 1 elif $n == null then 0 else $n end) * (
                            if ($rf | test("second")) then 1
                            elif ($rf | test("minute")) then 60
                            elif ($rf | test("hour")) then 3600
                            elif ($rf | test("day")) then 86400
                            elif ($rf | test("week")) then 604800
                            elif ($rf | test("month")) then 2592000
                            elif ($rf | test("year")) then 31536000
                            else 0 end)) end),
                ports: .Ports,
                restart_count: 0,
                on_demand: ($sab[.Names] // false),
                sablier_up: (if ($sab[.Names] // false) then $sabup else null end),
                stack: ((.Labels // "") | split(",") | map(select(startswith("com.docker.compose.project="))) | .[0] // "" | sub("^com.docker.compose.project="; "")),
                cpu_percent: ($st[.Names].cpu // null),
                mem_percent: ($st[.Names].mem // null)
            }]'
# GET /containers — All containers with state, health, ports and cached CPU/memory usage
handle_containers() {
    # PERFORMANCE: Single docker command to get all container data as JSON
    # Then use jq to transform — fast, reliable, no delimiter issues
    local raw_json
    raw_json=$(timeout 10 docker ps -a --format '{{json .}}' 2>/dev/null)

    if [[ -z "$raw_json" ]]; then
        _fleet_containers_respond '[]'
        return
    fi

    if command -v jq >/dev/null 2>&1; then
        local now_epoch
        now_epoch=$(date +%s)

        # Stats cache — refreshed in background each call, read via jq --slurpfile
        local _stats_cache="$BASE_DIR/.data/container-stats-cache.json"
        [[ ! -f "$_stats_cache" ]] && echo '{}' > "$_stats_cache"

        # Refresh in the background for the next request, at most every 15 s
        # (docker stats walks every container's cgroups: not free)
        local _stats_age=99999
        [[ -f "$_stats_cache" ]] && _stats_age=$(( $(date +%s) - $(stat -c %Y "$_stats_cache" 2>/dev/null || echo 0) ))
        if (( _stats_age >= 15 )); then
        touch "$_stats_cache" 2>/dev/null
        (
            mkdir -p "$BASE_DIR/.data" 2>/dev/null
            local _sl
            _sl=$(docker stats --no-stream --format '{{.Name}}|{{.CPUPerc}}|{{.MemPerc}}' 2>/dev/null | awk -F'|' '{
                gsub(/%/, "", $2); gsub(/%/, "", $3); gsub(/^ +| +$/, "", $1); gsub(/^ +| +$/, "", $2); gsub(/^ +| +$/, "", $3)
                if (NR > 1) printf ","
                printf "\"%s\":{\"cpu\":%s,\"mem\":%s}", $1, ($2+0), ($3+0)
            }')
            [[ -n "$_sl" ]] && printf '{%s}' "$_sl" > "$_stats_cache"
        ) </dev/null >/dev/null 2>&1 &
        fi

        # Build containers JSON — read stats cache via --slurpfile (avoids shell arg size limits)
        local containers_json
        local _sab_json _sab_up=null; _sab_json=$(_sablier_names_json)
        [[ "$_sab_json" != '{}' ]] && { _sablier_up && _sab_up=true || _sab_up=false; }
        containers_json=$(printf '%s\n' "$raw_json" | jq -s --argjson now "$now_epoch" --argjson sab "$_sab_json" --argjson sabup "$_sab_up" --slurpfile stats "$_stats_cache" "$_CONTAINERS_JQ" 2>/dev/null)

        if [[ -n "$containers_json" ]]; then
            local total
            total=$(printf '%s' "$containers_json" | jq 'length' 2>/dev/null)
            _fleet_containers_respond "$containers_json"
            return
        fi
    fi

    # Fallback: per-container inspect (slower but always works)
    local -a entries=()
    while IFS= read -r cid; do
        [[ -z "$cid" ]] && continue
        entries+=("$(_api_container_json "$cid")")
    done < <(docker ps -a -q 2>/dev/null)

    local json
    if [[ ${#entries[@]} -gt 0 ]]; then
        json=$(printf '%s,' "${entries[@]}")
        json="[${json%,}]"
    else
        json="[]"
    fi
    _fleet_containers_respond "$json"
}
# GET /containers on a hub: the local list plus every member's containers (tagged member, member_name, vmid)
_fleet_containers_respond() {
    local json="$1" remote
    [[ "$json" == \[* ]] || json='[]'
    if _fleet_has_members; then
        remote=$(_fleet_remote_containers_json); [[ "$remote" == \[* ]] || remote='[]'
        json=$(jq -c --argjson r "$remote" '. + $r' <<< "$json")
    fi
    _api_success "$(jq -nc --argjson c "$json" '{total: ($c | length), containers: $c}')"
}

# GET /containers/{container} — Container detail
handle_container_detail() {
    local name="$1"

    if ! docker inspect "$name" >/dev/null 2>&1; then
        _api_error 404 "Container not found: $name"
        return
    fi

    # Single inspect call — extract all fields via jq
    local _full_inspect
    _full_inspect=$(timeout 5 docker inspect "$name" 2>/dev/null) || {
        _api_error 500 "Failed to inspect container: $name"
        return
    }

    local now_epoch
    now_epoch=$(date +%s)

    local full_json
    local _sab_json _sab_up=null; _sab_json=$(_sablier_names_json)
    [[ "$_sab_json" != '{}' ]] && { _sablier_up && _sab_up=true || _sab_up=false; }
    full_json=$(printf '%s' "$_full_inspect" | jq -c --argjson now "$now_epoch" --argjson sab "$_sab_json" --argjson sabup "$_sab_up" '
        .[0] | {
            name: (.Name | ltrimstr("/")),
            state: .State.Status,
            health: (if .State.Health then .State.Health.Status else "none" end),
            image: .Config.Image,
            image_id: (.Image | split(":") | .[1][:12] // ""),
            created: .Created,
            uptime_seconds: (if .State.Status == "running" and .State.StartedAt != "0001-01-01T00:00:00Z" then
                (try ($now - (.State.StartedAt | split(".")[0] + "Z" | fromdateiso8601)) catch 0) else 0 end),
            ports: ([.NetworkSettings.Ports | to_entries[] |
                select(.value != null) | .value[] |
                (if .HostIp == "" or .HostIp == "0.0.0.0" then "0.0.0.0" else .HostIp end) +
                ":" + .HostPort + "->" + (.key // "")] | join(", ")),
            restart_count: (.RestartCount // 0),
            environment: ([.Config.Env // [] | .[] | .] | join("\n")),
            mounts: ([.Mounts // [] | .[] | .Source + ":" + .Destination + (if .Mode != "" then ":" + .Mode else "" end)] | join("\n")),
            networks: ([.NetworkSettings.Networks // {} | keys[] | .] | join("\n")),
            ip_addresses: ([.NetworkSettings.Networks // {} | to_entries[] | .key + "=" + .value.IPAddress] | join("\n")),
            platform: (.Platform // "linux"),
            hostname: .Config.Hostname,
            working_dir: .Config.WorkingDir,
            restart_policy: .HostConfig.RestartPolicy.Name,
            compose_project: (.Config.Labels["com.docker.compose.project"] // ""),
            on_demand: ($sab[(.Name | ltrimstr("/"))] // false),
            sablier_up: (if ($sab[(.Name | ltrimstr("/"))] // false) then $sabup else null end),
            compose_service: (.Config.Labels["com.docker.compose.service"] // ""),
            compose_dir: (.Config.Labels["com.docker.compose.project.working_dir"] // "")
        }' 2>/dev/null)

    [[ -z "$full_json" ]] && { _api_error 500 "Failed to parse container data"; return; }

    _api_success "$full_json"
}

# GET /containers/{container}/stats — Live CPU, memory, network and block I/O of a container
handle_container_stats() {
    local name="$1"

    if ! docker inspect "$name" >/dev/null 2>&1; then
        _api_error 404 "Container not found: $name"
        return
    fi

    local stats_line
    stats_line=$(docker stats --no-stream --format '{{.CPUPerc}}|{{.MemUsage}}|{{.MemPerc}}|{{.NetIO}}|{{.BlockIO}}|{{.PIDs}}' "$name" 2>/dev/null)

    IFS='|' read -r cpu mem_usage mem_perc net_io block_io pids <<< "$stats_line"

    # Strip % signs and whitespace for numeric fields
    cpu="${cpu%%%*}"; cpu="${cpu// /}"
    mem_perc="${mem_perc%%%*}"; mem_perc="${mem_perc// /}"
    pids="${pids// /}"
    # Default to 0 if empty or --
    [[ -z "$cpu" || "$cpu" == "--" ]] && cpu="0"
    [[ -z "$mem_perc" || "$mem_perc" == "--" ]] && mem_perc="0"
    [[ -z "$pids" || "$pids" == "--" ]] && pids="0"

    _api_success "{\"container\": \"$(_api_json_escape "$name")\", \"cpu_percent\": $cpu, \"memory_usage\": \"$(_api_json_escape "$mem_usage")\", \"memory_percent\": $mem_perc, \"network_io\": \"$(_api_json_escape "$net_io")\", \"block_io\": \"$(_api_json_escape "$block_io")\", \"pids\": $pids}"
}

# GET /containers/{container}/processes — Process list inside a container
handle_container_processes() {
    local name="$1"

    if ! docker inspect "$name" >/dev/null 2>&1; then
        _api_error 404 "Container not found: $name"
        return
    fi

    # Verify the container is running (docker top requires a running container)
    local state
    state=$(docker inspect --format='{{.State.Status}}' "$name" 2>/dev/null)
    if [[ "$state" != "running" ]]; then
        _api_error 400 "Container is not running: $name (state: $state)"
        return
    fi

    local top_output
    top_output=$(docker top "$name" -eo uid,pid,ppid,%cpu,time,cmd 2>&1) || {
        _api_error 500 "Failed to get processes: $(_api_json_escape "$top_output")"
        return
    }

    local -a entries=()
    local header_skipped=false
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        # Skip the header line
        if [[ "$header_skipped" == "false" ]]; then
            header_skipped=true
            continue
        fi

        # Parse columns: UID PID PPID %CPU TIME CMD (CMD may contain spaces)
        local uid pid ppid cpu time cmd
        read -r uid pid ppid cpu time cmd <<< "$line"

        entries+=("{\"uid\": \"$(_api_json_escape "$uid")\", \"pid\": \"$(_api_json_escape "$pid")\", \"ppid\": \"$(_api_json_escape "$ppid")\", \"cpu\": \"$(_api_json_escape "$cpu")\", \"time\": \"$(_api_json_escape "$time")\", \"cmd\": \"$(_api_json_escape "$cmd")\"}")
    done <<< "$top_output"

    local json
    json=$(printf '%s,' "${entries[@]}")
    json="[${json%,}]"

    _api_success "{\"container\": \"$(_api_json_escape "$name")\", \"processes\": $json}"
}

# GET /config — Effective configuration (secrets masked)
handle_config() {
    # Return full configuration — sensitive values (tokens, certs) excluded
    local config="{"
    # General
    config+="\"environment\": \"${ENVIRONMENT:-production}\","
    config+="\"update_channel\": \"$(_api_update_channel)\","
    config+="\"update_on_boot\": $([[ "${UPDATE_ON_BOOT:-false}" == "true" ]] && echo true || echo false),"
    config+="\"force_color\": $([[ "${FORCE_COLOR:-false}" == "true" || "${FORCE_COLOR:-0}" == "1" ]] && echo true || echo false),"
    config+="\"progress_bar_width\": $(_api_int_or "${PROGRESS_BAR_WIDTH:-}" 50),"
    config+="\"update_auto_rollback\": $([[ "${UPDATE_AUTO_ROLLBACK:-true}" == "false" ]] && echo false || echo true),"
    config+="\"update_health_grace\": $(_api_int_or "${UPDATE_HEALTH_GRACE:-}" 120),"
    config+="\"update_rollback_drop\": $(_api_int_or "${UPDATE_ROLLBACK_DROP:-}" 15),"
