                            _hm_ro_name=$(jq -r '.title // .name // empty' "$tdir/template.json" 2>/dev/null)
                            [[ -z "$_hm_ro_name" ]] && _hm_ro_name="$name"
                            _hm_ro_icon=$(_get_template_icon "$name")
