                            local _host_sub
                            _host_sub=$(sed -n 's/.*Host(`\([^.]*\).*/\1/p' "$_route_file" 2>/dev/null | head -1)
                            [[ -n "$_host_sub" ]] && _dns_sub="$_host_sub"
                        fi
