import sys, re
content = sys.stdin.read()
# Find the service block
pattern = r'^  ${_svc_name}:.*?(?=^  [a-zA-Z]|\Z)'
match = re.search(pattern, content, re.MULTILINE | re.DOTALL)
if match and 'proxy' in match.group():
