import sys
lines = sys.stdin.read().split('\n')
result = []
in_svc = False
svc_name = '  ${_svc_name}:'
injected = False
for i, line in enumerate(lines):
    if line.startswith(svc_name):
        in_svc = True
        result.append(line)
