        printf '[%s] INFRA-DNS: name=%s domain=%s token=%s\n' \
            "$(date -Iseconds)" "$name" "$traefik_domain" "$([[ -n "$_infra_cf_token" ]] && echo present || echo absent)" \
            >> "$BASE_DIR/.api-auth/cf-dns-audit.log" 2>/dev/null

        if [[ -n "$_infra_cf_token" ]]; then
