            _sab_out=$(handle_template_deploy sablier "$(jq -nc --arg s "$target_stack" --argjson r "$([[ "$replace_services" == "true" ]] && echo true || echo false)" '{target_stack: $s, auto_start: false, replace_services: $r}')" 2>/dev/null)
