                ;;
            *)
                _api_error 404 "Endpoint not found: $path"
                ;;
        esac
        return
    fi

    # ── Route: POST endpoints ─────────────────────────────────────────
    if [[ "$method" == "POST" ]]; then

        # Auth endpoints that do NOT require authentication
        case "$path" in
            /auth/setup)          handle_auth_setup "$request_body"; return ;;
            /auth/login)          handle_auth_login "$request_body"; return ;;
            /auth/register)       handle_auth_register "$request_body"; return ;;
            /auth/totp/validate)  handle_totp_validate "$request_body"; return ;;
            /setup/restore)       handle_setup_restore "$request_body"; return ;;
            /fleet/join)          handle_fleet_join "$request_body"; return ;;
            /fleet/relay)         handle_fleet_relay "$request_body"; return ;;
        esac

        # All other POST endpoints require authentication
        if ! _api_check_auth; then
            _api_error 401 "${AUTH_ERROR:-Authentication required. Provide Authorization: Bearer <token> header.}"
            return
        fi
        if ! _api_route_allowed "$method" "$path"; then
            _api_error 403 "Admin access required"
            return
        fi

        # SECURITY: Audit log ALL authenticated POST requests (write operations). The chat is the exception: a message
        # is not an operation on the server (its handlers audit what an admin removes), and no shared answer depends on it
        if [[ "$path" != /chat/* ]]; then
            _api_audit_log "$client_ip" "POST" "${AUTH_USERNAME:-unknown}" "$path"
            _api_cache_clear
        fi
        # A stack, container or template deploy that belongs to a member VM is answered by that VM
        _fleet_forward_if_remote "$method" "$path" "$request_body" && return

        # Setup wizard endpoints (require auth + setup not complete)
        case "$path" in
            /setup/configure) handle_setup_configure "$request_body"; return ;;
            /setup/complete)  handle_setup_complete; return ;;
        esac

        # Auth session management endpoints (any authenticated user)
        case "$path" in
            /auth/logout)        handle_auth_logout; return ;;
            /auth/refresh)       handle_auth_refresh; return ;;
            /auth/totp/setup)    handle_totp_setup "$request_body"; return ;;
            /auth/totp/verify)   handle_totp_verify "$request_body"; return ;;
            /auth/totp/disable)  handle_totp_disable "$request_body"; return ;;
        esac

        # Auth endpoints that require admin
        case "$path" in
            /auth/invite)         handle_auth_invite "$request_body"; return ;;
            /auth/users)          handle_auth_users_create "$request_body"; return ;;
            /auth/keys)           handle_auth_keys_create "$request_body"; return ;;
            /ssh/keys)            handle_ssh_key_create "$request_body"; return ;;
            /ssh/keys/*/vms)      local _sk="${path#/ssh/keys/}"; handle_ssh_key_vms "${_sk%/vms}" "$request_body"; return ;;
            /auth/users/*/role)   local _ru="${path#/auth/users/}"; handle_auth_user_role "${_ru%/role}" "$request_body"; return ;;
            /proxmox/test)        handle_proxmox_test "$request_body"; return ;;
            /proxmox/vms/*/snapshots)
                local _ps="${path#/proxmox/vms/}"; _ps="${_ps%/snapshots}"
                [[ "$_ps" =~ ^[0-9]{1,9}$ ]] || { _api_error 400 "Invalid VMID"; return; }
                handle_proxmox_snapshot_create "$_ps" "$request_body"; return ;;
            /proxmox/vms/*/snapshots/*/rollback)
                local _ps="${path#/proxmox/vms/}" _ps_id _ps_name
                _ps_id="${_ps%%/*}"; _ps_name="${_ps#*/snapshots/}"; _ps_name="${_ps_name%/rollback}"
                [[ "$_ps_id" =~ ^[0-9]{1,9}$ ]] || { _api_error 400 "Invalid VMID"; return; }
                handle_proxmox_snapshot_rollback "$_ps_id" "$_ps_name" "$request_body"; return ;;
            /proxmox/vms/*/*/*/*)
                local _pv="${path#/proxmox/vms/}" _pv_node _pv_type _pv_id _pv_action
                _pv_node="${_pv%%/*}"; _pv="${_pv#*/}"; _pv_type="${_pv%%/*}"; _pv="${_pv#*/}"; _pv_id="${_pv%%/*}"; _pv_action="${_pv#*/}"
