                _api_validate_resource_name "$key" "secret" || return
                # Merge URL key into body for the handler
                local _sb
                _sb=$(printf '%s' "$request_body" | jq -c --arg k "$key" '. + {key: $k}' 2>/dev/null)
                [[ -n "$_sb" ]] && request_body="$_sb"
                handle_secret_set "$request_body"
                ;;
            /schedules)
                handle_schedule_create "$request_body"
                ;;
            /plugins/install)
                handle_plugin_install "$request_body"
                ;;
            /plugins/scaffold)
                handle_plugin_scaffold "$request_body"
                ;;
            /rollback/*/restore)
                local stack="${path#/rollback/}"
                stack="${stack%/restore}"
                _api_validate_stack_name "$stack" || return
                handle_rollback_restore "$stack" "$request_body"
                ;;
            /schedules/*/update)
                local sched_id="${path#/schedules/}"
                sched_id="${sched_id%/update}"
                _api_validate_resource_name "$sched_id" "schedule" || return
                handle_schedule_update "$sched_id" "$request_body"
                ;;
            /schedules/*/toggle)
                local sched_id="${path#/schedules/}"
                sched_id="${sched_id%/toggle}"
                _api_validate_resource_name "$sched_id" "schedule" || return
                handle_schedule_toggle "$sched_id"
                ;;
            /schedules/*/run)
                local sched_id="${path#/schedules/}"
                sched_id="${sched_id%/run}"
                _api_validate_resource_name "$sched_id" "schedule" || return
                handle_schedule_run "$sched_id"
                ;;
            /plugins/catalog/*/install)
                local _cat="${path#/plugins/catalog/}"
                _cat="${_cat%/install}"
                _api_validate_resource_name "$_cat" "plugin" || return
                handle_plugin_catalog_install "$_cat"
                ;;
            /plugins/*/cards/*)
                local pname="${path#/plugins/}"
                local cname="${pname#*/cards/}"
                pname="${pname%%/*}"
                cname="${cname%%/*}"
                _api_validate_resource_name "$pname" "plugin" || return
                _api_validate_resource_name "$cname" "card" || return
                handle_plugin_card_save "$pname" "$cname" "$request_body"
                ;;
            /plugins/*/toggle)
                local pname="${path#/plugins/}"
                pname="${pname%/toggle}"
                _api_validate_resource_name "$pname" "plugin" || return
                handle_plugin_toggle "$pname"
                ;;
            /plugins/*/hooks/*/test)
                local pname="${path#/plugins/}"
                local rest="${pname#*/hooks/}"
                local hook_name="${rest%/test}"
                pname="${pname%%/*}"
                _api_validate_resource_name "$pname" "plugin" || return
                _api_validate_resource_name "$hook_name" "hook" || return
                handle_plugin_hook_test "$pname" "$hook_name" "$request_body"
                ;;
            /plugins/*/hooks/*/update)
                local pname="${path#/plugins/}"
                local rest="${pname#*/hooks/}"
                local hook_name="${rest%/update}"
                pname="${pname%%/*}"
                _api_validate_resource_name "$pname" "plugin" || return
                _api_validate_resource_name "$hook_name" "hook" || return
                handle_plugin_hook_update "$pname" "$hook_name" "$request_body"
                ;;
            /plugins/*/config)
                local pname="${path#/plugins/}"
                pname="${pname%/config}"
                _api_validate_resource_name "$pname" "plugin" || return
                handle_plugin_config_update "$pname" "$request_body"
                ;;
            *)
                _api_error 404 "Endpoint not found: $path"
                ;;
        esac
        return
    fi

    # ── Route: PUT endpoints ──────────────────────────────────────────
    if [[ "$method" == "PUT" || "$method" == "PATCH" ]]; then

        # All PUT/PATCH endpoints require authentication
        if ! _api_check_auth; then
            _api_error 401 "${AUTH_ERROR:-Authentication required. Provide Authorization: Bearer <token> header.}"
            return
        fi
        if ! _api_route_allowed "$method" "$path"; then
            _api_error 403 "Admin access required"
            return
        fi

        # SECURITY: Audit log ALL PUT/PATCH requests (the chat's edits excepted, as for POST)
        if [[ "$path" != /chat/* ]]; then
            _api_audit_log "$client_ip" "PUT" "${AUTH_USERNAME:-unknown}" "$path"
            _api_cache_clear
        fi
        _fleet_forward_if_remote "$method" "$path" "$request_body" && return

        case "$path" in
            /themes/active) handle_theme_active_set "$request_body"; return ;;
            /chat/messages/*) _chat_lib; handle_chat_edit "${path#/chat/messages/}" "$request_body"; return ;;
            /crowdsec/settings) _crowdsec_cfg_lib; handle_crowdsec_settings_set "$request_body"; return ;;
            /crowdsec/notifications) _crowdsec_cfg_lib; handle_crowdsec_notify_set "$request_body"; return ;;
            /crowdsec/notifications/digest) _crowdsec_cfg_lib; handle_crowdsec_digest_set "$request_body"; return ;;
            /crowdsec/plugin) _crowdsec_cfg_lib; handle_crowdsec_plugin_set "$request_body"; return ;;
            /fleet/members/*/api/*)
                local _fm="${path#/fleet/members/}" _fm_id _fm_inner
                _fm_id="${_fm%%/*}"; _fm_inner="${_fm#*/api}"
                [[ "$_fm_id" =~ ^[a-z0-9-]{1,40}$ ]] || { _api_error 400 "Invalid member id"; return; }
                handle_fleet_proxy "$_fm_id" "$_fm_inner" "$request_body"
                ;;
            /fleet/members/*)
                local _fm_id="${path#/fleet/members/}"
                [[ "$_fm_id" =~ ^[a-z0-9-]{1,40}$ ]] || { _api_error 400 "Invalid member id"; return; }
                handle_fleet_member_update "$_fm_id" "$request_body"
                ;;
            /dns/records/*)
                local _rec_id="${path#/dns/records/}"
                handle_dns_record_update "$_rec_id" "$request_body"
                ;;
            /routes/*/*)
                local _route_parts="${path#/routes/}"
                local _route_stack="${_route_parts%%/*}"
                local _route_svc="${_route_parts#*/}"
                handle_route_update "$_route_stack" "$_route_svc" "$request_body"
                ;;
            *)
                _api_error 404 "Endpoint not found: $path"
                ;;
        esac
        return
    fi

    # ── Route: DELETE endpoints ────────────────────────────────────────
    if [[ "$method" == "DELETE" ]]; then

        # All DELETE endpoints require authentication
        if ! _api_check_auth; then
            _api_error 401 "${AUTH_ERROR:-Authentication required. Provide Authorization: Bearer <token> header.}"
            return
        fi
        if ! _api_route_allowed "$method" "$path"; then
            _api_error 403 "Admin access required"
            return
        fi

        # SECURITY: Audit log ALL DELETE requests (the chat's deletions excepted, as for POST: the handlers audit an
        # admin's removal of someone else's message and clearing the room)
        if [[ "$path" != /chat/* ]]; then
            _api_audit_log "$client_ip" "DELETE" "${AUTH_USERNAME:-unknown}" "$path"
            _api_cache_clear
        fi
        _fleet_forward_if_remote "$method" "$path" "$request_body" && return

        case "$path" in
            /themes/*) handle_theme_delete "${path#/themes/}"; return ;;
            /chat/messages) _chat_lib; handle_chat_clear; return ;;
            /chat/messages/*) _chat_lib; handle_chat_delete "${path#/chat/messages/}"; return ;;
            /homarr/key) handle_homarr_key_delete; return ;;
            /feed/token) handle_feed_token_delete; return ;;
            /fleet/members/*/api/*)
                local _fm="${path#/fleet/members/}" _fm_id _fm_inner
                _fm_id="${_fm%%/*}"; _fm_inner="${_fm#*/api}"
                [[ "$_fm_id" =~ ^[a-z0-9-]{1,40}$ ]] || { _api_error 400 "Invalid member id"; return; }
                handle_fleet_proxy "$_fm_id" "$_fm_inner" "$request_body"
                ;;
            /fleet/members/*/folders/*)
                local _fm="${path#/fleet/members/}" _fm_id _ff
                _fm_id="${_fm%%/*}"; _ff="${_fm#*/folders/}"
                [[ "$_fm_id" =~ ^[a-z0-9-]{1,40}$ && "$_ff" != */* ]] || { _api_error 400 "Invalid member or folder"; return; }
                handle_fleet_member_folder_remove "$_fm_id" "$_ff"
                ;;
            /domains/*)
                local _dm="${path#/domains/}"
                _domain_valid "$_dm" || { _api_error 400 "Invalid domain"; return; }
                handle_domains_remove "$_dm"
                ;;
            /fleet/members/*)
                local _fm_id="${path#/fleet/members/}"
                [[ "$_fm_id" =~ ^[a-z0-9-]{1,40}$ ]] || { _api_error 400 "Invalid member id"; return; }
                handle_fleet_member_delete "$_fm_id"
                ;;
            /fleet/templates/*)
                local _ft="${path#/fleet/templates/}"
                [[ "$_ft" =~ ^[0-9]{1,9}$ ]] || { _api_error 400 "Invalid template vmid"; return; }
                handle_fleet_template_delete "$_ft"
                ;;
            /proxmox/vms/*/snapshots/*)
                local _ps="${path#/proxmox/vms/}" _ps_id _ps_name
                _ps_id="${_ps%%/*}"; _ps_name="${_ps#*/snapshots/}"
                [[ "$_ps_id" =~ ^[0-9]{1,9}$ ]] || { _api_error 400 "Invalid VMID"; return; }
                handle_proxmox_snapshot_delete "$_ps_id" "$_ps_name"
                ;;
            /fleet/jobs/*)
                local _fj="${path#/fleet/jobs/}"
                [[ "$_fj" =~ ^[A-Za-z0-9._-]{1,80}$ ]] || { _api_error 400 "Invalid job id"; return; }
                handle_fleet_job_delete "$_fj"
                ;;
            /fleet/join-tokens/*)
                local _jt="${path#/fleet/join-tokens/}"
                [[ "$_jt" =~ ^[A-Za-z0-9-]{1,40}$ ]] || { _api_error 400 "Invalid join code"; return; }
                handle_fleet_join_token_delete "$_jt"
                ;;
            /fleet/hub)
                handle_fleet_leave_hub
                ;;
            /auth/sessions/*)
                local token_prefix="${path#/auth/sessions/}"
                handle_auth_session_revoke "$token_prefix"
                ;;
            /auth/invite/*)
                local code="${path#/auth/invite/}"
                handle_auth_delete_invite "$code"
                ;;
            /auth/keys/*)
                handle_auth_keys_delete "${path#/auth/keys/}"
                ;;
            /ssh/keys/*)
                handle_ssh_key_delete "${path#/ssh/keys/}"
                ;;
            /notifications/rules/*)
                local rule_id="${path#/notifications/rules/}"
                _api_validate_resource_name "$rule_id" "notification rule" || return
                handle_notification_rules_delete "$rule_id"
                ;;
            /snapshots/*)
                local snap="${path#/snapshots/}"
                _api_validate_resource_name "$snap" "snapshot" || return
                handle_snapshot_delete "$snap"
                ;;
            /webhooks/*)
                local wid="${path#/webhooks/}"
                handle_webhook_delete "$wid"
                ;;
            /templates/*)
                local tname="${path#/templates/}"
                _api_validate_resource_name "$tname" "template" || return
                handle_template_delete "$tname"
                ;;
            /crowdsec/decisions/*)
                local _cs_ip="${path#/crowdsec/decisions/}"
                _crowdsec_lib; handle_crowdsec_unban "$_cs_ip"
                ;;
            /crowdsec/allowlist/*)
                local _cs_al="${path#/crowdsec/allowlist/}"
                _crowdsec_lib; handle_crowdsec_allowlist_remove "$_cs_al"
                ;;
            /crowdsec/bouncers/*)
                local _cs_bn="${path#/crowdsec/bouncers/}"
                _crowdsec_lib; handle_crowdsec_bouncer_delete "$_cs_bn" "$request_body"
                ;;
            /crowdsec/trust/*)
                local _cs_ip="${path#/crowdsec/trust/}"
                handle_crowdsec_untrust "$_cs_ip"
                ;;
            /automations/*)
                local auto_id="${path#/automations/}"
                _api_validate_resource_name "$auto_id" "automation" || return
                handle_automation_delete "$auto_id"
                ;;
            /secrets/*)
                local key="${path#/secrets/}"
                _api_validate_resource_name "$key" "secret" || return
                handle_secret_delete "$key"
                ;;
            /schedules/*)
                local sched_id="${path#/schedules/}"
                _api_validate_resource_name "$sched_id" "schedule" || return
                handle_schedule_delete "$sched_id"
                ;;
            /plugins/*/cards/*)
                local pname="${path#/plugins/}"
                local cname="${pname#*/cards/}"
                pname="${pname%%/*}"
                cname="${cname%%/*}"
                _api_validate_resource_name "$pname" "plugin" || return
                _api_validate_resource_name "$cname" "card" || return
                handle_plugin_card_delete "$pname" "$cname"
                ;;
            /plugins/*)
                local pname="${path#/plugins/}"
                _api_validate_resource_name "$pname" "plugin" || return
                handle_plugin_remove "$pname"
                ;;
            /dns/records/*)
                local _rec_id="${path#/dns/records/}"
                handle_dns_record_delete "$_rec_id"
                ;;
            /routes/*/*)
                local _route_parts="${path#/routes/}"
                local _route_stack="${_route_parts%%/*}"
                local _route_svc="${_route_parts#*/}"
                handle_route_delete "$_route_stack" "$_route_svc"
                ;;
            *)
                _api_error 404 "Endpoint not found: $path"
                ;;
        esac
        return
    fi

    _api_error 405 "Method not allowed: $method"
}

# =============================================================================
# SERVER MAIN LOOP
# =============================================================================

# _api_log_trim FILE MAX — keeps the last MAX lines of FILE: copied, then the file truncated and written in place (its mode,
# and the descriptor of a writer appending to it, stay)
_api_log_trim() {
    local f="$1" max="$2" tmp
    [[ -f "$f" && "$max" =~ ^[0-9]+$ && "$max" -ge 1 ]] || return 0
    (( $(wc -l < "$f") > max )) || return 0
    tmp=$(mktemp "$f.trim-XXXXXX" 2>/dev/null) || return 0
    { tail -n "$max" "$f" > "$tmp" && cat "$tmp" > "$f"; } 2>/dev/null || true
    rm -f "$tmp"
}

# _api_hourly_cleanup — the listener's hourly round: stale rate-limit files and TOTP tracking; the staging folders of a
# bundle, a restore or an upload that a crash left behind (6 h old: none is still running; the ones of a recovery bundle
# hold the master key in the clear); the request and audit logs cut to their last API_LOG_MAX_LINES (50000) lines.
# (It runs in the listener's loop, under errexit: no step of it may end the loop.)
_api_hourly_cleanup() {
    local d max="${API_LOG_MAX_LINES:-50000}"
    find "${API_RATE_DIR:-$API_AUTH_DIR/rates}" -type f -mmin +1440 -delete 2>/dev/null || true
    : > "$API_AUTH_DIR/.totp-attempts" 2>/dev/null || true
    for d in "$(_recovery_dir)" "${BACKUP_DEST_DIR:-}" "$SNAPSHOTS_DIR"; do
        [[ -n "$d" && -d "$d" ]] || continue
        find "$d" -mindepth 1 -maxdepth 1 \( -name '.staging-*' -o -name '.restore-*' -o -name '.upload-*' \) -mmin +360 -exec rm -rf -- {} + 2>/dev/null || true
    done
    [[ "$max" =~ ^[0-9]+$ && "$max" -ge 1 ]] || max=50000
    for d in "$API_LOG_FILE" "$BASE_DIR/.data/audit.jsonl" "$API_AUTH_DIR/auth-audit.log"; do _api_log_trim "$d" "$max"; done
    return 0
}

start_server() {
    # Create log directory
    mkdir -p "$(dirname "$API_LOG_FILE")" 2>/dev/null
    # a VM of a fleet keeps its backups beside the install (the hub's "Back up everything" asks every VM for one); a
    # destination set by hand stays
    if [[ -z "${BACKUP_DEST_DIR:-}" ]] && _fleet_is_member; then
        local _bd; _bd="$(dirname "$BASE_DIR")/dcs-backups"
        mkdir -p "$_bd" 2>/dev/null && chmod 700 "$_bd" 2>/dev/null && _api_env_write BACKUP_DEST_DIR "$_bd" && export BACKUP_DEST_DIR="$_bd"
    fi

    # Color setup for terminal output
    local _A_RST="" _A_BOLD="" _A_DIM=""
    local _A_CYAN="" _A_BLUE="" _A_GREEN="" _A_GRAY="" _A_WHITE="" _A_MAGENTA=""

    if [[ -t 1 ]] && [[ "${TERM:-dumb}" != "dumb" ]] && command -v tput >/dev/null 2>&1; then
        _A_RST="$(tput sgr0)"
        _A_BOLD="$(tput bold)"
        _A_DIM="$(tput dim)"
        _A_CYAN="$(tput setaf 51)"
        _A_BLUE="$(tput setaf 33)"
        _A_GREEN="$(tput setaf 82)"
        _A_GRAY="$(tput setaf 245)"
        _A_WHITE="$(tput setaf 15)"
        _A_MAGENTA="$(tput setaf 141)"
    fi

    local border
    border="$(printf '%0.s═' $(seq 1 60))"

    echo ""
    echo "  ${_A_BOLD}${_A_BLUE}${border}${_A_RST}"
    echo ""
    echo "  ${_A_BOLD}${_A_CYAN}   ╔═╗╔═╗╦  ╔═╗╔═╗╦═╗╦  ╦╔═╗╦═╗${_A_RST}"
    echo "  ${_A_BOLD}${_A_CYAN}   ╠═╣╠═╝║  ╚═╗║╣ ╠╦╝╚╗╔╝║╣ ╠╦╝${_A_RST}"
    echo "  ${_A_BOLD}${_A_CYAN}   ╩ ╩╩  ╩  ╚═╝╚═╝╩╚═ ╚╝ ╚═╝╩╚═${_A_RST}"
    echo ""
    echo "  ${_A_DIM}${_A_GRAY}  DCS Orchestrator REST API${_A_RST}"
    echo ""
    echo "  ${_A_BOLD}${_A_BLUE}${border}${_A_RST}"
    echo ""
    echo "  ${_A_BOLD}${_A_WHITE}Version${_A_RST}    ${_A_CYAN}v${API_VERSION}${_A_RST}"
    echo "  ${_A_BOLD}${_A_WHITE}Listen${_A_RST}     ${_A_GREEN}${API_BIND}:${API_PORT}${_A_RST}"
    echo "  ${_A_BOLD}${_A_WHITE}Transport${_A_RST}  ${_A_MAGENTA}${LISTENER_CMD}${_A_RST}"
    echo "  ${_A_BOLD}${_A_WHITE}Auth${_A_RST}       $([[ "$API_AUTH_ENABLED" == "true" ]] && echo "${_A_GREEN}Enabled${_A_RST}" || echo "${_A_GRAY}Disabled (localhost)${_A_RST}")"
    echo "  ${_A_BOLD}${_A_WHITE}PID${_A_RST}        ${_A_GRAY}$$${_A_RST}"
    echo "  ${_A_BOLD}${_A_WHITE}Base Dir${_A_RST}   ${_A_DIM}${BASE_DIR}${_A_RST}"
    echo ""
    echo "  ${_A_DIM}${_A_GRAY}$(printf '%0.s─' $(seq 1 60))${_A_RST}"
    echo ""
    echo "  ${_A_GREEN}Endpoints${_A_RST}  ${_A_DIM}curl http://${API_BIND}:${API_PORT}/${_A_RST}"
    echo "  ${_A_GREEN}Stop${_A_RST}       ${_A_DIM}$0 --stop${_A_RST}"
    echo ""
    echo "  ${_A_BOLD}${_A_BLUE}${border}${_A_RST}"
    echo ""

    # SELinux: the entry scripts get their bin_t label back before anything can fail. An update that ran on older code
    # may have replaced api-server.sh without it, and systemd cannot start a service from a user_home_t file (203/EXEC).
    _selinux_relabel_code >/dev/null 2>&1 || true
    # A backup the API's last run did not finish (a restart under it) may have left a stack's containers paused
    _backup_pid_alive "$BACKUP_PID_FILE" || _backup_unpause_all >/dev/null 2>&1 || true
    _backup_tidy_leftovers >/dev/null 2>&1 || true
    # The dashboard image's new name (docker-compose-skeleton-ui -> dcs-orchestrator-ui) in the dashboard's compose file
    _dcs_ui_image_migrate || echo "  Dashboard image: ${_DCS_UI_MIGRATE_FILE:-the compose file of DCS-UI} still names ${_DCS_UI_OLD_REPO}: ${_DCS_UI_MIGRATE_ERR:-could not rewrite it}"

    # Refuse to start on a port something else already owns (another DCS
    # installation, an unrelated service): a bind failure inside socat would
    # only show up as a dead API from the UI's side. What the listener this one replaced left
    # behind is not "something else": that is taken back first.
    local _holders _h
    _holders=$(_api_port_listeners "$API_PORT")
    if [[ -n "$_holders" ]]; then
        _api_reclaim_port "$API_PORT" || true
        _holders=$(_api_port_listeners "$API_PORT")
    fi
    if [[ -n "$_holders" ]]; then
        for _h in $_holders; do
            echo "  ERROR: port ${API_PORT} is already in use by PID ${_h}: $(tr '\0' ' ' < "/proc/${_h}/cmdline" 2>/dev/null | cut -c1-80)" >&2
        done
        echo "         Stop that process ('$0 --stop' removes an orphaned DCS listener)," >&2
        echo "         or set API_PORT in .env to a free port, then start again." >&2
        exit 1
    elif command -v ss >/dev/null 2>&1 && [[ -n "$(ss -Hltn "sport = :${API_PORT}" 2>/dev/null)" ]]; then
        echo "  ERROR: port ${API_PORT} is already in use by another user's process." >&2
        echo "         Set API_PORT in .env to a free port, then start again." >&2
        exit 1
    fi

    # Write PID file (use $BASHPID for the actual process PID, not $$ which is always the parent)
    echo "${BASHPID:-$$}" > "$API_PID_FILE"
    echo reexec-usr1 > "$API_CAPS_FILE" 2>/dev/null || true

    if [[ "$API_AUTH_FORCED" == "true" ]]; then
        echo "  WARNING: API_AUTH_ENABLED=false was ignored because the listener is not"
        echo "           bound to loopback. Set API_INSECURE_NO_AUTH=true to override."
        echo ""
    elif [[ "$API_AUTH_ENABLED" != "true" ]] && ! _api_bind_is_loopback "$API_BIND"; then
        echo "  WARNING: authentication is DISABLED on a non-loopback address"
        echo "           (API_INSECURE_NO_AUTH=true). Anyone who can reach"
        echo "           ${API_BIND}:${API_PORT} controls this Docker host."
        echo ""
    fi

    # Graceful shutdown: stop the listener and every helper loop we started
    trap '_api_shutdown_children; rm -f "$API_PID_FILE" "$API_CAPS_FILE"; exit 0' SIGTERM SIGINT
    # POST /system/restart: re-execute in place, same PID. SIGUSR1 is the signal
    # that always works (nohup leaves SIGHUP ignored, and an ignored signal cannot
    # be trapped); SIGHUP is kept for listeners systemd started.
    trap '_api_reexec' SIGUSR1 SIGHUP

    local self_path
    self_path="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
    # API_WORKERS (.env, default 4): pre-read copies of this script that answer the requests; 0 = read the script per connection
    # unset = automatic: twice the cores, four at least and eight at most (a burst of dashboard polls is then served by the
    # pool instead of spilling over), four on a machine with less than 3 GB (a worker holds about 25 MB)
    if [[ -z "${API_WORKERS:-}" ]]; then
        API_WORKERS=$(( $(nproc 2>/dev/null || echo 2) * 2 )); (( API_WORKERS < 4 )) && API_WORKERS=4; (( API_WORKERS > 8 )) && API_WORKERS=8
        (( $(awk '/^MemTotal/ {print int($2 / 1024)}' /proc/meminfo 2>/dev/null || echo 0) < 3000 )) && API_WORKERS=4
    fi; [[ "$API_WORKERS" =~ ^[0-9]+$ && "$API_WORKERS" -le 64 ]] || API_WORKERS=4

    # Start DDNS loop (only once, in the server process — not per-request)
    if [[ "$DDNS_ENABLED" == "true" && -n "${CF_DNS_API_TOKEN:-}" && -n "${TRAEFIK_DOMAIN:-}" ]]; then
        _ddns_update_loop &
        local _ddns_pid=$!
        echo "$_ddns_pid" > "$DDNS_PID_FILE" 2>/dev/null
    fi

    # UPS watch (NUT over TCP or apcupsd): alerts and a clean stack stop on low battery
    if [[ "${UPS_ENABLED:-false}" == "true" ]]; then
        _dcs_power_loop &
        echo "$!" > "$POWER_PID_FILE" 2>/dev/null || true
        echo "  UPS watch started (${UPS_SOURCE:-auto}, every ${UPS_POLL_INTERVAL:-15}s)"
    else
        rm -f "$POWER_PID_FILE" 2>/dev/null || true
    fi

    # On-demand containers an older prune removed come back (created, not started)
    (
        sleep 30
        _sablier_repair
        [[ ${#SAB_REPAIRED[@]} -gt 0 ]] && echo "  Recreated on-demand containers: ${SAB_REPAIRED[*]}"
        [[ ${#SAB_FAILED[@]} -gt 0 ]] && echo "  On-demand containers still missing: ${SAB_FAILED[*]}"
        exit 0
    ) </dev/null &

    # Start metrics collector background loop (same pattern as DDNS loop above)
    if [[ "${METRICS_ENABLED:-true}" == "true" ]]; then
        local _m_interval="${METRICS_COLLECT_INTERVAL:-60}"
        local _m_file="$BASE_DIR/.api-auth/metrics-history.jsonl"
        _dcs_metrics_loop() {
            # sleep runs as a job so SIGTERM ends the loop immediately
            trap 'kill "${_sleep_pid:-}" 2>/dev/null; exit 0' TERM INT
            local _m_env_stamp; _m_env_stamp=$(mktemp 2>/dev/null) || _m_env_stamp=""
            while true; do
                local ts ep l1 l5 l15 nc cp mt ma mu mp dp
                # a channel, a threshold or a rule saved since the last tick counts from this one (the workers read .env per request)
                if [[ -n "$_m_env_stamp" && "$BASE_DIR/.env" -nt "$_m_env_stamp" ]]; then
                    _api_load_env_file "$BASE_DIR/.env"; touch "$_m_env_stamp" 2>/dev/null
                fi
                ts=$(_api_now_iso)
                ep=$(date +%s)
                read -r l1 l5 l15 _ _ < /proc/loadavg 2>/dev/null || { l1=0; l5=0; l15=0; }
                nc=$(nproc 2>/dev/null || echo 1)
                cp=$(awk "BEGIN {v=$l1/$nc*100; if(v>100)v=100; printf \"%.1f\", v}")
                mt=$(awk '/MemTotal/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
                ma=$(awk '/MemAvailable/ {printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 0)
                mu=$((mt - ma))
                if [[ "$mt" -gt 0 ]]; then
                    mp=$(awk "BEGIN {printf \"%.1f\", $mu/$mt*100}")
                else
                    mp=0
                fi
                dp=$(df -P "$BASE_DIR" 2>/dev/null | tail -1 | awk '{print $5}' | tr -d '%')
                [[ -z "$dp" ]] && dp=$(df -P / 2>/dev/null | tail -1 | awk '{print $5}' | tr -d '%')
                [[ -z "$dp" ]] && dp=0
                echo "{\"ts\":\"$ts\",\"epoch\":$ep,\"cpu_pct\":$cp,\"load1\":$l1,\"load5\":$l5,\"load15\":$l15,\"mem_used_mb\":$mu,\"mem_total_mb\":$mt,\"mem_pct\":$mp,\"disk_pct\":$dp}" >> "$_m_file"
                # Disk, CPU, memory and stale-image rules are checked here
                _alerts_evaluate >/dev/null 2>&1 || true
                # containers that stopped or turn unhealthy are noticed here, not only while a dashboard polls /health: the
                # health check fires (or, on a member, relays) the container events itself, each once per its cooldown
                # (not in the first minutes after a boot: the stacks are still being started then, nothing is down yet)
                if (( $(cut -d. -f1 /proc/uptime 2>/dev/null || echo 999999) > ${HEALTH_WATCH_BOOT_GRACE:-300} )) && _health_watch_wanted; then
                    ( unset 'QUERY_PARAMS[fleet]' 2>/dev/null; _api_success() { :; }; _api_error() { :; }; _api_response() { :; }; handle_health ) </dev/null >/dev/null 2>&1 || true
                fi
                # a VM with containers that start on demand runs its own Sablier (the hub's proxy asks it)
                if _fleet_is_member && [[ -n "$(_sablier_names 2>/dev/null)" ]]; then _member_sablier_ensure >/dev/null 2>&1 || true; fi
                # on-demand containers started some other way (the boot, a stack start, an update) go to sleep after their idle time
                _sablier_track_running >/dev/null 2>&1 || true
                # Proxmox VMs that stopped or started on their own
                _pve_watch >/dev/null 2>&1 || true
                # the waiting OS updates are looked at again when due (every 6 h, after packages changed, after a restart)
                _os_updates_kick >/dev/null 2>&1 || true
                # the fleet's tick (members down or back, relay tokens, the domain, the routes for every Traefik) runs in the
                # background: a member that stalls never holds up the samples
                _fleet_loop_tick >/dev/null 2>&1 || true
                # Once an hour: trim raw samples and rebuild the 5-minute and hourly tiers
                if (( ep / 3600 != ${_last_rollup_hour:--1} )); then
                    _last_rollup_hour=$(( ep / 3600 ))
                    _metrics_rollup >/dev/null 2>&1 || true
                fi
                sleep "$_m_interval" & _sleep_pid=$!
                wait "$_sleep_pid" || true
            done
        }
        _dcs_metrics_loop &
        echo "  Metrics collector started (interval: ${_m_interval}s)"
    fi

    # theme files an older DCS wrote under a plugin name this Traefik does not know (the route answered 404);
    # in the background: a broken route is probed again after Traefik reloads
    ( _theme_files_repair >/dev/null 2>&1 ) </dev/null >/dev/null 2>&1 &

    # a VM from a DCS image older than 4.0.30: kernel changes rewrite its boot menu, and Debian's full kernel can find its disk
    ( _image_boot_repair ) </dev/null &

    # A hub that updated itself with "then update the VMs": the round runs now, on the new code, in the background
    if [[ -f "$BASE_DIR/.data/fleet-update-pending" ]]; then
        rm -f "$BASE_DIR/.data/fleet-update-pending"
        if _fleet_has_members; then
            ( sleep 5; _fleet_update_round all >/dev/null 2>&1 ) </dev/null >/dev/null 2>&1 &
            echo "  Fleet update queued: the members follow to DCS $DCS_VERSION in a moment"
        fi
    fi

    # a web terminal deployed by an earlier version gets the current start script
    ( sleep 6; _web_terminal_upgrade >/dev/null 2>&1 ) </dev/null >/dev/null 2>&1 &

    # Automations and schedules run in the server process (no crontab)
    if [[ "${AUTOMATIONS_ENABLED:-true}" == "true" ]]; then
        mkdir -p "$BASE_DIR/.data" "$BASE_DIR/logs" 2>/dev/null
        # Lines installed by older versions pointed at a route that never existed
        if crontab -l 2>/dev/null | grep -q '# DCS-AUTO:'; then
            _legacy=$(crontab -l 2>/dev/null | grep -v '# DCS-AUTO:[A-Za-z0-9_]*$')
            printf '%s\n' "$_legacy" | crontab - 2>/dev/null && echo "  Removed legacy automation crontab lines"
        fi
        _dcs_automation_loop &
        echo "  Automation engine started (rules and schedules, 1-minute clock)"
    fi

    # Push bans to Cloudflare keeps the list at Cloudflare in step with CrowdSec's bans (every CLOUDFLARE_BOUNCER_INTERVAL s while it is on)
    (
        trap 'kill "${_sleep_pid:-}" 2>/dev/null; exit 0' TERM INT
        set +e
        while true; do
            _cloudflare_bouncer_tick
            sleep 10 & _sleep_pid=$!
            wait "$_sleep_pid" || true
        done
    ) </dev/null >/dev/null 2>&1 &

    # Periodic cleanup (_api_hourly_cleanup): stale rate-limit files, TOTP tracking, staging left by a crash, long logs.
    # sleep runs as a job so SIGTERM ends the loop at once instead of leaving
    # an hour-long sleep behind when the server stops.
    (
        trap 'kill "${_sleep_pid:-}" 2>/dev/null; exit 0' TERM INT
        while true; do
            sleep 3600 & _sleep_pid=$!
            wait "$_sleep_pid" || true
            _api_hourly_cleanup
        done
    ) &

    # Start the listener in the background and wait on it. A trap cannot run
    # while bash is blocked on a foreground child, so this is what makes
    # SIGTERM (systemd stop, --stop) actually stop the server. socat/ncat
    # invoke this script with --handle-request for every connection.
    [[ "$API_MAX_CHILDREN" =~ ^[0-9]+$ ]] && (( API_MAX_CHILDREN > 0 )) || API_MAX_CHILDREN=64
    # beyond API_MAX_CHILDREN a connection waits in the kernel's queue until a slot is free; socat's own queue is 5
    # connections, and past it the kernel drops a new one (the client tries again after 1, 3, 7 … s and gives up after about
    # two minutes): a burst of 200 left dozens of requests unanswered on a small hub
    local _backlog=$(( API_MAX_CHILDREN * 4 )); (( _backlog < 256 )) && _backlog=256
    local listener_pid
    # the workers (API_WORKERS > 0) and the front that hands them the connections; ncat mode and API_WORKERS=0 read the script per connection
    local _front="$self_path --handle-request"
    [[ "$LISTENER_CMD" == "socat" ]] || API_WORKERS=0
    if (( API_WORKERS > 0 )) && [[ ! -x "$BASE_DIR/.scripts/api-dispatch.sh" ]]; then
        echo "warning: .scripts/api-dispatch.sh is missing or not executable: one process per request instead of a worker pool"; API_WORKERS=0
    fi
    # a unix socket's path holds 108 bytes at most: past that the workers' socat could never bind and spun instead
    if (( API_WORKERS > 0 )); then
        local _wsock="${API_RUN_DIR:-$BASE_DIR/.data/run-$$}/w${API_WORKERS}.sock"
        if (( $(printf '%s' "$_wsock" | wc -c) > 100 )); then
            echo "warning: the workers' socket path ($_wsock) is longer than 100 bytes: one process per request instead of a worker pool (a shorter install path brings the pool back)"; API_WORKERS=0
        fi
    fi
    if (( API_WORKERS > 0 )); then
        _api_workers_start
        _front="$BASE_DIR/.scripts/api-dispatch.sh"
        echo "API workers: $API_WORKERS (API_WORKERS; 0 = one process per request)"
    fi
    if [[ "$LISTENER_CMD" == "socat" ]]; then
        if [[ "$API_TLS_ENABLED" == "true" ]]; then
            if [[ ! -f "$API_TLS_CERT" ]] || [[ ! -f "$API_TLS_KEY" ]]; then
                echo "ERROR: TLS enabled but certificate/key not found." >&2
                echo "  Certificate: $API_TLS_CERT" >&2
                echo "  Key: $API_TLS_KEY" >&2
                echo "  Generate with: openssl req -x509 -newkey rsa:4096 -keyout server.key -out server.crt -days 365 -nodes -subj '/CN=dcs-api'" >&2
                exit 1
            fi
            echo "Starting API server on https://${API_BIND}:${API_PORT} (TLS enabled)"
            socat "OPENSSL-LISTEN:${API_PORT},bind=${API_BIND},reuseaddr,fork,max-children=${API_MAX_CHILDREN},backlog=${_backlog},cert=${API_TLS_CERT},key=${API_TLS_KEY},verify=0" \
                EXEC:"$_front",nofork &
        else
            echo "Starting API server on http://${API_BIND}:${API_PORT}"
            socat "TCP-LISTEN:${API_PORT},bind=${API_BIND},reuseaddr,fork,max-children=${API_MAX_CHILDREN},backlog=${_backlog}" \
                EXEC:"$_front",nofork &
        fi
    else
        # ncat mode
        ncat -l -k "${API_BIND}" "${API_PORT}" -m "${API_MAX_CHILDREN}" -e "$self_path --handle-request" &
    fi
    listener_pid=$!

    local rc=0
    if (( ${API_WORKERS:-0} > 0 )); then
        # a worker that died (killed, out of memory) is replaced while the front runs; the front's own end ends the loop.
        # The pause is a job waited for, not a foreground sleep: bash runs a trap only once its foreground child has ended,
        # so a plain `sleep 2` held a restart (SIGUSR1) or a stop (SIGTERM) back for up to two seconds, during which the old
        # listener still answered as if it had restarted (the shutdown ends this job with the others)
        while kill -0 "$listener_pid" 2>/dev/null; do _api_workers_tend; sleep 2 & wait "$!" 2>/dev/null || true; done
    fi
    wait "$listener_pid" || rc=$?
    # The listener exited on its own (port in use, crash): tidy up and report
    _api_shutdown_children
    rm -f "$API_PID_FILE" "$API_CAPS_FILE"
    return "$rc"
}

# Stop the listener and the background loops started by start_server
_api_shutdown_children() {
    # runs from signal traps of a shell with errexit on: no step of it may end the process (a restart that dies half way
    # leaves no API at all)
    set +e
    echo ""
    echo "  Shutting down API server..."
    local pids
    pids=$(jobs -p 2>/dev/null)
    [[ -n "$pids" ]] && kill $pids 2>/dev/null
    pkill -TERM -P "${BASHPID:-$$}" 2>/dev/null || true
    # Request handlers are socat's children, not ours: end the long-lived ones
    if [[ -n "${self_path:-}" ]]; then
        local self_re
        self_re=$(printf '%s' "$self_path" | sed 's/[][\.*^$+?(){}|]/\\&/g')
        pkill -TERM -f -- "${self_re} --handle-request$" 2>/dev/null || true
        # only this listener's own workers: a listener that already replaces this one has workers of its own
        if [[ -n "${API_RUN_DIR:-}" ]]; then
            local _wrun_re; _wrun_re=$(printf '%s' "$API_RUN_DIR" | sed 's/[][\.*^$+?(){}|]/\\&/g')
            pkill -TERM -f -- "${self_re} --worker ${_wrun_re}/" 2>/dev/null || true
        fi
    fi
    # a worker that was cut off mid-request leaves its socat behind: nothing may keep listening on a socket of the run dir
    if [[ -n "${API_RUN_DIR:-}" ]]; then
        local run_re
        run_re=$(printf '%s' "$API_RUN_DIR" | sed 's/[][\.*^$+?(){}|]/\\&/g')
        pkill -TERM -f -- "^socat .*UNIX-LISTEN:${run_re}/w[0-9]+\.sock," 2>/dev/null || true
        rm -rf "$API_RUN_DIR" 2>/dev/null
    fi
    # The DDNS loop is no job of this process when a settings change or the wizard started it from a request: it (and
    # its sleep) would run on, next to the loop of the listener that replaces this one
    local _dp
    _dp=$(cat "$DDNS_PID_FILE" 2>/dev/null || true)
    if [[ "$_dp" =~ ^[0-9]+$ ]] && tr '\0' ' ' < "/proc/${_dp}/cmdline" 2>/dev/null | grep -q 'api-server\.sh'; then
        pkill -TERM -P "$_dp" 2>/dev/null || true
        kill -TERM "$_dp" 2>/dev/null || true
    fi
    rm -f "$DDNS_PID_FILE" 2>/dev/null
}

# SIGHUP: restart in place. The listener and helper loops are stopped, the
# port is waited for, then the script re-executes itself with its original
# arguments — same PID, so a systemd unit does not even notice.
# _api_scrub_before_exec — a process that re-executes itself keeps every descriptor a handler left open and every
# variable an earlier run exported; after weeks of in-place restarts git, tar and friends then fail in ways a fresh
# start never shows. Everything above stderr is closed and the git environment forgotten before the exec.
_api_scrub_before_exec() {
    local fd
    for fd in /proc/$$/fd/*; do fd=${fd##*/}; [[ "$fd" =~ ^[0-9]+$ ]] && (( fd > 2 )) && { exec {fd}>&- ; } 2>/dev/null; done
    unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_OBJECT_DIRECTORY GIT_COMMON_DIR 2>/dev/null || true
}

_api_reexec() {
    set +e
    echo ""
    echo "  Restarting API server in place ..."
    _api_shutdown_children
    wait 2>/dev/null || true
    local i self
    for i in $(seq 1 50); do
        [[ -z "$(_api_port_listeners "$API_PORT")" ]] && break
        sleep 0.1
    done
    [[ -n "$(_api_port_listeners "$API_PORT")" ]] && { _api_reclaim_port "$API_PORT" || true; }
    rm -f "$API_PID_FILE" "$API_CAPS_FILE"
    self="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
    _api_scrub_before_exec
    exec "$self" ${_API_ARGV[@]+"${_API_ARGV[@]}"}
}

# =============================================================================
# WORKERS — a pool of pre-read copies of this script, one request at a time each
# =============================================================================
# Reading this script is what a request costs most on a small VM (about a tenth of a second of CPU, cached answer or
# not). With API_WORKERS > 0 (the default) start_server keeps that many copies of itself running; each listens on its
# own unix socket and answers one connection at a time, in a subshell, so nothing a handler sets, changes or traps
# survives into the next request. The front (socat with .scripts/api-dispatch.sh) hands each connection to a free
# worker and sends the client's address first. A worker renews itself after API_WORKER_REQUESTS answers (exec in
# place: same PID, fresh memory); the server starts a replacement for one that dies. API_WORKERS=0 is the old way:
# the whole script read again for every connection.
_api_worker_loop() {
    local sock="$1" served=0 first req sp="" stamp zfd="" _g _gmax
    # this worker read .env when it started; the stamp says when (two seconds early: a save in that very moment counts as
    # newer). ".env newer than the stamp" is a test bash does itself, so a request pays nothing for it — parsing .env on
    # every request cost a hub with a long .env more than the pool saved
    stamp="${sock%.sock}.stamp"; touch -d '2 seconds ago' "$stamp" 2>/dev/null || : > "$stamp"
    # the socat waiting for a connection is a child of ours: it goes with us (a listener with nobody behind it would stay for good)
    trap 'kill -TERM "${sp:-}" 2>/dev/null; rm -f "$sock" "$stamp"; exit 0' TERM INT HUP
    _api_close_inherited_fds
    # a descriptor nothing ever writes to: a timed read on it is a pause without starting a process (sleep is one per pause)
    if mkfifo "${sock%.sock}.z" 2>/dev/null; then exec {zfd}<>"${sock%.sock}.z"; rm -f "${sock%.sock}.z"; fi
    while :; do
        # one connection: socat puts the client's bytes on the coprocess's output and our answer on its input
        local _t0="${EPOCHREALTIME/[.,]/}"
        coproc _WSOC { exec socat -t 900 -T "${API_WORKER_IDLE_SECS:-900}" "UNIX-LISTEN:$sock,unlink-early,umask=077,backlog=32" STDIO 2>/dev/null; }
        local rfd wfd; sp="$_WSOC_PID"
        # bash closes a coprocess's own descriptors in every subshell: plain copies of them are what the request's subshell can use
        # shellcheck disable=SC1083   # {name}<& is bash 4.1+ syntax shellcheck does not read
        exec {rfd}<&"${_WSOC[0]}" {wfd}>&"${_WSOC[1]}"
        eval "exec ${_WSOC[0]}<&- ${_WSOC[1]}>&-"      # the originals go (a plain number cannot stand in {name}<&-; eval it is)
        first=""
        # wait for the client (no timeout: a worker waits as long as it must); the front sends the client's address first
        if IFS= read -r first <&"$rfd"; then
            first="${first%%$'\r'}"
            if [[ "$first" == "DCS-PEER "* ]]; then
                SOCAT_PEERADDR="${first#DCS-PEER }"; export SOCAT_PEERADDR
                req=""; IFS= read -r -t 10 req <&"$rfd" || req=""
            else
                SOCAT_PEERADDR=""; export SOCAT_PEERADDR; req="$first"
            fi
            if [[ -n "$req" ]]; then
                # the .env of now, not of the worker's start: a setting saved through another worker since then is read first
                ( set +e; [[ -n "$zfd" ]] && exec {zfd}<&-
                  [[ "$BASE_DIR/.env" -nt "$stamp" ]] && _api_load_env_file "$BASE_DIR/.env"
                  _API_PREREAD_SET=1; _API_PREREAD_LINE="$req"; handle_request ) <&"$rfd" >&"$wfd"
                served=$(( served + 1 ))
            fi
        elif [[ -n "$_t0" ]] && (( ${EPOCHREALTIME/[.,]/} - _t0 < 500000 )); then
            # socat ended at once, with no connection (it could not bind the socket): a pause, not a loop that spins
            if [[ -n "$zfd" ]]; then read -r -t 1 -u "$zfd" _ 2>/dev/null; else sleep 1; fi
        fi
        exec {rfd}<&- {wfd}>&-
        # the answer is written (the subshell is gone); socat ends as soon as the front has read it. A detached job the handler left
        # behind may still hold the pipe open, which would keep this worker from its next connection: a few seconds, then it is cut off
        if [[ -n "$zfd" ]]; then _gmax=1000; else _gmax=250; fi
        for (( _g = 0; _g < _gmax; _g++ )); do
            kill -0 "$sp" 2>/dev/null || break
            if [[ -n "$zfd" ]]; then read -r -t 0.005 -u "$zfd" _ 2>/dev/null; else sleep 0.02; fi
        done
        kill -TERM "$sp" 2>/dev/null; wait "$sp" 2>/dev/null; sp=""
        # a renewal after the quota, or as soon as .env changed: a key removed from it would otherwise linger in this worker
        if (( served >= ${API_WORKER_REQUESTS:-500} )) || [[ "$BASE_DIR/.env" -nt "$stamp" ]]; then
            _api_scrub_before_exec
            exec "$_self_path" --worker "$sock"
        fi
    done
}
# start_server's part: the pool, and a replacement for a worker that died (called every few seconds while the front runs)
_api_workers_start() {
    local i
    # A run directory of this process's own (.data/run-<pid>): a listener that replaces this one while it is still shutting
    # down (a self-update, a restart that did not wait) keeps its own sockets, and this one's shutdown takes away only its
    # own. What a listener that is gone left behind is removed here.
    local _old _opid
    for _old in "$BASE_DIR"/.data/run-* "$BASE_DIR/.data/run"; do
        [[ -d "$_old" ]] || continue
        _opid="${_old##*/run-}"; [[ "$_old" == */run ]] && _opid=""
        [[ "$_opid" =~ ^[0-9]+$ ]] && kill -0 "$_opid" 2>/dev/null && continue
        rm -rf "$_old" 2>/dev/null
    done
    API_RUN_DIR="${API_RUN_DIR:-$BASE_DIR/.data/run-$$}"
    rm -rf "$API_RUN_DIR"; mkdir -p "$API_RUN_DIR"; chmod 700 "$API_RUN_DIR"
    export DCS_API_RUN_DIR="$API_RUN_DIR"
    API_WORKER_PIDS=()
    for (( i = 1; i <= API_WORKERS; i++ )); do
        "$self_path" --worker "$API_RUN_DIR/w$i.sock" >> "$API_LOG_FILE" 2>&1 &
        API_WORKER_PIDS+=("$!")
    done
}
_api_workers_tend() {
    local i
    for (( i = 1; i <= API_WORKERS; i++ )); do
        kill -0 "${API_WORKER_PIDS[i-1]:-0}" 2>/dev/null && continue
        "$self_path" --worker "$API_RUN_DIR/w$i.sock" >> "$API_LOG_FILE" 2>&1 &
        API_WORKER_PIDS[i-1]="$!"
    done
}

# =============================================================================
# ENTRY POINT
# =============================================================================

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    # Unattended update (schedules, automations): runs outside the listener's process tree
    if [[ "${SELF_UPDATE_JOB:-false}" == "true" ]]; then
        set +e
        _self_update_job
        exit $?
    fi

    # Unattended image updates (the image-update schedule): pull what changed, recreate what runs the old copy
    if [[ "${IMAGE_UPDATE_JOB:-false}" == "true" ]]; then
        set +e
        _image_update_job "$([[ "${IMAGE_UPDATE_PULL_ONLY:-false}" == "true" ]] && echo false || echo true)"
        exit $?
    fi

    # One look at the waiting OS updates, in the foreground (what GET /system/os-updates answers from); prints it
    if [[ "${OS_UPDATES_JOB:-false}" == "true" ]]; then
        set +e
        _os_updates_check
        exit $?
    fi

    # Fleet commands used by setup.sh (and by hand): join a hub, mint a join code
    if [[ -n "${FLEET_CLI:-}" ]]; then
        set +e
        _fleet_cli "$FLEET_CLI"
        exit $?
    fi

    # Internal: one of the server's worker processes (see WORKERS above)
    if [[ "$WORKER_MODE" == "true" ]]; then
        set +e
        [[ -n "${_self_path:-}" ]] || _self_path="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
        _api_worker_loop "$WORKER_SOCK"
        exit 0
    fi

    # Internal: called by socat/ncat for each incoming connection
    if [[ "$HANDLE_REQUEST" == "true" ]]; then
        # Disable errexit for request handling — we handle errors via JSON responses
        set +e
        _api_close_inherited_fds
        handle_request
        exit 0
    fi

    if [[ "$DAEMON_MODE" == "true" ]]; then
        start_server >> "$API_LOG_FILE" 2>&1 &
        bg_pid=$!
        disown
        # Overwrite PID file with the actual background PID
        echo "$bg_pid" > "$API_PID_FILE"
        echo "API server started in background (PID: $bg_pid)"
        echo "Log: $API_LOG_FILE"
        echo "Stop: $0 --stop"
    else
        start_server
    fi
fi
